"""Сменный отчёт по станку в стиле ручного «Отчёта производства за смену».

Ключевое отличие от подсчёта по интервалам сообщений: время работы станка
берётся ИЗ СЧЁТЧИКА и нормы выработки, а не из таймлайна чата:

    Выпуск, узл.    = счётчик_конечное − счётчик_начальное
    Время работы, ч = Выпуск / (узлов в минуту) / 60         (см. machine_rates)

Норма смены: станок 12 ч (07:00–19:00), оператор 11,25 ч. Обед — всегда
45 минут, входит в ПРОСТОЙ станка (станок стоит) и не входит в часы
оператора. В часы оператора идут все его операции, включая подмены на других
станках. Если смена оператора короче 12 ч, остаток ставится как отсутствие
оператора. Всё, что станок не работал, — простой; если учтённые остановки не
покрывают простой, разница помечается как простой без указанной причины.

Модуль детерминированный и не зависит от источника: на вход идёт структура
(её готовит ИИ из переписки/фото либо ручной парсер).
"""
from __future__ import annotations

from dataclasses import dataclass, field, replace
from typing import Dict, List, Optional, Tuple

import re

from . import machine_rates

MACHINE_SHIFT_HOURS = 12.0
OPERATOR_SHIFT_HOURS = 11.25
LUNCH_FULL_H = 0.75          # 45 мин — обед всегда 45 минут

# ПЛАВАЮЩИЙ ОБЕД (введён на участке 16.09.2026): операторы обедают в разное
# время и на свой перерыв ПЕРЕДАЮТ станок коллеге, машина продолжает работать.
# Тогда строки «простой обед» в отчёте нет — станок время не терял.
# Эталон пользователя за 16.09: у ст.321/151/251 строки обеда НЕТ, а у ст.98
# (там обед никто не принимал) есть 0,75 ч.
#
# Признаки в тексте мастера: «не останавливает N 151», «принимает N 251»,
# «принял под контроль машины 151», «передал навивку шпулей Петровскому О.»,
# «под контролем Погодиной Л.Е.».
# Записи, которыми мастер ЗАКРЫВАЕТ смену: заполнение журнала, чата, отчёта.
# После такой записи человек уходит, и до 19:00 у станка его уже нет.
# Прогон 16.09.2026, ст.321: последняя запись Демидова — «16:00-16:15
# заполнение журнала и чата», а ни «19:00», ни «конец смены» в разделе НЕТ.
# Модель всё равно вернула operator_shift_end = «19:00», код принял полную
# смену, хвост 16:15–19:00 не стал «отсутствием оператора», баланс станка
# съехал на 9,13 ч, и 2,87 ч ушли в «причина не указана». В эталоне
# пользователя: «3,78 простой отсутствие оператора».
# «конец смены», «19:00 конец смены», «в 19.00» — подтверждение, что человек
# доработал до конца смены станка (см. model_shift_end_unconfirmed).
_SHIFT_END_RE = re.compile(r"конец\s*смены|19\s*[:.]\s*00", re.IGNORECASE)

_CLOSING_RE = re.compile(
    r"заполн\w*\s+(?:журнал|чат|отчёт|отчет)|журнал\w*\s+и\s+чат"
    r"|чат\w*\s+и\s+журнал|отчёт\w*\s+в\s+чат", re.IGNORECASE)

# Прикрытие коллеги НА ВРЕМЯ ЕГО ОБЕДА — не привлечённый персонал, а взаимный
# обмен: каждый из двоих получает зеркальные часы на своей машине.
# Прогон 16.09.2026, ст.321: «принял 321 на время обеда Демидова Е.» — 0,75 ч
# Петровского попали в «Работу привлекаемого персонала» (3,02 ч), а в эталоне
# пользователя там только «2,17 Гузяев — подмена шпулей 93 шт», и эти 0,75 ч
# стоят в блоке Демидова его own-строкой «0,75 работа на машине №151 (принял
# под контроль у Петровского во время обеда)».
# Отличие от обычной помощи (там часы считаются): 251 за тот же день —
# «2,52 Петровский — замена шкулярника 101 шт» в эталоне ЕСТЬ, это работа в
# середине смены, а не прикрытие перерыва.
_LUNCH_COVER_RE = re.compile(
    r"(?:на\s+время|во\s+время|на\s+период)\s+(?:обед\w*|перерыв\w*)"
    r"|(?:обед\w*|перерыв\w*)[^.\n]{0,60}?(?:принял|принимает|подменял|"
    r"подменил|прикрыл|замещал)", re.IGNORECASE)

# Маркер обязан стоять РЯДОМ со словом «обед»/«перерыв», иначе «согласно
# записи наладчика — машину приняла и пускаю» (01.09, ст.251) ошибочно
# отменяло строку обеда у станка, где он действительно был.
# ⚠️ Промежуток между словами — [^\n]{0,90}, БЕЗ запрета точки: мастера пишут
# инициалы («Петровского О.», «Демидов Е.»), и запрет точки рвал фразу пополам,
# из-за чего передача станка не распознавалась вовсе (прогон 16.09.2026).
_LUNCH_HANDOVER_RE = re.compile(
    r"(?:обед|перерыв|перекур)[^\n]{0,90}?"
    r"(?:не\s+останавлив\w*|принимает|принял\w*|под\s+контрол\w*|"
    r"переда\w+)",
    re.IGNORECASE)
# То же, но в обратном порядке: «Петровский О не останавливает N 151 …
# на время обеденного перерыва» (блок «Данные из чата» за 16.09.2026).
_LUNCH_HANDOVER_RE2 = re.compile(
    r"(?:не\s+останавлив\w*|принимает|принял\w*|под\s+контрол\w*|"
    r"переда\w+)[^\n]{0,90}?(?:обед|перерыв)",
    re.IGNORECASE)
# Прямая передача машины чужим рукам: «Передаю машину под наблюдение
# Петровскому» / «Взял 151 машину под наблюдение на время обеда» (прогон
# 20.09.2026, ст.151). Раньше признак искался ONLY в причине одного события,
# а мастер пишет передачу ОТДЕЛЬНЫМ сообщением — строка «простой обед 0,75»
# оставалась, хотя станок в это время вели и он не стоял.
_LUNCH_TAKEOVER_RE = re.compile(
    r"(?:переда\w+|взял\w*|принял\w*|принима\w*|принимает|беру|берёт)\w*"
    r"[^\n]{0,40}?машин\w*"
    r"|(?:машин\w*)[^\n]{0,40}?(?:передан\w*|переда\w+|принят\w*|"
    r"под наблюдени\w+)",
    re.IGNORECASE)
_LUNCH_WORD_RE = re.compile(r"обед|перерыв|перекур", re.IGNORECASE)
LUNCH_SHORT_H = 0.75         # оставлено для совместимости: обед всегда 45 мин
TOLERANCE_H = 20.0 / 60.0    # допуск 20 мин — ЕДИНЫЙ и для недостатка, и для
                             # переработки (правило пользователя 28.08)

# Предел «тихого» добора часов оператора. Приказ владельца от 30.09.2026 по
# вопросу №140 (дословно): остаток часов оператора добирать строкой «контроль
# за работой машины», «но если расхождение не прям большое (до 1-1,5 часа)».
# Разрыв больше 1,5 ч добором не закрывается: он остаётся как есть и виден
# красной строкой «РАСХОЖДЕНИЕ: оператор −X ч» (приказ 28.09.2026 «не нужно их
# добивать до 11,25» для больших расхождений в силе).
OPERATOR_PAD_MAX_H = 1.5

# Правила часов (со слов пользователя, участок намотки):
#   • станок  — норма 12 ч (07:00–19:00);
#   • обед    — ВСЕГДА 45 мин и ВХОДИТ в простой станка (станок стоит);
#   • оператор — норма 11,25 ч (12 − обед), обед в его время не входит, зато
#     входят ВСЕ его операции: работа за станком, чинка, наладка, подмены,
#     в том числе подмены на ДРУГИХ станках;
#   • если смена оператора короче 12 ч (например 8-часовая), остаток смены
#     станка ставится как отсутствие оператора.
LUNCH_LABEL = "обед (станок стоит)"
# Формулировка как в эталоне пользователя (лист 27.08, ст.111/121):
# «простой наладка / инженерная служба».
ENGINEERING_LABEL = "наладка / инженерная служба"
# Обычная наладка станка (наладчик участка). Внутри этого времени машина может
# крутиться: наладчик прогоняет пробные узлы, и счётчик сдвигается. Такое время
# уходит в работу станка и вычитается из наладки — см. _naladka_minus_test_run.
NALADKA_LABEL = "наладка/переналадка"
# Подмена (заправка полотна) НА ЭТОМ ЖЕ станке: по правилу участка это делается
# на работающей машине, поэтому время подмены идёт во ВРЕМЯ РАБОТЫ станка, а не
# в простой. Уход на подмену на ДРУГОЙ станок (other_machine) — это отдельный
# случай (отсутствие оператора здесь), см. TechStop.elsewhere.
SUB_LABEL = "подмена (заправка полотна)"
# Правило пользователя 03.09.2026: «при подстановке или подмене бобин машина
# тоже в стопе, это время идёт в простой; при подмене шпулярника тоже машина в
# стопе и идёт простой». Ярлыки отдельные, чтобы в отчёте было видно, ЧТО
# делали (пользователь просит писать операции его словами, правило Д).
#
# Приказ владельца 30.09.2026: «замена сырья это замена шпулярника». В его
# ручном файле за 29.09 станок 321 имеет строку «замена шпулярника» 7,32 ч в
# технических остановках при пустых «подмены, ч» и «Кол-во подмен», а мастер
# писал «замена 21 бобины», «замена 22 бобины», … То есть то же самое дело
# называется операцией на шпулярнике, а не «подстановкой бобин». Слово «бобин»
# в ярлыке ОСТАЛОСЬ намеренно: по нему гейт `is_material_swap` не пускает строку
# в подмены человека (см. `_SUBMEN_MARKERS`), и часы не исчезают из колонки
# «Технические остановки».
BOBBIN_LABEL = "замена шпулярника (замена бобин, станок стоит)"
SPOOLER_STOP_LABEL = "подмена шпулярника (станок стоит)"
# Часы, отработанные оператором на ЧУЖОМ станке и вернувшиеся в его блок
# отдельной строкой (правило Р23). Префикс ярлыка нужен ещё и в расчёте: эти
# минуты человек провёл не у своей машины, поэтому в «контроль за работой
# машины» они второй раз не идут — см. away_own_hours.
ELSEWHERE_WORK_LABEL = "работа на машине №"
# Часы оператора, не разложенные по названным операциям: он был у машины и вёл
# её работу. Ярлык расширяется операциями без времени — см. control_label.
CONTROL_LABEL = "работа по контролю за работой машины"
# Простой станка, который в переписке ничем не объяснён.
UNEXPLAINED_LABEL = "причина не указана"
# Ярлыки «причину не распознали». Это НЕ название операции, а заглушка: по ним
# нельзя склеивать разные дела мастера в одну строку (см. operator_work_by_reason).
OTHER_LABEL = "прочее"
NO_REASON_LABEL = "без указанной причины"

# Станок отдан в инженерную службу: если он при этом не работал по счётчику,
# весь день (12 ч) — ремонт, оператора и обеда на нём нет.
_ENGINEERING_MARKERS = ("инженерн", "инж. служб", "инж служб", "инж.служб")

# Правило участка (26.08.2026): если за смену по станку НЕТ вообще никаких
# показаний счётчика (ни начального, ни конечного), машина не производила —
# значит она весь день в наладке или в инженерной службе. Различаем по тому,
# кто фигурирует в обсуждении:
#   • Пронкин / Шалыминов → наладка (оператор при машине, 11,25 ч + обед);
#   • Каленюк            → инженерная служба (ремонт 12 ч, оператора нет).
_NALADKA_PEOPLE = ("пронкин", "шалыминов")
_ENGINEERING_PEOPLE = ("каленюк",)

# Причины простоя, при которых ОПЕРАТОР не работал (не идут в его время
# и создают недостаток времени). Всё остальное (навивка, подмена шпулей,
# наладка, чинка, срезы) — это работа оператора при остановленном станке.
_ABSENCE_MARKERS = ("отсут", "нет опер", "без опер", "ушёл", "ушел", "прогул",
                    "не вышел", "опоздал")

# Оператора перевели на другой станок: часы засчитываются ТОМУ станку.
# Номер станка ищем в формулировке («навивка шпулей на 251», «стоп чинка
# на √111», «оператор на подмену 251 машины») — одного слова «переведён»
# мало, оно бывает и про операцию.
#
# \b перед «на» обязателен: без него внутри слова «подме-НА 90 шп.» находится
# мнимое «на 90», и подмена превращается в уход на несуществующий станок 90.
_ELSEWHERE_RE = (r"\bна\s*(?:подмен\w*\s*(?:на\s*)?|машин\w*\s*|станк\w*\s*)?"
                 r"[√#№]?\s*(\d{2,4})\s*(?:машин\w*|станк\w*)?")

SHIFT_START_H = 7.0          # смена начинается в 07:00
LUNCH_START_SPAN = 5.0       # обед около 12:00 = 5 ч от начала смены

# Мастер иногда называет вместо интервала ВЕСЬ рабочий день: «замена
# шпулярника в течении всей смены», «чинка в теч.смены», «подстановки бобин всю
# смену». Для такого дела окно — вся смена 07:00–19:00, даже если ИИ вернул
# запись без start/end (прогон 24.09.2026 со второго раза).
_WHOLE_SHIFT_RE = re.compile(
    r"в\s*теч[а-яё]*\.?\s*(?:всей\s+)?смен"
    r"|на\s+протяж[а-яё]*\s*(?:всей\s+)?смен"
    r"|(?:всю|целую)\s+смен",
    re.IGNORECASE)

# Классификация причин простоя из сообщений мастеров: (маркеры, ярлык,
# оператор_работал). Порядок важен — первое совпадение выигрывает, поэтому
# сначала идут причины, при которых оператор НЕ работал («ждал задание после
# наладки» — это ожидание, а не наладка), потом его операции.
# ДОТЯГИВАНИЕ — постоянная категория в отчёте пользователя: «простой
# дотягивание» стоит почти каждый день с 19.08 по 14.09 (эталон 14.09, ст.321:
# «6,95 | дотягивание (подстановка сошедших шпулей)» — самая крупная строка дня;
# 08.09: «дотяжка узлов/подстановка сошедших шпулей»; 10.09: «дотягивание
# (замена сошедшей шпулины на половинку)»). Смысл: сошедшую шпулю подставляют
# обратно, чтобы дотянуть ассортимент, станок при этом стоит.
#
# В коде такой категории не было, и часы уходили в безликую «замену шпуль
# (станок стоит)» — название строки отчёта не совпадало с эталоном.
# Гейт _STRETCH_RE объявлен рядом с _CATEGORY_GATES (ему нужны _SPOOL_*_RE).
# «Обрыв нити» — отдельная строка простоя в отчёте пользователя (14.09 ст.151
# «0,35 | простой обрыв», 01.09 ст.151 «0,05 | простой обрыв нити»). В коде
# такой категории не было, и часы уходили в безликую «прочее».
#
# Ставится ПОСЛЕ категорий наладки и чинки: «обрыв, занимается Пронкин» —
# это НАЛАДКА (службу вызвали), «чинка полотна после обрыва нити» — ЧИНКА.
# Новая категория ловит только чистый обрыв, который оператор устранил сам.
THREAD_BREAK_LABEL = "обрыв нити"
# «полотна чистые, без обрывов и дыр» — это НЕ обрыв, а замечание о состоянии.
_THREAD_BREAK_RE = re.compile(
    r"^(?!.*(?:без\s+обрыв|обрывов\s+нет))(?:.*(?:обрыв\w*|оборва\w*))",
    re.IGNORECASE | re.DOTALL)

STRETCH_LABEL = "дотягивание (подстановка сошедших шпулей)"
# Навивка/намотка шпулей — операция ПРИ РАБОТАЮЩЕЙ машине (см. _RUNNING_LABELS).
# Своя метка нужна, чтобы её можно было поставить записи, которую классификатор
# по тексту не узнал, но модель назвала род работы явно (см. _events_to_stops).
WINDING_LABEL = "навивка/намотка шпулей"
# Снятие/установка валов — операция с ВЫНУЖДЕННОЙ остановкой (валы на ходу не
# трогают) и НАЗВАННОЙ мастером причиной. Без своей категории она уходила в
# «прочее», и в Excel причина терялась (ст.91 за 24.09: «0,25 | прочее»).
SHAFT_LABEL = "снятие и установка валов"
# Намотка полотна (нити, шнура) на вал — станок встаёт сам: полотно заходит на
# вытяжной вал, и дальше не идёт. Своей категории у такой записи не было, слово
# «намот» ловило её в навивке шпулей — параллельной работе ИДУЩЕЙ машины, — и
# простой исчезал совсем (ст.98 за 26.09.2026: «10:00 остановила машину,
# намотало полотно на вытяжной вал, 11:10 машина в работе» = 1,17 ч, а в Excel
# у станка не было ни минуты этого простоя).
SHAFT_WRAP_LABEL = "намотка полотна на вал"
# Остановка по ошибке машины, которую оператор снять не смог (см. категорию
# «ошибк» ниже по файлу): станок стоит, и это названо словом мастера.
MACHINE_ERROR_LABEL = "ошибка машины"

_STOP_CATEGORIES = (
    (("отсут", "нет опер", "без опер", "ушёл", "ушел", "прогул", "не вышел",
      "опоздал"), "отсутствие оператора", False),
    (("ожидан", "ждал", "ждала", "жду", "ждём", "ждем", "нет сырь", "нет матер",
      "нет пряж", "нет задани", "нет нит"),
     "ожидание (задание, наладчик, сырьё)", False),
    (("обед", "перерыв", "перекур"), "перерыв", False),
    # Правило пользователя 03.09.2026: подстановка/подмена бобин и подмена
    # шпулярника — СТАНОК СТОИТ, время идёт в простой. Обе категории стоят
    # РАНЬШЕ параллельной «замены шпулярника / перехода на ассортимент»,
    # иначе «подмена шпулярника» ловится словом «шпулярник» и простой станка
    # исчезает. Гейт _CATEGORY_GATES требует НАЗВАННОЙ операции: «Вес начинки
    # со шпулярника большая» (реальная смена 05.08) — замечание о весе, а не
    # подмена, и станок по нему не останавливается.
    (("бобин", "бабин"), BOBBIN_LABEL, True),
    (("шпулярник",), SPOOLER_STOP_LABEL, True),
    # Параллельная работа при ИДУЩЕЙ машине (см. _RUNNING_LABELS) — это
    # ПЕРЕХОД НА ДРУГОЙ АССОРТИМЕНТ. Слово «шпулярник» само по себе сюда не
    # повод: замена шпулярника названа категорией выше (со своим гейтом на
    # глагол операции), а без гейта сюда уезжала любая запись про шпулярник.
    # Прогон 24.09.2026, ст.111: «обрыв нити со шпулярника, устранил наладчик
    # Пронкин» (6 записей) получало ярлык «замена шпулярника» и статус
    # параллельной работы — хотя по правилу «названа служба наладки — это
    # наладка» (см. THREAD_BREAK_LABEL выше) строка обязана быть наладкой.
    # Голый корень «ассортим» здесь тоже лишний: на смене 22.09.2026 (ст.151) под
    # него попадали «сортировка ченарышей ассортимента ПА187×3» и «чистка машины
    # от загрязнений полиэтиленового ассортимента» — это работа с остатками, а
    # не перестройка, и 1,03 ч чистки молча вписались в «подмены, ч».
    (("переход на", "смена асс", "перезаряд"),
     "замена шпулярника / переход на ассортимент", True),
    # Дотягивание идёт РАНЬШЕ протяжки и замены шпуль: запись мастера обычно
    # содержит оба слова («замена сошедших шпулей», «дотяжка узлов/подстановка
    # сошедших шпулей»), а пользователь называет такую строку дотягиванием.
    # «дотяжк» нужен отдельно от «дотяг»: в эталоне 08.09 мастера пишут
    # «дотяжка узлов/подстановка сошедших шпулей» → «простой дотягивание узлов»,
    # а без него запись уходила в «протяжку узлов» (там маркер «протяж»).
    (("дотяг", "дотяжк", "сошедш", "сошл", "сошёл", "сошел", "сход",
      "подстав", "застрявш"), STRETCH_LABEL, True),
    # Протяжка идёт раньше навивки: «выпустил нитки со стороны шпулей для
    # ручной протяжки» — это протяжка, хотя в тексте есть слово «шпулей».
    (("протяж",), "протяжка узлов", True),
    # Замена шпуль (снять/поставить шпули на станок) — станок при этом СТОИТ,
    # это простой. Отличать от навивки/развивки (намотка запаса) — та идёт
    # параллельно работе. Ловим глаголы замены со словом «шпул».
    # Сюда же СХОД шпуль — правило пользователя (09.09.2026): «при сходе шпулей
    # машина ставится в стоп, как было многократно на 321 машине». Гейт
    # _SPOOL_STOP_RE требует слово «шпул» рядом: «12 ч сошлись» — не сход.
    (("замена шпул", "замену шпул", "смена шпул", "поменя", "заменил шпул",
      "заменила шпул", "менял шпул", "меняю шпул", "смену шпул", "постав"),
     "замена шпуль (станок стоит)", True),
    # Подмена идёт РАНЬШЕ навивки: «подмена шпулей 136 шт» — это подмена
    # (станок стоит), хотя в тексте есть «шпул». Навивка/развивка без слова
    # «подмен» — параллельная подготовка при работающей машине.
    (("подмен", "заправка полот", "заряд"), "подмена (заправка полотна)", True),
    # Наладка датчика схода шпули идёт РАНЬШЕ навивки: в записи есть слово
    # «шпул», и категория навивки перехватывала её. В эталоне пользователя это
    # строка «простой наладка (датчик схода шпули, 08:52-09:20)» (21.08, ст.251)
    # и «Пронкин — наладка (датчик схода шпули x2, протяжка узлов)» (04.09).
    # Разница смысловая: датчик схода — предмет наладки, а не работа оператора.
    (("приёмка наладк", "приемка наладк", "датчик схода", "датчика схода",
      "схода шпули с наладчиком"), "наладка/переналадка", True),
    # Снятие/установка валов — станок стоит (на ходу валы не трогают), и причину
    # мастер называет словами: без категории строка теряла имя в Excel
    # («0,25 | прочее» вместо «0,25 | снятие и установка валов»).
    (("снятие вал", "снятии вал", "сняли вал", "снять вал", "снят вал",
      "установка вал", "установить вал", "поставить вал", "замена вал",
      "поменял вал", "поменяла вал"), SHAFT_LABEL, True),
    # Наладчик стоит РАНЬШЕ чинки: «машину остановил наладчик Пронкин, чтобы
    # не сломать крючки» — это наладка (работа службы наладки), а не чинка
    # оператора. Иначе слово «поломк» уводило часы наладчика в чужую строку и
    # в работу оператора (прогон 01.09, ст.251: 2,25 ч).
    (("наладчик",), "наладка/переналадка", True),
    # Чинку узнаём по ВСЕМ формам слова, а не по одному корню «чинк»: мастер
    # пишет глаголом («продолжаю вырезать и чинить полотно», «продолжаю чинить и
    # спускать узлы», «чиню пропуск рядом», «дыра вычинена»). Без этих форм
    # запись проваливалась в категории ниже — в «протяжку узлов» по слову «узл»
    # (25.09.2026, ст.251: 2,92 ч чинки стояли протяжкой) или в «прочее».
    # «чина» НЕ берём: в нём сидит «начинаю» («начинаю навивку шпулей»).
    (("чинк", "чинит", "чиню", "чиня", "чинил", "чинен",
      "ремонт", "поломк", "сломал", "авари", "пропуск"),
     "чинка/ремонт", True),
    # Заправка НИТЕЙ через валы — это наладка, а не подмена оператора.
    (("налад", "переналад", "настрой", "перезаправ", "заправка нит",
      "заправка основ", "заправ нит", "через вал"),
     "наладка/переналадка", True),
    # ОШИБКА машины, которую не удалось снять: мастер назвал причину одним
    # словом, а сход шпуль в той же строке ОТРИЦАН («ни одна не сошла»).
    # Ставится ПОСЛЕ наладки и чинки — «стоп машина, ошибка… занимается служба
    # наладки» остаётся наладкой, «наладчик исправил ошибки» — наладкой.
    # Без этой строки запись шла в «дотягивание» по слову «сошла», которого на
    # станке не было (25.09.2026, ст.251, 17:49–19:00, 1,18 ч), а после гейта
    # отрицания падала в навивку по слову «шпули» — тоже выдуманную работу.
    (("ошибк",), MACHINE_ERROR_LABEL, True),
    # Обрыв нити, устранённый самим оператором. Стоит ПОСЛЕ наладки/чинки:
    # если в записи назван наладчик или чинка — выигрывает та категория.
    (("обрыв", "оборва"), THREAD_BREAK_LABEL, True),
    (("срез",), "срезы", True),
    (("узл",), "протяжка узлов", True),
    # Внешние причины — не по вине станка и не работа оператора. Маркеры
    # названы прямо словами мастеров: «нет питания», «свет отключили»,
    # «цех встал» (останов всего цеха подачей). Без них такая запись падала в
    # «прочее», где оператор считался занятым (operator_active=True), и часы
    # простоя молча становились часами работы человека.
    (("электр", "свет", "энерг", "воздух", "пар ", "нет питан", "отключ",
      "цех встал", "цех встает", "цех встаёт"), "внешние причины", False),
    # Бумага и порядок на участке — дело, которое мастер назвал сам:
    # «заполнение журнала, сопроводительных листов, бирок», «культура
    # производства», «заполнение журнала, чата» (прогон 24.09.2026, ст.111:
    # 0,67 ч таких строк висели в безликом «прочее», хотя человек описал
    # конкретную работу — правило №5 «причины простоя словами мастеров»).
    (("заполнен", "журнал", "накладн", "бирк", "культура производ",
      "культуры производ", "документ"),
     "документация и культура производства", True),
    # Намотка полотна на вал идёт РАНЬШЕ навивки шпулей: и там и там есть слово
    # «намот», но смысл противоположный. Навивка — запас шпуль, который делают
    # при идущей машине; намотанное на вал полотно машину останавливает.
    (("намотал",), SHAFT_WRAP_LABEL, True),
    # Навивка/развивка — ПРИ РАБОТАЮЩЕЙ машине (см. _RUNNING_LABELS), поэтому
    # она стоит ПОСЛЕДНИМ маркером: названная операция (чинка, наладка, обрыв,
    # сход шпуль, валы) всегда важнее слова про шпулю. Пока категория стояла в
    # середине таблицы, голый корень «шпул» (он же начало слова «шпулярник»)
    # перехватывал чужие записи: «обрыв нити со шпулярника, устранил наладчик
    # Пронкин» (прогон 24.09.2026, ст.111, 6 записей) получал ярлык «навивка»
    # вместо строки наладки, которую требует правило «названа служба наладки —
    # это наладка».
    # Запись про шпулю БЕЗ другой названной операции обязана остаться навивкой,
    # а не съехать в «прочее»: «Вес начинки со шпулярника большая» (реальная
    # смена 05.08) — замечание, станок на нём не стоит, а неизвестную причину
    # код по умолчанию считает остановкой (unknown_is_stop).
    # Если модель назвала род работы явно (kind «навивка»), ярлык ставится и без
    # глагола — см. winding_kind в _events_to_stops.
    (("навив", "намот", "шпул", "завив", "навит", "развит"), WINDING_LABEL, True),
)

# Короткие маркеры, которые нельзя искать «где угодно в слове»: «жду» есть
# внутри «меЖДУ», «пуск» — внутри «выПУСК». На реальной смене 24.08 из-за
# этого «отогнуло водилки между 2 и 3 полотном» попало в «ожидание», и
# 4,75 ч чинки превратились в недостаток времени оператора. Поэтому для них
# требуем начало слова; длинные корни («налад», «протяж») ищем как раньше.
_WORD_START_MARKERS = frozenset((
    "жду", "ждём", "ждем", "ждал", "ждала", "пуск", "обед", "узл", "свет",
    "заряд", "срез",
))

# «чинк» — отдельный случай: внутри слова «начинка» он тоже находится («Вес
# начинки со шпулярника большая», реальная смена 05.08), и тогда обычная работа
# превращалась в чинку станка. Но и требовать НАЧАЛО слова нельзя — есть живое
# «починка». Поэтому запрещаем ровно один префикс: «на».
#
# Формы глагола идут вместе с корнем: «чинка сильнее подмены/навыки» — правило
# смысла, а не написания. Запись «подмена полотна, чиню пропуск» остаётся чинкой
# и в том виде, где мастер назвал её глаголом (25.09.2026, ст.251).
_REPAIR_RE = re.compile(r"(?<!на)(?:чинк|чинит|чиню|чиня|чинил|чинен)")

# ——— Бобины и шпулярник (правило пользователя 03.09.2026) ———
#
# «При подстановке или подмене бобин машина тоже в стопе, это время идёт в
# простой; при подмене шпулярника тоже машина в стопе и идёт простой».
# Одного существительного мало: в переписке «шпулярник» и «бобины» встречаются
# и без операции («Вес начинки со шпулярника большая» — 05.08). Поэтому нужен
# ГЛАГОЛ операции рядом (до 30 символов, внутри одного предложения).
_SWAP_VERBS = (r"подмен\w*", r"замен\w*", r"смена", r"смену", r"поменя\w*",
               r"меня[юел]\w*", r"перезаряд\w*", r"снял\w*", r"снят\w*",
               r"сним\w*", r"постав\w*", r"подстав\w*", r"подстановк\w*",
               r"перестав\w*", r"навеси\w*", r"навесил\w*", r"довеси\w*",
               r"зарядил\w*", r"заряжа\w*",
               # «подвязывание нитей со шпулярника с нитями распределителя»
               # (22.09.2026, ст.151, 14:16–16:43) — станок в это время стоит:
               # без нитей в распределителе полотно не вяжется. Без глагола
               # запись уезжала в параллельную «замену шпулярника», и 2,45 ч
               # подмены исчезали из отчёта.
               r"подвяз\w*")


def _pair_re(verbs, nouns, window: int = 30) -> "re.Pattern":
    """Регэксп «глагол рядом с существительным» в любом порядке.

    window — сколько символов ТУЖЕ этой фразы (дальше точки, точки с запятой
    и восклицания нет) может стоять между глаголом и существительным.

    Для схода шпуль окно шире (см. _SPOOL_OFF_RE): мастер перечисляет номера
    сошедших шпуль, и между «сошли» и «шпули» встает весь список.
    """
    v, n = "|".join(verbs), "|".join(nouns)
    return re.compile(rf"(?:{v})[^.;!?]{{0,{window}}}(?:{n})"
                      rf"|(?:{n})[^.;!?]{{0,{window}}}(?:{v})")


_BOBBIN_SWAP_RE = _pair_re(_SWAP_VERBS, (r"бобин\w*", r"бабин\w*"))
_SPOOLER_SWAP_RE = _pair_re(_SWAP_VERBS, (r"шпулярник\w*",))

# ——— Сход шпуль (правило пользователя 09.09.2026) ———
#
# «При сходе шпулей машина ставится в стоп, как было многократно на 321 машине».
# Одного корня «сошл» мало: он есть в «часы сошлись», «данные не сошлись».
# Поэтому рядом нужно слово про шпулю — иначе это не сход.
#
# Слово мастер пишет НЕ только полностью: «сошли 4 и 5 шп. Ср. сч. 524»,
# «сошла 28 шп Ср. сч. 608». Без сокращения «шп» такая запись не узнавалась ни
# сходом, ни заменой шпуль и падала в «прочее», где оператор считается занятым:
# 1,17 ч названного схода шпуль на ст.321 за 24.09.2026 молча переехали в
# надуманное «отсутствие оператора», а 30 одинаковых записей того же станка
# остались дотягиванием. «шп» ищем только целым словом — внутри «шпулярник»
# его нет (там после «шп» стоит «л»), и шпулярник остаётся своей категорией.
#
# Окно между глаголом и существительным для схода — шире обычных 30 символов:
# «сошли 41,42,43,45,46,47,48, 49,50,51 шпули» (32 символа до слова «шпули») —
# тот же сход, что и «сошли 37,38,39,40 шпули», но при окне в 30 вылетал в
# параллельную навивку, и 1,12 ч простоя станка исчезали из отчёта.
_SPOOL_NOUNS = (r"шпул\w*", r"шт\b", r"штук\w*", r"шп\b")
_SPOOL_OFF_RE = _pair_re((r"сошл\w*", r"сош[её]л", r"сход\w*", r"скинул\w*"),
                         _SPOOL_NOUNS, window=60)
# «Подставляю 8 шпулей», «Подставил. Машина в работе» — вторая половина того же
# простоя. Своей категории не даём: это та же «замена шпуль (станок стоит)».
_SPOOL_PUT_RE = _pair_re((r"подстав\w*", r"постав\w*", r"меня[юел]\w*",
                          r"замен\w*"), _SPOOL_NOUNS, window=60)
_SPOOL_STOP_RE = re.compile(
    rf"{_SPOOL_OFF_RE.pattern}|{_SPOOL_PUT_RE.pattern}"
    r"|замен\w*\s+шпул|смен\w*\s+шпул|поменя\w*\s+шпул")

# Гейт категории «дотягивание» (см. STRETCH_LABEL выше по файлу): одного корня
# «дотяг» мало («дотянул до конца смены» — не операция), нужна названная работа:
# сошедшие/застрявшие шпули, подстановка, дотяжка узлов.
# Отрицательный просмотр «нет слова налад» впереди обязателен: «приёмка наладки
# датчика схода шпули с наладчиком Пронкиным» (эталон 21.08) и «наладка (сошла
# шпуля, неоднократно; передал наладчику Шалыминову)» (эталон 26.08) — это
# НАЛАДКА, и в отчёте пользователя они стоят в простоях как «простой наладка»,
# а исполнитель — в привлекаемом персонале. Дотягивание — работа ОПЕРАТОРА по
# подстановке шпуль, а не предмет наладки.
_STRETCH_RE = re.compile(
    r"^(?!.*налад)"
    # Сход ОТРИЦАН — значит подставлять сошедшую шпулю не из-за чего. Прогон
    # 25.09.2026, ст.251 17:49–19:00: «ошибка не скидывается, все шпули на
    # месте, ни одна не сошла» → 1,18 ч встали строкой «дотягивание
    # (подстановка сошедших шпулей)», хотя ни одна шпуля не сходила.
    r"(?!.*(?:не\s+сошл\w*|не\s+со[ё]л\w*|не\s+сход\w*"
    r"|ни\s+одна\s+не|шпул\w*\s+на\s+месте))"
    r"(?:.*(?:дотяг\w*|дотяжк\w*|сошедш\w*|застрявш\w*"
    rf"|{_SPOOL_OFF_RE.pattern}|{_SPOOL_PUT_RE.pattern}))",
    re.IGNORECASE | re.DOTALL)

# Гейт намотки на вал: одного «намотал» мало — так же начинается и честная
# навивка («намотала четыре челнока по счётчику», ст.111 за 21.09). Нужен
# предмет, вокруг которого всё намоталось: вал, полотно или шнур.
_SHAFT_WRAP_RE = re.compile(
    r"намотал\w*[^.;!?]{0,40}?(?:\b(?:вал\w*|полотн\w*|шнур\w*))"
    r"|(?:\bполотн\w*|\bшнур\w*)[^.;!?]{0,40}?намотал\w*",
    re.IGNORECASE | re.DOTALL)

# Категории, где совпадения по слову НЕДОСТАТОЧНО: нужна названная операция.
# Навивка не должна перехватывать запись, которая начинается с «наладка …»:
# «наладка (сошла шпуля, неоднократно; передал наладчику Шалыминову)» (эталон
# 26.08, ст.321) — это работа службы наладки, хотя слово «шпул» там есть.
# Слово «наладчик» В СЕРЕДИНЕ записи навивку не отменяет: «машина отдана в
# работу от наладчика, продолжаю навивку шпулей» — оператор resumed свою работу.
_WINDING_GATE_RE = re.compile(r"^(?!\s*налад)", re.IGNORECASE)

# УШЁЛ не оператор, а служба — это не «отсутствие оператора». Запись
# «наладчик ушёл» описывает, что человек наладки отлучился, а станок в это
# время стоит в наладке; оператор при этом на месте. Без гейта слово «ушёл»
# (первая категория таблицы) превращало её в отсутствие оператора, и станок
# терял строку наладки, а привлекаемый персонал — часы наладчика.
# Гейт срабатывает только когда служба названа ПЕРЕД словом об уходе, иначе
# «оператор ушёл, наладчик к нам не приходил» осталось отсутствием.
_ABSENCE_GATE_RE = re.compile(
    r"^(?!.*(?:наладчик\w*|наладчиц\w*|наладк\w*|электрик\w*|слесарь\w*"
    r"|ремонтник\w*)[^.!?]{0,40}?(?:уш[её]л\w*|уех\w*|не приш[ёе]л\w*|уход\w*))",
    re.IGNORECASE | re.DOTALL)

_CATEGORY_GATES = {
    THREAD_BREAK_LABEL: _THREAD_BREAK_RE,
    BOBBIN_LABEL: _BOBBIN_SWAP_RE,
    SPOOLER_STOP_LABEL: _SPOOLER_SWAP_RE,
    STRETCH_LABEL: _STRETCH_RE,
    "замена шпуль (станок стоит)": _SPOOL_STOP_RE,
    "навивка/намотка шпулей": _WINDING_GATE_RE,
    SHAFT_WRAP_LABEL: _SHAFT_WRAP_RE,
    "отсутствие оператора": _ABSENCE_GATE_RE,
}
# Обе новые категории — простой станка (см. _STOP_ONLY_LABELS ниже).
_SWAP_STOP_LABELS = frozenset((BOBBIN_LABEL, SPOOLER_STOP_LABEL))


def is_swap_stop(reason: str) -> bool:
    """Это подстановка/подмена бобин или подмена шпулярника (станок стоит)."""
    low = (reason or "").lower()
    return bool(_BOBBIN_SWAP_RE.search(low) or _SPOOLER_SWAP_RE.search(low))


def _has_marker(low: str, marker: str) -> bool:
    """Есть ли маркер в тексте. Для коротких — только с начала слова."""
    if marker == "чинк":
        return _REPAIR_RE.search(low) is not None
    if marker in _WORD_START_MARKERS:
        return re.search(r"(?<![а-яёa-z])" + re.escape(marker), low) is not None
    return marker in low


# ——— Стоял станок или работал, пока оператор занимался своим делом ———
#
# Правило участка (со слов пользователя): подмена шпулей и чинка идут при
# ОСТАНОВЛЕННОМ станке; если же оператор не написал «машина в стопе», а пишет
# «развивка/навивка шпуль», станок в стоп НЕ ставится — это делается
# параллельно работе. Поэтому такие часы нельзя класть ни в простой станка,
# ни вторым слагаемым в часы сотрудника: они уже внутри времени работы станка,
# иначе сумма вылезает за 12 ч («ПРЕВЫШЕНИЕ» на 98 и 321 за 24.08.2026).
_STOP_TEXT_MARKERS = ("стоп", "останов", "стоит", "стоял", "стояла", "простой",
                      "не работа", "в ремонте", "инженерн", "заглох")

# Прямое слово мастера о том, что станок ШЁЛ во время его записи: «7.00 машина
# в работе …», «машина в работе, продолжаю навивку шпулей». Нужен свой
# признак, потому что ярлык ставится по одному ключевому слову, и «машина в
# работе, продолжаю навивку шпулей и подстановку шпулярника» (прогон 21.09,
# ст.151) получало «подмена шпулярника (станок стоит)»: 4,55 ч записывались в
# простой идущей машины, а её же время по счётчику добавлялось оператору
# сверху как «контроль за машиной» — 14,0 ч работы при смене 12 ч.
_MACHINE_RUNNING_RE = re.compile(
    r"(?:машина|станок|машинка)\s*(?:тоже|всё\s*таки|уже)?\s*"
    r"(?:в\s+работ\w*|на\s+работ\w*|работает|запущен\w*|пошла|зашла)",
    re.IGNORECASE)

# Операции, которые физически невозможны на работающем станке.
_STOP_ONLY_LABELS = frozenset((
    THREAD_BREAK_LABEL,
    "чинка/ремонт",
    "наладка/переналадка",
    "подмена (заправка полотна)",
    STRETCH_LABEL,
    "замена шпуль (станок стоит)",
    BOBBIN_LABEL,
    SPOOLER_STOP_LABEL,
    "протяжка узлов",
    SHAFT_LABEL,
    # Полотно на вале останавливает станок само — слово «стоп» мастеру писать
    # не нужно.
    SHAFT_WRAP_LABEL,
    # Ошибка машины — это всегда стоп: на «не скидывающейся» ошибке станок не
    # идёт, слова «стоп» мастеру писать не нужно.
    MACHINE_ERROR_LABEL,
    "срезы",
    "отсутствие оператора",
    "ожидание (задание, наладчик, сырьё)",
    "перерыв",
    "внешние причины",
))


# Операции, которые идут при РАБОТАЮЩЕМ станке (не простой).
_RUNNING_LABELS = frozenset((
    WINDING_LABEL,
    "замена шпулярника / переход на ассортимент",
))


def is_shaft_wrap(reason: str) -> bool:
    """Полотно (нить, шнур) намотало на вал — названный останов станка.

    Правило пользователя 28.09.2026 (ст.98 за 26.09: «намоталась на вал — тоже
    простой»). Функция ОДНА на четыре места: классификатор причин, решение
    «стоял ли станок», kind «навивка» и kind «работа» у модели. Один и тот же
    текст мастера ИИ в разных прогонах называет то остановкой, то навивкой, то
    работой, и без общей проверки простой терялся бы заново на любом из этих
    путей.
    """
    return bool(_SHAFT_WRAP_RE.search((reason or "").lower()))


def _spindle_only_stop(low: str) -> bool:
    """Остановлен ОДИН шпиндель или навивочный аппарат, а станок мотает (приказ 29.09).

    Читается ТОЛЬКО слоем переписки (`_log_stop_at`): там «стоп шпиндель» решает,
    открывать ли окну простоя станка. В слое разбора (`machine_stopped_for`) эта
    проверка напротив ломает приказ 29.09 по 28.09 («машина на подмене + навивка
    шпуль в те же минуты = станок стоит») и правило 24.09 («стоп, навивка шпулей»
    — останов): в событии слово мастера про останов своей операции уже учтено.
    Требование «в причине нет слова про машину» обязательно: «16:07 стоп машина,
    шпиндель 2» — станок стоит.
    """
    if _LOG_MACHINE_WORD_RE.search(low):
        return False
    return bool(_LOG_SPINDLE_RE.search(low) or _LOG_UNIT_STOP_RE.search(low))


# ——— Шпиндель и шпульный стол: это не машина (приказ владельца 30.09.2026) ———
#
# «наладка шпинеделя это не причина простоя, шпиндели и шпиндельные столы вообще
# не относятся к машинам. Наладка - это когда наладка машины».
#
# Границы меряли по всем 12 сохранённым разборкам: правило снимает ровно два
# окна — «Шпульный стол, шпиндель 2 недовивает заданные обороты 1457 вместо
# 1550, необходима наладка» (111 за 29.09, 1,52 ч) и «шпульный стол на
# ассортимент НПА 187х3х2 настроен, средний вес 950 гр, …настройки стола: 1390
# оборотов до выключения, скорость мотора 40 HZ» (251 за 14.09, 0,18 ч). Шесть
# других окон со словом про шпиндель остаются простоями: у 14тр за 21/22/24.09
# (по 12,0 ч) в причине написано про машину, у 251 за 16.09 (0,42 ч) — «обрыв
# нити», у 111 за 27.09 (0,07 и 0,08 ч) — «при схождении бобины».
_SPINDLE_PART_RE = re.compile(r"шпиндел|шпуле?ьн\w*\s+стол|шпульн\w*\s+стол",
                              re.IGNORECASE)
# Причина, которая останавливает машину сама по себе. Если она стоит в другом
# предложении, останов шпинделя к ней не относится: «обрыв нити, требуется
# помощь наладчика, шпиндель №1 в наладке» — станок встал из-за обрыва.
_SPINDLE_OTHER_CAUSE_RE = re.compile(
    r"обрыв|стоп|останов|стоит|стоял|стояла|простой|ремонт|чинк|пропуск|срез|"
    r"бобин|бабин|шпулярник|сошл|поломк|инженерн", re.IGNORECASE)
_CLAUSE_SPLIT_RE = re.compile(r"[.,;:\n]+")


def is_spindle_part_work(reason: Optional[str]) -> bool:
    """Наладка или настройка шпинделя/шпульного стола, а не машины.

    Слово про машину снимает правило: «16:07 стоп машина, шпиндель 2» — станок
    стоит. Названная в другом предложении машинная причина тоже снимает: там
    шпиндель упомянут вскользь.
    """
    low = (reason or "").lower()
    if _LOG_MACHINE_WORD_RE.search(low):
        return False
    clauses = [c for c in _CLAUSE_SPLIT_RE.split(low) if c.strip()]
    if not any(_SPINDLE_PART_RE.search(c) for c in clauses):
        return False
    return not any(_SPINDLE_OTHER_CAUSE_RE.search(c)
                   for c in clauses if not _SPINDLE_PART_RE.search(c))


def machine_stopped_for(reason: str, label: Optional[str] = None,
                        unknown_is_stop: bool = True) -> bool:
    """Стоял ли станок во время этой операции.

    True, если мастер прямо написал про стоп/останов/ремонт, либо операция
    сама по себе требует остановки (чинка, наладка, подмена полотна, срез,
    подстановка/подмена бобин, подмена шпулярника). Навивка и размотка шпулей,
    переход на ассортимент без слова «стоп» — работа параллельно работающему
    станку.

    Порядок решений: «чина» и слова про останов сильнее всего; затем прямое
    «машина в работе» (см. _MACHINE_RUNNING_RE) снимает останов даже с бобин и
    шпулярника — правило 03.09.2026 описывает операцию, а не этот момент смены.

    unknown_is_stop — что делать с причиной, которую не узнал ни один маркер
    (см. конец функции).
    """
    low = (reason or "").lower()
    # Правило пользователя 03.09.2026: «если оператор пишет чинка, то в это
    # время машина стоит и это идёт в простой». Проверка идёт ПЕРВОЙ, потому
    # что в свободном тексте чинка часто соседствует со словами, которые
    # классификатор считает параллельной работой: «чинка шпуледержателя»
    # попадала в «навивка/намотка шпулей» (маркер «шпул» стоит раньше) и
    # простой станка исчезал.
    if _REPAIR_RE.search(low):
        return True
    # Намотка полотна на вал — останов по слову мастера, даже без «стоп» и
    # даже если рядом есть признак параллельной работы (см. is_shaft_wrap).
    if is_shaft_wrap(low):
        return True
    # Наладка шпинделя или шпульного стола — не простой машины (приказ владельца
    # 30.09.2026). Проверка стоит ПЕРЕДЕ словарём остановки, потому что мастер
    # пишет «стоп» про шпиндель, а не про машину, и широкая проверка переписки
    # (`_spindle_only_stop`) здесь не годится: в слое разбора строка несёт слово
    # мастера про останов своей операции («стоп, навивка шпулей» — 24.09), и по
    # приказу 29.09 такие минуты остаются простоем машины. Узкое правило смотрит
    # только на шпиндель/шпульный стол и снимается любым словом про машину или
    # машинной причиной в другом предложении.
    if is_spindle_part_work(low):
        return False
    if any(m in low for m in _STOP_TEXT_MARKERS):
        return True
    # После «чина» и «стоп»: прямое «машина в работе» перевешивает ярлык,
    # поставленный по одному ключевому слову (см. _MACHINE_RUNNING_RE).
    if _MACHINE_RUNNING_RE.search(low):
        return False
    lab = label if label is not None else classify_stop(reason)[0]
    if lab in _STOP_ONLY_LABELS:
        return True
    if lab in _RUNNING_LABELS:
        return False
    # «78 маш. в подработке» — человек ведёт вторую машину, пока наша РАБОТАЕТ.
    # Без этого сменная подработка считалась простоем нашего станка и оператору
    # ст.98 выходило ровно 12 ч с ложным «+0,75 ч сверх нормы» (прогоны 27.08 и
    # 01.09). Проверка идёт после _STOP_ONLY_LABELS: «подмена на 78» — всё-таки
    # остановка.
    if "подработк" in low:
        return False
    # Причина не распознана ни одним маркером. Правило пользователя от
    # 25.09.2026: «если в сообщении НЕ сказано, что машина стоп, то она идёт и
    # все операции параллельно» — значит, нераспознанное НЕ останов. Но правило
    # говорит про машину, которая ИДЁТ: когда по счётчику станок за смену не
    # выдал ни узла (ст.321 за 15.09 — работа 0 ч), «параллельно работе» часам
    # взяться неоткуда, и неизвестная причина остаётся простоем. Иначе человек
    # получает часы работы «за идущей машиной», которой не было: 8,53 ч из
    # эталонных 8,25 превращаются в 10,75.
    return unknown_is_stop


# Насколько далеко от начала записи может стоять «обед», чтобы это всё ещё
# был обед, а не упоминание внутри длинной причины.
# Реальные записи обеда: «Обед», «обед», «12:00-12:45 обед»,
# «обед (время не указано)» — слово стоит в первых ~15 символах.
_LUNCH_POS_LIMIT = 15
_LUNCH_TEXT_LIMIT = 25


# «после обеда машина в работе» — отметка времени, а не обед.
_LUNCH_CONTEXT_RE = re.compile(
    r"(?:после|до|перед|посл|без|вместо|кроме)\s+\S{0,12}\s*(?:обед|перерыв|перекур)"
    r"|(?:обед|перерыв|перекур)\w*\s*(?:не|без|отмен|перенес)", re.IGNORECASE)


def _is_lunch_record(low: str) -> bool:
    """Это запись ПРО ОБЕД, а не рабочая запись со словом «обед» внутри.

    Обед мастера пишут коротко и с самого начала: «обед», «12:00-12:45 обед»,
    «обед (время не указано)». Два случая, когда это НЕ обед:

    1. «Обед» глубоко внутри длинной причины («стоп машина, чинка полотна …;
       обед; сч 752202 …») — основное содержание записи работа. Прогон
       10.09.2026, ст.151: 2,7 ч чинки ушли в «перерыв».
    2. «Обед» как ОТМЕТКА ВРЕМЕНИ в начале: «после обеда машина в работе,
       продолжаю навивку шпулей» (прогон 14.09.2026, ст.151) или «до обеда
       успели заменить телеги». Слово стоит рано, но описывает не перерыв, а
       момент — и 3,37 ч навивки превращались в «перерыв».
    """
    pos = min([p for p in (low.find("обед"), low.find("перерыв"),
                           low.find("перекур")) if p >= 0], default=-1)
    if pos < 0:
        return False
    if _LUNCH_CONTEXT_RE.search(low):
        return False                    # «после обеда …», «обеда не было»
    return pos <= _LUNCH_POS_LIMIT or len(low) <= _LUNCH_TEXT_LIMIT


# Счётчик-сводка внутри причины простоя: «5 подмена из 6», «подмена 5 из 5».
# Это ОТЧЁТ о накопленном за смену, а не операция в этом окне: прогон
# 22.09.2026, ст.321 — «09:32 стоп машина, срез (1 срез из 3, 5 подмена из 6)»
# получала ярлык «подмена (заправка полотна)», и часы среза стояли в колонке
# «подмены, ч» (в ручном файле пользователя они в «срезах», а подмен у станка
# нет вовсе). «Срез» из зачистки ИСКЛЮЧЕН: «довязан 2 срез из 3» (21.09.2026,
# ст.251) — это само событие среза, а не сводка, и снимать его нельзя.
# Туда же — «срез узлов от подмены» и «развивка после подмены» (ст.321 за
# 22.09): подмена названа ПРОШЛЫМ действием, в этом окне станок стоял по
# другой причине.
_RECAP_COUNTER_RE = re.compile(
    r"(?:(?:\d+\s*)?подмен\w*\s*[-–—:.]?\s*(?:\d+\s*)?из\s*\d+"
    r"|(?:после|от|во\s*время)\s+подмен\w*)",
    re.IGNORECASE)


def _without_recap_counters(low: str) -> str:
    """Текст причины без счётчиков-сводок — для распознавания операции."""
    stripped = _RECAP_COUNTER_RE.sub(" ", low)
    # Сводка не должна съедать операцию целиком: если после зачистки слов нет,
    # классифицируем исходный текст.
    return stripped if any(c.isalnum() for c in stripped) else low


# Станок убрали в стоп не на час, а до конкретной даты: «машина в стопе до
# 15.10.2026 г.» (прогон 24.09.2026, ст.15тр). Такому записи нет места в
# таблице маркеров — причины там перечисляются словами, а здесь мастер назвал не
# причину, а СРОК. Это не «прочее»: в строке простоя обязаны стоять его слова
# (правило №5), иначе 11,25 ч смены выглядят как беспричинные.
_HORIZON_STOP_RE = re.compile(
    r"(?:в стоп\w*|останов\w*|стои\w*|прост(?:ой|аивает)\w*)\D{0,15}до\s+"
    r"(?:\d{1,2}\.\d{1,2}|(?:[0-9]{1,2}\s+)?\S*(?:янв|фев|мар|апр|май|мая|июн"
    r"|июл|авг|сен|окт|ноя|дек)\w*)")


def _horizon_stop_verbatim(text: str) -> str:
    """Дословная первая фраза мастера, если запись — стоп станка до даты."""
    if not _HORIZON_STOP_RE.search(text or ""):
        return ""
    phrase = re.split(r"[;,\n]", text.strip())[0].strip(" .")
    if not phrase:
        return ""
    return phrase if len(phrase) <= 60 else phrase[:59].rstrip() + "…"


# Та же запись, но найденная в заголовке темы: «15т машина(в стопе до
# 15.10.2026 г.) - информация за смену 27.09.2026г.». Дословную фразу из неё
# брать нельзя — текст начинается с «Погодина Л., 19:52:», и первая запятая
# отрезала бы фамилию. Вырезаем сам срок вместе со словом «машина», если оно
# стоит рядом, иначе ярлык строки простоя разъезжается с 24.09/25.09.
_TOPIC_HORIZON_RE = re.compile(
    r"((?:машина\s*\(?\s*)?в\s+стоп\w*\s+до\s+\d{1,2}\.\d{1,2}\.\d{2,4}\s*г\.?)",
    re.IGNORECASE)


# ——— Станок в стопе НАЗВАНОГО дела, а не «на подмене» ———
#
# Приказ владельца от 29.09.2026 (дословно, про 28.09 ст.111): «если написана
# машина остановлена для нумерации челноков значит это пр[ост]ой машины, пуска
# не было». В той же строке есть слово «подмене» — «Машина остановлена для
# нумерации челноков, чтобы избежать нарушения нумерации шпуль при подмене» —
# и оно называет ЦЕЛЬ, ради которой шпули нумеруют, а не операцию этого окна.
# Из-за него 2,97 ч вечерного простоя (16:02–19:00) уезжали в колонку
# «подмены, ч», а в «Тех. остановки» у станка не оставалось ни строки.
#
# Слово «машина» ОБЯЗАТЕЛЬНО перед словом про останов: «ориентировочное время
# останова машины на подмену с 15.00» (диспетчер, 24.09 ст.111) — это план, а
# не состояние станка, и окно по такому тексту открывать нельзя.
_STOP_PURPOSE_RE = re.compile(
    r"(?:\bмашин\w*|\bстанк\w*)[^.;]{0,18}?(?:остановл\w*|остановил[а-яё]{0,4}|"
    r"в\s+стоп\w*|взял[а-яё]{0,3}\s+в\s+стоп\w*)[^.;]{0,25}?\bдля\s+"
    r"([а-яё][а-яё%×x\d\s\-]{2,40}?)(?=,|\s*[.;]|\Z)",
    re.IGNORECASE)
# Цель, которая и есть операция из таблицы причин, строку не переименовываем:
# «машина в стопе для подмены полотна» остаётся подменой, «…для замены
# шпулярника» — заменой шпулярника.
_STOP_PURPOSE_OPS_RE = re.compile(
    r"подмен|заправ|заряд|шпулярник|бобин|шпул|вал|ассортим|срез|нит",
    re.IGNORECASE)


def _stop_purpose_verbatim(low: str) -> str:
    """«машина остановлена для <названного дела>» — ярлык словами мастера."""
    m = _STOP_PURPOSE_RE.search(low or "")
    if not m:
        return ""
    purpose = (m.group(1) or "").strip(" :,-")
    if len(purpose) < 3 or _STOP_PURPOSE_OPS_RE.search(purpose):
        return ""
    return "машина остановлена для " + purpose


def classify_stop(text: str) -> tuple:
    """Причина простоя → (ярлык, работал ли оператор в это время).

    Мастера пишут свободно («машина стоп, произвожу подмену», «стоит,
    навиваю шпули»), поэтому причину узнаём по ключевым словам. Если
    причина не распознана — считаем, что оператор был занят станком
    (иначе получим ложный «недостаток времени»), но помечаем как «прочее».
    """
    low = (text or "").lower()
    # Маркеры ищем по тексту без счётчиков-сводок («5 подмена из 6») — иначе
    # отчёт о накопленном выдаётся за операцию этого окна (см. выше).
    for_reop = _without_recap_counters(low)
    for markers, label, operator_active in _STOP_CATEGORIES:
        if not any(_has_marker(for_reop, m) for m in markers):
            continue
        if label == "перерыв" and not _is_lunch_record(low):
            # Слово «обед» В СЕРЕДИНЕ длинной рабочей записи — это не обед.
            # Прогон 10.09.2026, ст.151: модель собрала останов 10:03–12:45
            # одной причиной («стоп машина, чинка полотна …; обед; сч 752202;
            # в 12:45 машина в работе»), и 2,7 ч ЧИНКИ оператора уехали в
            # «перерыв»: простой станка задвоился с обедом (баланс 12,26 ч),
            # а оператор потерял 2,7 ч работы.
            continue
        gate = _CATEGORY_GATES.get(label)
        if gate is not None and not gate.search(low):
            # Слово есть, а операции нет («Вес начинки со шпулярника большая»)
            # — пусть причину определяют правила ниже по таблице.
            continue
        if (label in _RUNNING_LABELS or label in _SWAP_STOP_LABELS
                or label == SUB_LABEL) and _REPAIR_RE.search(low):
            # Правило пользователя 03.09.2026: чинка сильнее и «параллельных»
            # операций, и подстановки бобин. «Чинка шпуледержателя» по порядку
            # категорий попадала в навивку (маркер «шпул» стоит раньше) и
            # уходила из простоя станка вместе с ярлыком.
            #
            # Подмена полотна — из того же ряда (прогон 22.09.2026, ст.321):
            # «чина чинка полотна по краю 3 полотна, машина в стопе; … 5 подмена
            # из 6» давало 1,68 ч в колонке «подмены, ч», хотя мастер описывал
            # чинку и в ручном файле пользователя эти часы стоят в «чинка».
            return "чинка/ремонт", True
        if label == SUB_LABEL or label in _RUNNING_LABELS:
            verbatim = _stop_purpose_verbatim(low)
            if verbatim:
                # Названное дело станок и остановило; операция из таблицы
                # причин здесь ни при чём (приказ 29.09 по 28.09, ст.111).
                return verbatim, True
        return label, operator_active
    verbatim = _stop_purpose_verbatim(low)
    if verbatim:
        # Причина не распознана таблицей, но мастер назвал дело, ради которого
        # станок стоит: «Машина остановлена для очистки машины от загрязнений».
        return verbatim, True
    verbatim = _horizon_stop_verbatim(low)
    if verbatim:
        # Станок убрали в долгосрочный стоп — у машины никого нет, это статус,
        # а не операция человека (как наладка или инженерная служба). С True
        # такой останов становился «работой оператора» на всю смену: прогон
        # 24.09.2026, ст.15тр — 11,25 ч «машина в стопе до 15.10.2026 г» в
        # блоке работы оператора при пустой фамилии.
        return verbatim, False
    return (OTHER_LABEL if low.strip() else NO_REASON_LABEL), True


@dataclass
class ProductLine:
    """Одна строка отчёта: станок + ассортимент + заявка."""
    assortment: Optional[str] = None
    client: Optional[str] = None
    order_no: Optional[str] = None
    # Дата заявки (колонка H). В переписке мастер пишет номер вместе с датой
    # одним числом («Склад 49-24.08.26»), и ИИ часто отдаёт обрывок «49-24»:
    # тогда в G уезжает неверный номер, а H остаётся пустой. См.
    # _split_order_with_date.
    order_date: Optional[str] = None
    panels: Optional[int] = None
    counter_start: Optional[float] = None
    counter_end: Optional[float] = None
    # Первое показание счётчика взято НЕ с начала смены (в переписке его нет).
    # Тогда время работы станка заведомо занижено, и молчать об этом нельзя:
    # прогон 01.09, ст.321 — бот взял 115423 из середины смены и дал 1,2 ч,
    # а в журнале начальное показание 115329 (у пользователя 1,46 ч).
    counter_start_mid_shift: bool = False

    @property
    def output(self) -> Optional[float]:
        if self.counter_start is None or self.counter_end is None:
            return None
        if self.counter_end < self.counter_start:
            # Счётчик назад не отматывается: такая пара — испорченное показание
            # мастера, и выпуск по ней выдумывать нельзя. Время по ей и так не
            # считается (machine_rates.work_hours), поэтому и в колонку «Выпуск
            # фактический» идёт пустая клетка, а не «-88568» (прогон 26.09.2026,
            # ст.251 — туда доезжало отрицательное число).
            return None
        return self.counter_end - self.counter_start


@dataclass
class TechStop:
    """Простой станка с причиной из сообщений мастера."""
    hours: float
    reason: str = ""
    operator_active: Optional[bool] = None   # None → определить по причине
    other_machine: Optional[str] = None      # оператор ушёл работать на этот станок
    performer: Optional[str] = None          # кто выполнял (для привлекаемого персонала)
    is_sub: bool = False                     # это подмена (заправка полотна)
    submen_recorded: bool = False            # мастер сам назвал окно подменой
                                             # (kind «подмена»): основание для
                                             # колонки «подмены, ч»
    start_min: Optional[int] = None          # начало интервала, мин от полуночи
    end_min: Optional[int] = None            # конец интервала, мин от полуночи
    full_absence: bool = False               # оператор ВСЮ смену на другом станке
                                             # (kind «отсутствие»): здесь чистое
                                             # отсутствие, его часы — на том станке,
                                             # где он штатный оператор, а не тут
    is_naladka: bool = False                 # это наладка (kind «наладка»):
                                             # в лист-таблицу НЕ идёт как подмена/
                                             # привлечённый — только простой машины
    label_override: Optional[str] = None     # готовый ярлык для строки отчёта
                                             # (перенос часов оператора с чужого
                                             # станка: «работа на машине №151»)
    is_parallel: bool = False                # операция шла ПАРАЛЛЕЛЬНО работе
                                             # станка независимо от причины
                                             # (склейка «всю смену» на ст.98)
    machine_label: Optional[str] = None      # ярлык для строки ПРОСТОЯ станка,
                                             # когда машину держит служба, а
                                             # оператор в это время занят своим
                                             # делом (см. _service_stop_label)
    shiftlong_parallel: bool = False         # длинное окно, которое не влезает
                                             # в 12 ч вместе с работой станка и
                                             # потому оставлено параллельным
                                             # (см. _parallelize_shiftlong_swaps)
    hours_estimated: bool = False            # время названо приблизительно
                                             # («ориентировочное окончание работ
                                             # 10-00») — привлечённому персоналу
                                             # такие часы не начисляем
    unknown_is_stop: bool = True             # нераспознанная причина на ЭТОМ
                                             # станке = простой. False ставит
                                             # разбор, когда счётчик подтверждает,
                                             # что машина шла (правило 25.09.2026)
    free_ivs: Optional[List[Tuple[int, int]]] = None
                                             # минуты этого окна, которые НЕ
                                             # заняли более ранние записи той же
                                             # смены (см. _squeeze_time_overlaps).
                                             # Пока окно целое — None, часы и
                                             # обед считаются по нему
    transferred: bool = False                # запись ПЕРЕНЕСЕНА на этот станок с
                                             # чужого (оператор уходил сюда). Это
                                             # не пересказ события этого станка,
                                             # поэтому фильтр зеркальных дублей
                                             # (_is_mirrored_arrival) её не трогает
    on_submen_state: bool = False            # станок в эти минуты назван «на
                                             # подмене» (приказ 29.09.2026 по
                                             # 28.09, ст.111): «параллельная»
                                             # навивка шпуль при таком состоянии
                                             # идёт у стоящего станка
    performer_claimed: str = ""              # имя, которое назвала модель, но в
                                             # переписке ЭТОГО станка его нет (см.
                                             # _performer_in_topic). Оно остаётся
                                             # в performer: по нему работают
                                             # фильтр зеркальных пересказов
                                             # (_is_mirrored_arrival) и разбивка
                                             # «свои часы / привлечённые». В
                                             # отчёт строка выходит ролью.

    @property
    def windows_min(self) -> List[Tuple[int, int]]:
        """Минуты, которые эта запись реально занимает у смены.

        Целиком окно — если его не перекрыла более ранняя запись; иначе те
        свободные куски, что от него остались (free_ivs). Операции без
        интервала возвращают пустой список — их часы считаются как есть.
        """
        if self.free_ivs:
            return list(self.free_ivs)
        if self.start_min is not None and self.end_min is not None:
            return [(self.start_min, self.end_min)]
        return []

    @property
    def elsewhere(self) -> bool:
        """Оператор в это время работал на ДРУГОМ станке.

        По правилу участка для ЭТОГО станка такие часы — отсутствие
        оператора: он ушёл, станок остался без человека. Свои часы он
        получает на том станке, куда ушёл (там это подмена).
        Определяется только явным номером другого станка: по одному слову
        «переведена» судить нельзя (её могли перевести на другую операцию
        на этом же станке).
        """
        return bool(self.other_machine)

    @property
    def label(self) -> str:
        if self.label_override:
            return self.label_override
        if self.elsewhere:
            return ("отсутствие оператора (ушёл на станок "
                    + str(self.other_machine) + ")")
        if self.is_naladka:
            # kind «наладка» сильнее слов в причине: «вызван наладчик, идут
            # пропуска» — это наладка, а не чинка пропусков, иначе часы
            # наладчика уезжают в чужую строку простоя.
            return "наладка/переналадка"
        return classify_stop(self.reason)[0]

    @property
    def stop_label(self) -> str:
        """Ярлык для строки ПРОСТОЯ станка (у оператора он может быть другим).

        В одном сообщении мастер часто пишет и почему стоит машина, и чем он
        сам в это время занят: «машина в стопе, действия инженерной службой, пэ
        оборван; продолжаю навивку шпулей». Часы у человека — навивка, а простой
        станка — наладка. Прогон 01.09, ст.151: простой назывался «навивка
        5,67 ч» (в эталоне пользователя — «наладка 6 ч»).
        """
        return self.machine_label or self.label

    @property
    def by_operator(self) -> bool:
        """Работал ли оператор в это время НА ЭТОМ станке."""
        if self.elsewhere:
            return False
        if self.is_naladka:
            # Наладка — время СЛУЖБЫ НАЛАДКИ, а не оператора (правило
            # пользователя 27.08.2026: «наладка идёт лишь в простой машины»).
            # Без этого «машина в службе наладки» попадала и в простой станка,
            # и в работу оператора одновременно (прогон 31.08, ст.151: строка
            # «машина в службе наладки … 1 ч» в блоке работы оператора).
            # Часы самого наладчика идут в привлекаемый персонал по performer.
            return False
        if self.operator_active is not None:
            return self.operator_active
        return classify_stop(self.reason)[1]

    @property
    def machine_stopped(self) -> bool:
        """Стоял ли станок. False → операция шла параллельно работе станка.

        Чинка сильнее любого признака параллельности: даже если в том же
        сообщении написано «машина в работе» (реальная смена 02.09, ст.151:
        «10:36 Чинка , машина в работе 10:39 чинка завершена»), по правилу
        участка станок в это время стоит и время идёт в простой машины.

        Исключение — окно, которое физически не влезает в смену: запись «всю
        смену» на 12 ч при работе по счётчику 7,22 ч (ст.91 за 24.09) описывает
        фон, а не останов, и её снимает в параллель _parallelize_shiftlong_swaps
        (флаг shiftlong_parallel).
        """
        if self.shiftlong_parallel:
            return False
        if _REPAIR_RE.search((self.reason or "").lower()):
            return True
        # Названная намотка на вал сильнее kind от ИИ: модель может вернуть эту
        # же запись как «навивку» или «работу», а станок по словам мастера стоял
        # (правило 28.09.2026, ст.98 за 26.09).
        if is_shaft_wrap(self.reason):
            return True
        if self.elsewhere:
            return True
        # Станок назван «на подмене» — он не мотает полотно, и навивка шпуль в
        # эти минуты не может идти параллельно работе (приказ 29.09.2026).
        if self.on_submen_state:
            return True
        if self.is_parallel:
            return False
        # Ярлык для правила берём из слов причины, а НЕ из self.label: kind от
        # ИИ («наладка» при «переход на др. ассортимент») перекрыл бы правило
        # 25.09 — перестройка на другой ассортимент идёт при работающей машине
        # и в простой не входит (эталон 10.09.2026, ст.98: 8,52 работа + 2,33
        # названных простоя + 0,75 обед + 0,4 именованный остаток = 12 ч).
        return machine_stopped_for(self.reason, classify_stop(self.reason)[0],
                                   self.unknown_is_stop)

    @property
    def is_absence(self) -> bool:
        if self.elsewhere:
            return True
        low = (self.reason or "").lower()
        if not any(m in low for m in _ABSENCE_MARKERS):
            return False
        # Тот же гейт, что у классификатора (_CATEGORY_GATES для «отсутствие
        # оператора»). Без него «наладчик ушёл, ждём службу» считалось уходом
        # ОПЕРАТОРА: запись терялась из простоя как чужая, а её минуты забирала
        # строка «отсутствие оператора» — в отчёте не оставалось ни наладки, ни
        # часов наладчика (проверено на ст.121: 2,0 ч наладки исчезали, а баланс
        # показывал 9,24 ч отсутствия).
        return bool(_ABSENCE_GATE_RE.search(low))


def _same_person_name(a: Optional[str], b: Optional[str]) -> bool:
    """Один ли это человек — сравнение по фамилии/имени в любом порядке.

    «Петровский» == «Петровский О.» == «Олег Петровский»; «Демидов» != «Гузяев».
    Отличие от _same_person: тот работает с полными строками performer, а здесь
    сравниваем короткие подписи из событий обеда, где имя может стоять как
    до, так и после фамилии.
    """
    def tokens(s: str) -> set:
        return {t.strip(" .,()").lower() for t in str(s or "").split()
                if len(t.strip(" .,()")) > 1}

    ta, tb = tokens(a), tokens(b)
    if not ta or not tb:
        return False
    return bool(ta & tb)


def _same_person(a: Optional[str], b: Optional[str]) -> bool:
    """Один ли это человек по фамилии (первый токен, без регистра).

    «Камбаров» == «Камбаров Иван» == «камбаров». Нужно, чтобы не задвоить
    оператора целевого станка в привлечённый персонал (эталон 26.08: Камбаров
    ушёл с 321 и весь день был оператором на 251 — там он уже учтён).
    """
    if not a or not b:
        return False
    ta = a.strip().split()
    tb = b.strip().split()
    if not ta or not tb:
        return False
    return ta[0].casefold() == tb[0].casefold()


def _name_backed_by(who: str, text) -> bool:
    """Назван ли человек этим текстом — ИЛИ проверять нечем.

    Ищем фамилию без падежного окончания и без инициалов: мастер пишет
    «Гудкова», «Гудковой», «И. Гудкова». Перебираем ВСЕ части имени, а не самую
    длинную: модель отдаёт «Рыжкова Елена», а в чате — «Рыжкова Е.», и по одному
    «елена» имя уехало бы в небытие.

    True возвращается и когда именем правит пустой текст, и когда от имени
    остались одни инициалы: снять фамилию можно только по ДОКАЗАННОМУ
    отсутствию. Прогон 16.09.2026, ст.251: исполнитель «Р.» — это Александр Р.,
    наладчик, который сам писал в тему («Александр Р., 07:25: Обрыв устранён…»),
    и по одной букве «Р» проверить его нельзя.
    """
    tokens = [t for t in re.split(r"[^а-яёa-z]+", (who or "").lower())
              if len(t) > 2]
    low = str(text or "").lower()
    if not tokens or not low.strip():
        return True
    return any(name in low or (len(name) > 4 and name[:-1] in low)
               for name in tokens)


# Роль вместо фамилии, которую в записи никто не называл.
UNPROVEN_ROLE = "исполнитель не назван"
UNPROVEN_NALADKA_ROLE = "наладчик"


def _unproven_role(is_naladka: bool) -> str:
    """Роль вместо фамилии, которой нет в словах мастера.

    Так уже выглядит эталон пользователя 14.09, ст.321: «0,87 наладчик —
    наладка» — строка есть, часы на месте, а человека без подтверждения не
    названо.
    """
    return UNPROVEN_NALADKA_ROLE if is_naladka else UNPROVEN_ROLE


def _windows_touch(a: "TechStop", b: "TechStop") -> bool:
    """Пересеклись ли окна двух строк. Без окна доказательств нет — считаем,
    что пересеклись (старое поведение: пересказ дела с другого станка часто
    приходит вообще без времени)."""
    if a.start_min is None or a.end_min is None or \
            b.start_min is None or b.end_min is None:
        return True
    return a.start_min < b.end_min and b.start_min < a.end_min


def _same_reason(a: "TechStop", b: "TechStop") -> bool:
    """Названо ли дело дословно одинаково (в разном времени — это то же дело).

    Пересказ одного дела из двух тем часто приходит с OTHER окном: ст.151 за
    27.08.2026 — «замена шпулярника, 58 бабин» 07:00–09:30 и те же 2,5 ч с той
    же формулировкой 16:30–19:00. Эталон пользователя — 2,5 ч, поэтому одинаковая
    причина сильнее несовпадающего окна.
    """
    first = re.sub(r"\s+", " ", (a.reason or "").strip().lower())
    second = re.sub(r"\s+", " ", (b.reason or "").strip().lower())
    return bool(first) and first == second


def _dedupe_people(stops: List["TechStop"]) -> List["TechStop"]:
    """Убрать повтор одной и той же работы одного человека на станке.

    Одно событие часто попадает в разбор дважды: раз по своему станку («замена
    шпулярника, 58 бабин — Камбаров») и раз по чужому («Камбаров ушёл на подмену
    шпулярника на 151»). За 27.08 из-за этого на ст.151 Камбаров стоял на 5 + 2,5
    ч при эталонных 2,5.

    Повтор = одна фамилия И одна длительность (с точностью до минуты) И
    (одинаково названное дело ИЛИ пересекающиеся окна).

    Раньше доставало фамилии с длительностью, и из-за этого сливались два РАЗНЫХ
    дела одного человека одной длины: 29.09.2026 ст.251 — «перекладывание развитых
    шпуль из телеги» 10:10–10:18 (0,13 ч) и «нумерация шпуль с 1.285–1.303»
    10:18–10:25 (0,12 ч). В ручном файле пользователя обе строки стоят отдельно
    (`отчет за 29 число.xlsx`, лист «29.09»), а у нас вторые часы пропадали —
    и у Вашурин (оператора 151) их не было в переносе по приказу №135.

    ИСКЛЮЧЕНИЕ: повторные ВЫЗОВЫ НАЛАДЧИКА (is_naladka) в разное время — это
    разные дела, даже если длительность и формулировка совпали. Иначе терялись
    вызовы одинаковой длины (правило промта 6.292: каждый вызов — отдельное
    событие).
    """
    res: List["TechStop"] = []
    for s in stops:
        dup = False
        for kept in res:
            if abs(kept.hours - s.hours) < 0.02 and \
                    _same_person(kept.performer, s.performer) and \
                    (_same_reason(kept, s) or _windows_touch(kept, s)):
                if (kept.is_naladka and s.is_naladka
                        and kept.start_min is not None
                        and s.start_min is not None
                        and abs(kept.start_min - s.start_min) > 1):
                    continue        # два разных вызова наладчика
                dup = True
                break
        if not dup:
            res.append(s)
    return res


_ARRIVAL_RE = re.compile(
    r"(уш[её]л|ушел|пришл?[ёе]л|приш[ёе]л|отправлен|вызван на|подошл)",
    re.IGNORECASE)


def _is_mirrored_arrival(stop, report, machine_key: str) -> bool:
    """Событие описывает УХОД на этот же станок → это дубль с другого станка.

    «Олег — ушёл на подмену шпулярника на 151 машину, пришёл с подмены»,
    записанное ПО СТАНКУ 151, — пересказ события станка 321, где тот же человек
    уже учтён. Своего оператора и уходы на ДРУГИЕ станки не трогаем.

    Перенесённые строки (transferred) — не пересказ: их создал сам перенос в
    build, и номер этого станка в причине там обязателен (25.09: «Петровский —
    ушел на 251 смотреть ошибку» перенесено в привлекаемый персонал 251; без
    флага фильтр снимал эту строку только из-за слова «ушел»).
    """
    reason = (stop.reason or "")
    if not reason or getattr(stop, "elsewhere", False) or \
            getattr(stop, "transferred", False):
        return False
    if not _ARRIVAL_RE.search(reason):
        return False
    nums = re.findall(r"\d+\s*(?:тр)?", reason)
    if machine_key not in {machine_rates._norm_key(n) for n in nums if n.strip()}:
        return False
    who = (stop.performer or "").strip()
    if not who:
        return False
    if _same_person(who, report.operator) or _same_person(who, report.operator2):
        return False
    return True


_NALADKA_ACTION = ("остановил", "остановила", "останов", "вызван", "вызвал",
                   "вызвала", "работает", "работают", "подошёл", "подошел",
                   "подошли", "занимается", "занимаются", "устраняет",
                   "устраняют", "поправил", "поджал", "запустил", "в наладке",
                   "идут наладочные", "идет наладочн", "идёт наладочн")

# «Машину пустили» = станок пошёл, и день уже не закрыт наладкой. Корень ищем
# без приставок «вы-/от-»: «выпустил нитки со стороны шпулей» — это работа
# оператора на стоящей в наладке машине, а не пуск.
_RESUMED_RE = re.compile(r"(?<![а-яё])пустил\w*")


# «Нужна консультация наладчика», «требуется помощь наладчика в заправе» —
# это ЗАПРОС/ОЖИДАНИЕ, а не отработанное время службы. Прогон 15.09.2026,
# ст.251: событие 15:58–16:21 «машина остановилась сама, с крючков нить
# нескинута, сигнала нет; нужна консультация наладчика» дало строку
# «0,38 | наладчик» в привлекаемом персонале, хотя фамилии нет и никто не
# приходил — в эталоне пользователя за этот день только «0,88 | Пронкин».
_SERVICE_REQUEST_RE = re.compile(
    r"нужн\w*\s+(?:консультаци|помощ|наладчик)|требу\w+\s+(?:помощ|наладчик)"
    r"|(?:вызвать|позвать|пригласить|жду|ожидани|прид[ёе]т|подойдите)"
    r"[^.]{0,25}наладчик|наладчик[^.]{0,15}(?:нужен|требуется|жд[ёе]м)",
    re.IGNORECASE)


def _is_service_request(reason: str) -> bool:
    """Запись ПРОСИТ службу прийти, а не сообщает о её работе."""
    return bool(_SERVICE_REQUEST_RE.search(reason or ""))


def _naladchik_from_reason(reason: str) -> Optional[str]:
    """Фамилия наладчика из причины: «машину остановил наладчик Пронкин».

    Модель иногда не заполняет performer, и часы службы наладки уезжают в
    работу оператора (прогон 01.09, ст.251: 2,25 ч вместо привлечённого
    Пронкина). Фамилию берём только если она стоит рядом со словом
    «наладчик» и написана с большой буквы.
    """
    text = reason or ""
    m = re.search(r"наладчик[а-яё]*\s+([А-ЯЁ][а-яё]{2,})", text)
    if m:
        return m.group(1)
    m = re.search(r"([А-ЯЁ][а-яё]{2,})\s+наладчик", text)
    return m.group(1) if m else None


def _reason_is_naladka(reason: str) -> bool:
    """Причина говорит о РАБОТЕ СЛУЖБЫ НАЛАДКИ, а не о чинке оператора."""
    low = (reason or "").lower()
    if "наладчик" not in low and "наладке" not in low:
        return False
    if any(m in low for m in ("ожидан", "ждал", "ждала", "жду ")):
        return False
    return any(m in low for m in _NALADKA_ACTION)


# Служба (наладка/инженерная) ДЕРЖИТ машину. Ловим только прямое указание на
# службу или наладчика: слово «наладочный» («срез наладочных узлов») сюда не
# попадает — это операция оператора.
_SERVICE_HOLDS_MARKERS = ("инженерн", "наладчик", "службой наладки",
                          "службы наладки", "служба наладки", "в наладке")
# Ярлыки, которые сами по себе уже объясняют простой станка: их подменять
# наладкой нельзя.
_KEEP_STOP_LABEL = frozenset((
    "наладка/переналадка", "отсутствие оператора", "перерыв",
    "ожидание (задание, наладчик, сырьё)", "внешние причины",
    "подмена (заправка полотна)",
))


def _service_stop_label(reason: str) -> Optional[str]:
    """Ярлык простоя, когда машину держит служба, а оператор занят своим делом.

    Мастер пишет одним сообщением и причину остановки, и своё занятие: «машина
    в стопе … производились действия инженерной службой, пэ оборван …;
    продолжаю навивку шпулей». Ярлык по такой причине выходил «навивка/намотка
    шпулей», и в простое станка вместо наладки стояла навивка (прогон 01.09,
    ст.151: 5,67 ч навивки, в эталоне пользователя — наладка 6 ч).

    Часы оператора при этом остаются навивкой: он действительно навивал шпули,
    пока машину держала служба. Поэтому меняется только ярлык строки ПРОСТОЯ.
    """
    low = (reason or "").lower()
    if not any(m in low for m in _SERVICE_HOLDS_MARKERS):
        return None
    label = classify_stop(reason)[0]
    if label in _KEEP_STOP_LABEL:
        return None
    return "наладка/переналадка"


# Время названо приблизительно — начислять его человеку нельзя.
_ESTIMATE_MARKERS = ("ориентировочн", "предположительн", "время не уточн",
                     "время неизвестн", "примерное время")


def _time_is_estimate(reason: str) -> bool:
    """«Ориентировочное окончание работ 10-00» — это прогноз, а не отработка."""
    return any(m in (reason or "").lower() for m in _ESTIMATE_MARKERS)


def _merge_intervals(intervals: List[tuple]) -> List[tuple]:
    res: List[tuple] = []
    for s, e in sorted(iv for iv in intervals
                       if iv[0] is not None and iv[1] is not None):
        if res and s <= res[-1][1]:
            res[-1] = (res[-1][0], max(res[-1][1], e))
        else:
            res.append((s, e))
    return res


def _subtract_intervals(intervals: List[tuple],
                        blockers: List[tuple]) -> List[tuple]:
    """Интервалы БЕЗ минут, которые уже заняты другим блокером.

    Нужен, чтобы «снять наложение» можно было не только цифрой часов, но и
    точными минутами: у операции, чьё окно уже занято более ранней записью,
    остаётся только свободный кусок. Прогон 10.09.2026, ст.321: обёртка
    07:00–14:04 после навивки 07:00–12:40 свободна только с 12:40, и обед
    12:00–12:45 в эти оставшиеся минуты почти не попадает — а вычитался из
    неё целиком, 45 минут, которых оператор не терял.
    """
    out: List[tuple] = []
    block = _merge_intervals(blockers)
    for s, e in _merge_intervals(intervals):
        cur = s
        for bs, be in block:
            if be <= cur or bs >= e:
                continue
            if bs > cur:
                out.append((cur, min(bs, e)))
            cur = max(cur, be)
            if cur >= e:
                break
        if cur < e:
            out.append((cur, e))
    return out


def _union_hours(intervals: List[tuple]) -> float:
    """Часы объединения интервалов [(start_min, end_min), ...].

    Параллельные подмены (эталон 26.08, ст.151: Камбаров 07:00–08:00, Сенцов
    и Скворцов 07:35–08:00 идут ОДНОВРЕМЕННО) занимают у станка не сумму, а
    длину общего окна. Пересекающиеся интервалы сливаются, непересекающиеся
    (подмена в разное время) складываются.
    """
    ivs = sorted(iv for iv in intervals
                 if iv[0] is not None and iv[1] is not None and iv[1] >= iv[0])
    total = 0
    cur_s = cur_e = None
    for s, e in ivs:
        if cur_e is None:
            cur_s, cur_e = s, e
        elif s <= cur_e:
            cur_e = max(cur_e, e)
        else:
            total += cur_e - cur_s
            cur_s, cur_e = s, e
    if cur_e is not None:
        total += cur_e - cur_s
    return total / 60.0


# Подмена и обед — не техническая остановка станка: у них свои колонки
# («подмены, ч» / «фио на подменах», а обед — строка простоя в «Пояснении»).
# В лист-таблице (колонка «Технические остановки») их быть не должно — так в
# ручном файле пользователя за 22.09.2026: ст.98 стоит пустой при двух подменах
# и обеде, ст.321 = «2,7+5,95 | наладка+чинка».
_SUBMEN_MARKERS = ("подмен", "замена шпу", "замену шпу", "замене шпу",
                   "шпулярник")
_LUNCH_MARKERS = ("обед", "перерыв", "перекур")

# Замена МАТЕРИАЛА — это не подмена человека. Приказ владельца 30.09.2026:
# «строку мастера считай подменой, заменой одной катушки это не подмена».
# Сданная сборка 29.09.2026 по ст.321 поставила в «Кол-во подмен» 56: в счётчик
# уходило любое окно ветки замены, а 58 строк мастера были «замена 21 бобины»,
# «замена 22 бобины», … (род модель назвала «остановка») — при том что сам мастер
# писал «Подмена - 5 из 6». В
# файле владельца эти часы лежат строкой «замена шпулярника — замена бобин»
# (7,32 ч) в технических остановках, а «подмены, ч» у станка пустая.
# Шпулярник в список НЕ входит: целая замена шпулярника — работа людей, и в
# ручном файле за 22.09 ст.151 такие окна дают 8,66 ч подмен. Отсекается только
# слово о единице сырья, поэтому «замена катушки на шпулярнике» (ст.321, 27.09)
# всё равно не подмена: в ней назана катушка.
# Шпуля тоже НЕ входит: «подмена 250 шпулей» (ст.98, 29.09) и «Скворцов на
# подмену шпуль» (ст.321, 27.09) — это подменщик у машины, владелец считает их
# подменами.
_MATERIAL_SWAP_RE = re.compile(r"бобин|бабин|катушк", re.IGNORECASE)


def is_material_swap(text: Optional[str]) -> bool:
    """В тексте назана замена единицы сырья (бобины, катушки), а не людей."""
    return bool(_MATERIAL_SWAP_RE.search(text or ""))


def is_submen_label(label: Optional[str]) -> bool:
    """Ярлык операции — подмена человека (заправка полотна, подмена шпуль).

    Со словом «чинка» ярлык чистой подменой быть перестаёт: правило пользователя
    от 22.09 (пункт 8) — ремонт сильнее подмены, и его часы идут в технические
    остановки. Прогон 24.09.2026, ст.91: «замена шпулярника и чинка в течении
    всей смены» попадала в подмены из-за маркера «шпулярник», и в Excel колонка
    «Технические остановки» показывала 0,25 ч вместо 2,78+0,25.

    С 30.09.2026 так же перестаёт быть подменой замена материала — бобины и
    катушки (см. `_MATERIAL_SWAP_RE`).
    """
    low = (label or "").lower()
    if _REPAIR_RE.search(low):
        return False
    if is_material_swap(low):
        return False
    return any(m in low for m in _SUBMEN_MARKERS)


def is_lunch_label(label: Optional[str]) -> bool:
    low = (label or "").lower()
    return any(m in low for m in _LUNCH_MARKERS)


# ——— Колонка «подмены, ч» (I): считает ТОЛЬКО то, что мастер назвал подменой ———
#
# Разбор ставит kind «подмена» и там, где у машины стоял свой оператор, и там,
# где слово «подмена» означает партию шпуль («Подмена 6 из 15»). Ручной файл
# пользователя за 27.09.2026 показывает, что он считает человеком отработанным
# по подмене: ст.98 «12:20-13:10 подмена» — 0,83; ст.321 «7:10-10:10 Скворцов
# на подмену шпуль» — 3,33 (а пять записей «замена катушки на шпулярнике» у него
# лежат в технических остановках строкой «шпулярник», а не в подменах); ст.251
# «Подмена на 251» 07:08 — «Подмену закончил. 64 шп.» 08:07 — 1,1 при том, что
# станок в эти минуты не стоял; ст.111 — пусто, хотя в теме есть «16:29 Стоп на
# подмену. Сошла шпуля №7».
_SPOOL_DROP_RE = re.compile(
    r"(?:сош(?:ла|ел|ов|ла)|(?<![а-яё])сход|упал[аи]?|слет(?:ела|ит|ело))"
    r"(?:\s+\S+){0,3}?\s+(?:шпул|бобин|бабин)\w*"
    # Обратный порядок слов: «бобина слетела со шпильки».
    r"|\b(?:шпул|бобин|бабин)\w*(?:\s+\S+){0,3}?\s+"
    r"(?:сош(?:ла|ел|ов|ла)|(?<![а-яё])сход|упал[аи]?|слет(?:ела|ит|ело))",
    re.IGNORECASE)


def is_spool_drop_text(text: Optional[str]) -> bool:
    """Окно названо подменой, но речь о сходе шпули/бобины, а не о человеке.

    «Стоп на подмену. Сошла шпуля №7» (27.09, ст.111) — станок встал из-за
    сошедшей шпули; подмены человека в этом нет, и в его файле клетка пустая.
    """
    return bool(_SPOOL_DROP_RE.search(text or ""))


# Работа службы в окне, которое модель пометила kind «подмена». «наладочных»
# («срез наладочных узлов» — операция оператора) сюда сознательно не берём.
_SUBMEN_SERVICE_RE = re.compile(r"наладка|наладчик|переналадка", re.IGNORECASE)


def is_submen_window(stop: "TechStop", operator: Optional[str]) -> bool:
    """Какое окно идёт в колонку «подмены, ч».

    Основание — слово мастера (kind «подмена»), а не наша догадка по слову
    «шпулярник» в причине. Станок при этом может идти: подменщик делает своё
    дело параллельно (251, Петровский, 07:00–08:07).

    Замена ЕДИНИЦЫ сырья подменой не считается вовсе (приказ владельца
    30.09.2026: «заменой одной катушки это не подмена»): её часы остаются в
    технических остановках станка, но в эту колонку не идут. Это вторая подстраховка
    к слову мастера: в сохранённых разборах окна «замена N бобины» (ст.321, 29.09)
    названы родом «остановка», то есть до `submen_recorded` дело не доходит.
    """
    if not stop.submen_recorded:
        return False
    if is_material_swap(stop.reason):
        return False
    if is_spool_drop_text(stop.reason) or is_spool_drop_text(stop.stop_label):
        return False
    who = (stop.performer or "").strip()
    service = (stop.is_naladka or _reason_is_naladka(stop.reason)
               # Слово мастера про службу сильнее его же метки: «Пропуск узлов
               # после подмены, наладка» — это наладчик, а не подменщик.
               or _SUBMEN_SERVICE_RE.search(stop.reason or "")
               or _SUBMEN_SERVICE_RE.search(str(stop.stop_label or "")))
    other_person = bool(who) and not _same_person_name(
        who, (operator or "").strip()) and not service
    # Привлечённый человек считается всегда; когда окна ведёт свой оператор,
    # подменой это бывает только на стоящей машине («12:20-13:10 подмена», ст.98).
    return other_person or (stop.machine_stopped and not service)



# ——— Колонки подмен и строка «РАСХОЖДЕНИЕ»: ОДИН код для Excel и для 1С ———
#
# Раньше оба выгрузчика держали эти правила каждый у себя: excel_export._subs_fio перечислял
# оператора, который сам стоял на подмене (в ручном файле пользователя ст.98 —
# «Белякова»), а onec_export._subs_fio его не добавлял, и в 1С уезжала пустая
# клетка при той же смене. То же с переработкой оператора: в Excel она не
# считается расхождением, когда выросла из времени работы станка по счётчику
# (правило 03.09.2026), а в 1С красная строка оставалась. Разъезжаются цифры там,
# где их сверяет человек, поэтому правила переехали сюда — считать может только
# один код.

def submen_hours(r) -> float:
    """Часы подмен для колонок — окно, названное подменой, а не сумма по людям.

    Трое на одном окне дают по людям 17,46 ч при смене 12 ч (прогон 22.09.2026,
    ст.151), поэтому у колонки своё основание.

    Запасного пути «если окна нет — брать записанные мастером r.subs_hours»
    больше НЕТ: он печатал ровно те часы, которые правило отвергло.
    Прогон 27.09.2026, ст.111: «16:29 Стоп на подмену. Сошла шпуля №7» — партия
    шпуль (в течение дня «Подмена 6 из 15»), а не человек у машины; в его файле
    клетка пустая, а код клал туда 1,37 ч из r.subs_hours.
    Прогон 10.09.2026, ст.251: 9,42 ч «подмен» собрались из «работа стажёра:
    мониторинг навивки шпулей, стоп и пуск машин» — станок в это время шёл,
    подменщика у машины не было.
    Прогон 24.09.2026, ст.321: 0,35 ч «меняю на шпулярнике с малым количеством
    шнура» — оператор у СВОЕЙ машины, то есть не подмена (см. is_submen_window).

    В ручном файле пользователя (27.09) клетка «подмены, ч» заполнена ТОЛЬКО
    вместе с фамилией в «фио на подменах» — значит основанием служит названное
    окно с названным человеком, а не цифра разбора. Нет окна → пустая клетка.
    """
    window = getattr(r, "subs_window_hours", 0.0) or 0.0
    if window > 0.01:
        return round(window, 2)
    return 0.0


def submen_names(r) -> List[str]:
    """Кто стоял на подменах: привлечённые люди и сам оператор, если подмену
    делал он. Наладчик сюда не попадает (решение пользователя 27.08.2026).

    Оператор, отсутствовавший всю смену, в списке не появляется: «подмена 1 из 6»
    из утреннего блока — это цифры вчерашнего дня, а не работа человека
    (прогон 21.09.2026, ст.321).
    """
    names: List[str] = []
    hours = submen_hours(r)
    operator = str(r.operator).strip() if r.operator else ""
    if operator and hours > 0.01 and not r.operator_absent_all_shift:
        names.append(operator)
    try:
        subs = r.attracted_subs()
    except Exception:
        subs = []
    for s in subs:
        who = (getattr(s, "performer", "") or "").strip()
        if who and who not in names:
            names.append(who)
    return names


def submen_fio(r) -> str:
    """Строка колонки «фио на подменах» (через пробел, как в бланке).

    Фамилии, которые назвал мастер (r.subs_fio), ПРИБАВЛЯЮТСЯ к списку, а не
    заменяют его: как только часы окна посчитались, submen_names добавляет
    оператора, и прежний запасной путь («если список пуст — брать subs_fio»)
    терял названного подменщика. Прогон 27.09.2026, ст.251: в его файле
    «Петровский», а у нас в клетке осталось одно «Гудкова».
    """
    names = submen_names(r)
    for who in re.split(r"[,;]", str(getattr(r, "subs_fio", "") or "")):
        who = who.strip()
        if who and who not in names:
            names.append(who)
    return " ".join(names)


# ──── колонка P «Доп. работы (шт, кг)» ────────────────────────────────────

# Эталон владельца (Книга1, лист 27.09.2026, станок 98): «замена шпуляриника
# в течении смены + 26 машина в подработке». Это ЕГО слова о деле, которое
# оператор делал не на своей машине, — часы при этом остаются там же, где
# были посчитаны (в блоке оператора), поэтому P ничего не перекладывает.
#
# Строки блока оператора бывают двух сортов: пересказ события нашим кодом
# («работа по контролю за работой машины», «подмена (заправка полотна) (2
# раз)») и дословная фраза мастера («замена шпулярника в течении смены / 26
# машина в подработке»). В P идут только дословные: они и несут те самые
# «шт, кг», которые мастер называет сам («подставляла шпулярник, 205 шт.»,
# «привязывал 115 бобин»).
_SYSTEM_ROW_PREFIXES = ("работа по контролю", "работа машины", "простой",
                        "отсутствие оператора", "обед", "навивка/намотка",
                        "намотка полотна", "прочее", "без указанной причины")

# Номер СТАНКА. Сильный признак — слово «машина» рядом с цифрами: «на 151
# машину», «с 121 машины», «78 маш.», «работаю на 26 машине», «машину 251».
# Время станком не считается — «7.00 машина в работе» номера не даёт (цифры не
# могут быть хвостом числа с точкой, двоеточием или запятой), и голый номер без
# слова («Шпинделя №1») считается станком только если он есть в парке.
_MACHINE_NUM_RE = re.compile(
    r"(?<![\d.:,\-])(\d{1,3})\s*(?:машин\w*|маш\.|маш\b)"
    r"|(?:машина|машину|машине|машин\w*)\s*№?\s*(?<![\d.:,\-])(\d{1,3})"
    r"|(?<![\d.:,\-])(\d{2,3})\s*м\b"
    r"|№\s*(\d{1,3})",
    re.I)

# Дело на шпулярнике — глагол работы РЯДОМ со словом «шпулярник» (в пределах
# одной фразы). «Сход нити со шпулярника» — причина дефекта, а не работа, и
# в колону не попадает.
_BEAM_JOB_RE = re.compile(
    r"(?:замен\w*|подмен\w*|подстав\w*|привяз\w*|осмотр\w*|наведени\w*"
    r"|меня[юе]|менял|меняли)[^.;]{0,40}?шпулярник"
    r"|шпулярник\w*[^.;]{0,40}?(?:замен\w*|подмен\w*|подстав\w*|привяз\w*"
    r"|осмотр\w*|наведени\w*)", re.I)

# Голый номер из парка без слова «машина»: «ушел на 251 смотреть ошибку»,
# «приглашена на 321 по вопросу навивки», «вернулась с 321». За станок не
# считаем: часть разрядного счётчика («229 273» — номеру нельзя примыкать к
# другой цифре через пробел), долю («1,405–1,410»), время («15:48») и
# количество («на 98 шт», «250 из 250»).
_BARE_PARK_NUM_RE = re.compile(
    r"(?<![\d.,:×\-–—])(?<!\d )"
    r"(\d{2,3})"
    r"(?![\d×\-–—])(?![.,:]\d)(?!\s\d)"
    r"(?!\s*(?:шт|шп\w*|бобин|из|кг|узл|мин|сек)\b)", re.I)


def _foreign_machine_number(text: str, own_key: str) -> bool:
    """В строке назван номер станка, отличный от своего («26 машина в
    подработке», «работа на машине №251»). Свой номер — не доп. работа:
    мастер описывает свою машину («151м в работе»)."""
    park = {machine_rates._norm_key(m) for m in machine_rates.known_machines()}
    for match in _MACHINE_NUM_RE.finditer(text):
        num, weak = ((match.group(1) or match.group(2) or match.group(3)),
                     False)
        if num is None:
            num, weak = match.group(4), True
        key = machine_rates._norm_key(num) if num else ""
        if not key or key == own_key:
            continue
        if not weak or key in park:
            return True
    for match in _BARE_PARK_NUM_RE.finditer(text):
        if match.group(1) != own_key and match.group(1) in park:
            return True
    return False


def extra_works(r) -> List[str]:
    """Дополнительные работы станка за смену — дословные слова мастера.

    Основание: чужой номер машины, слово «подработка» или дело на
    шпулярнике. Системные ярлыки строк (контроль, простой, отсутствие,
    обед, склейка «(N раз)») в колонку не идут: они пересказ нашего кода,
    а не названная работа.
    """
    own_key = machine_rates._norm_key(getattr(r, "machine", "") or "")
    out: List[str] = []
    for desc, _hours in getattr(r, "operator_work_by_reason", list)() or []:
        text = " ".join(str(desc or "").split())
        if not text or re.search(r"\(\d+ раз\)$", text):
            continue
        low = text.lower()
        if any(low.startswith(p) for p in _SYSTEM_ROW_PREFIXES):
            continue
        if ("подработк" in low or _BEAM_JOB_RE.search(text)
                or _foreign_machine_number(text, own_key)):
            if text not in out:
                out.append(text)
    return out


def extra_works_text(r) -> str:
    """Колонка P одним текстом: работы через « + », как в файле владельца."""
    return " + ".join(extra_works(r))


def discrepancy_flags(r) -> List[tuple]:
    """Что считать расхождением смены: [(«станок», −3,2), («оператор», +0,69)].

    Знак говорит, чего не хватает (−) или чего больше (+). Нормы: станок 12 ч,
    оператор — его смена. Если баланс считать нельзя (нет нормы или счётчика),
    расхождения нет: иначе отчёт придумает недостаток (правило «нет данных»).
    Переработка оператора, выросшая из времени работы станка по счётчику,
    расхождением НЕ считается (правило 03.09.2026: часы человека не урезаем).
    """
    flags = []
    if getattr(r, "machine_shortfall", 0):
        flags.append(("станок", -round(r.machine_shortfall, 2)))
    elif getattr(r, "machine_excess", 0):
        flags.append(("станок", round(r.machine_excess, 2)))
    if getattr(r, "operator_shortfall", 0):
        flags.append(("оператор", -round(r.operator_shortfall, 2)))
    elif getattr(r, "operator_excess", 0):
        if not getattr(r, "excess_from_machine_time", False):
            flags.append(("оператор", round(r.operator_excess, 2)))
    return flags


def discrepancy_text(r, num) -> str:
    """Красная строка расхождения; `num` — формат чисел конкретной выгрузки."""
    parts = []
    for who, value in discrepancy_flags(r):
        if who == "станок":
            parts.append(f"станок −{num(-value)} ч до 12 ч" if value < 0
                         else f"станок +{num(value)} ч сверх 12 ч")
        else:
            parts.append(f"оператор −{num(-value)} ч" if value < 0
                         else f"оператор +{num(value)} ч")
    if not parts:
        return ""
    return "!!! РАСХОЖДЕНИЕ: " + "; ".join(parts)


def has_swap_marker(text: Optional[str]) -> bool:
    """В тексте есть слово операции замены (шпуль, бобин, шпулярника)."""
    low = (text or "").lower()
    return any(m in low for m in _SUBMEN_MARKERS)


def is_real_submen(reason: str) -> bool:
    """Событие с kind «подмена» действительно про подмену шпуль/полотна.

    Модель ставит kind «подмена» и там, где подмены нет: прогон 22.09.2026,
    ст.111 — запись «16:22 полотно вытянули, приподняв вал (Пронкин, Сеньков,
    Клинов)» вернулась ТРЕМЯ событиями «подмена» по 7 минут. Итог: наладчик
    Пронкин попал в «фио на подменах» (в ручном файле пользователя его там нет
    — время наладки идёт только в простой машины, решение от 27.08.2026), а
    «подмены, ч» стали 4,37 вместо эталонных 4,25.

    Различаем по тексту причины, а не по метке модели: подмена — это про шпули,
    бобины и шпулярник.

    Здесь решается ТОЛЬКО то, что операция названа, то есть станок в эти минуты
    стоял. Была ли она подменой ЧЕЛОВЕКА, решает `is_submen_window`: замена
    бобин и катушки подменой не считается (приказ владельца 30.09.2026), но
    простым станка быть не перестаёт. Без этой разницы 56 окон «Замена N бобины»
    вместе с колонкой «подмены, ч» потеряли бы и свои часы в технических
    остановках (ст.321 за 29.09 — 7,32 ч; ст.251 за 15.09 — 0,55 ч).
    """
    low = (reason or "").lower()
    if _REPAIR_RE.search(low):
        return False
    return has_swap_marker(low) or has_swap_marker(classify_stop(low)[0])


# «После замены шпулярника» — та же замена, но УЖЕ закончившаяся: чем мастер
# занят после неё, то и пишет (уборка, транспортировка коробок). Вырезаю такое
# придаточное до глагола, чтобы прошлое время не выдавалось за идущую подмену.
_AFTER_SWAP_RE = re.compile(
    r"после[^.;,!?]{0,25}?(?:шпул|бобин|бабин)\w*[^.;,!?]{0,30}",
    re.IGNORECASE)


def creel_change_now(reason: str) -> bool:
    """Замена шпулярника/бобин происходит СЕЙЧАС, а не упомянута вскользь.

    Подмену по kind «работа» я разрешил из-за ст.321 за 24.09.2026: «13:03 Меняю
    на шпулярнике с малым количеством шнура для подвивки шпулей» модель вернула
    как работу, а станок в это время стоял. Тот же шаг на 22.09.2026, ст.151
    поймал и чужие строки — «сортировка ченарышей со шпулярника» и «уборка
    площадки … после замены шпулярника» (13:00–14:05, 1,87 ч), и они раздули
    «подмены, ч» с эталонных 8,9 до 9,98. Разводит их глагол операции: шпулярник
    меняют («меняю на шпулярнике»), а не сортируют рядом с ним нити.
    """
    low = (reason or "").lower()
    return is_swap_stop(_AFTER_SWAP_RE.sub(" ", low))


def _describe(label: str, count: int, reason: str = "") -> str:
    """Описание операции для блока: деталь мастера или «label (N раз)»."""
    text = (reason or "").strip() or label
    if count > 1:
        return f"{label} ({count} раз)"
    return text


def _times_word(count: int) -> str:
    """«2 раза», «5 раз» — по-русски."""
    tail = count % 10
    if count % 100 not in (11, 12, 13, 14) and tail in (2, 3, 4):
        return f"{count} раза"
    return f"{count} раз"


def _group_untimed(texts) -> List[tuple]:
    """Записи без времени → [(самая короткая формулировка, сколько раз)].

    Складываем по смыслу (classify_stop), чтобы пять «чинка кромки» не заняли
    полстроки. Порядок — как в переписке.
    """
    groups: dict = {}
    order: List[str] = []
    for raw in texts or []:
        text = " ".join(str(raw or "").split())
        if not text:
            continue
        label = classify_stop(text)[0]
        key = text.lower() if label in ("прочее", "без указанной причины",
                                        UNEXPLAINED_LABEL) else label
        if key not in groups:
            order.append(key)
            groups[key] = [0, text]
        g = groups[key]
        g[0] += 1
        if len(text) < len(g[1]):
            g[1] = text
    return [(groups[k][1], groups[k][0]) for k in order]


def _summarize_untimed(texts, max_items: int = 4, max_len: int = 150) -> str:
    """«подстановка бобин, чинка кромки (4 раза), упаковка гильз и др.»."""
    groups = _group_untimed(texts)
    parts = []
    for text, cnt in groups[:max_items]:
        short = text if len(text) <= 46 else text[:43].rstrip() + "…"
        parts.append(f"{short} ({_times_word(cnt)})" if cnt > 1 else short)
    out = ", ".join(parts)
    if len(groups) > max_items:
        out += " и др."
    if len(out) > max_len:
        out = out[:max_len - 1].rstrip(" ,") + "…"
    return out


@dataclass
class ShiftMachineReport:
    machine: Optional[str] = None
    operator: Optional[str] = None
    brand: Optional[str] = None
    date: Optional[str] = None
    lines: List[ProductLine] = field(default_factory=list)
    cuts: Optional[int] = None
    subs_count: Optional[int] = None
    subs_hours: float = 0.0
    subs_fio: Optional[str] = None
    tech_stops: List[TechStop] = field(default_factory=list)
    operator_shift_end: Optional[str] = None   # «15:30» → короткий обед
    # Норма оператора, если она названа словами («смена 8 часов», «из 8 часа»,
    # сокращённая смена стажёра). Прогон 14.09.2026, ст.321: оператор — стажёр
    # Демидов, в эталоне пользователя его норма 8 ч, а бот печатал «из 11,25»
    # и получал ложное превышение +0,75 ч. None — код считает норму сам
    # (присутствие минус обед).
    operator_norm_hours: Optional[float] = None
    # Передача смены: если оператор сдал станок другому человеку в середине
    # смены (эталон 25.08, ст.321: Арташина → Сотволдиев в 08:20), первый
    # оператор считается только до передачи, а принявший ведёт станок до конца
    # смены и его часы идут в ПРИВЛЕКАЕМЫЙ персонал (это не подмена на пару
    # минут, а полноценная работа за станком вместо ушедшего оператора).
    operator2: Optional[str] = None          # кто принял станок
    operator2_start: Optional[str] = None    # во сколько принял («08:20»)
    # Поздний приход / ранний уход С ЭТОГО станка. Если оператор пришёл на
    # станок позже 07:00 (был занят на другом станке), то время ДО прихода —
    # это отсутствие оператора на станке (простой), а НЕ его недостаток
    # времени. Зеркало передачи смены (там оператор уходит рано, тут —
    # приходит поздно). Пример 26.08, ст.321: Камбаров весь день на 251, на
    # 321 пришёл только в 17:02.
    operator_start: Optional[str] = None     # во сколько пришёл на станок
    # Во сколько по ЭТОМУ станку появилась первая информация в переписке
    # (первое сообщение о станке, первое показание счётчика, первая операция).
    # Смена у всех начинается в 07:00, поэтому пустое начало смены — это время,
    # когда станок стоял без своего оператора (правило пользователя
    # 03.09.2026). В отличие от operator_start это НЕ свидетельство прихода
    # человека, а отсутствие данных, поэтому и ярлык, и предупреждение другие,
    # и применяется поле только когда в балансе станка есть свободное место
    # (см. data_gap_before_shift).
    first_info_time: Optional[str] = None
    # Время, которым мастер ЗАКРЫЛ смену («16:00-16:15 заполнение журнала и
    # чата»), в минутах от полуночи. Используется, когда явного «конец смены /
    # 19:00» в разделе нет: см. _operator_end_span.
    closing_activity_end: Optional[int] = None
    # Обед прошёл при РАБОТАЮЩЕМ станке: его принял другой человек (плавающий
    # обед 16.09.2026). Тогда строки «простой обед» нет — см. lunch_in_downtime.
    lunch_handed_over: bool = False
    lunch_recorded: bool = False   # обед пришёл отдельным интервалом
    # Окно обеда принадлежит ОПЕРАТОРУ ЭТОГО станка (а не коллеге, чей обед
    # описан в том же разделе при плавающем обеде). См. _events_to_stops_and_subs.
    lunch_window_mine: bool = False
    # Окно обеда в минутах от полуночи, если мастер назвал его временем
    # («11:30-12:15 обед»). None → берём стандартные 12:00–12:45.
    lunch_window: Optional[Tuple[int, int]] = None
    # Причины остановок, написанные БЕЗ времени («крючок не взял петлю»,
    # «вызываю наладчика»). В часы их поставить нельзя, но и терять нельзя:
    # именно они обычно и объясняют «недостаток времени».
    untimed_stops: List[str] = field(default_factory=list)
    # Из них — операции САМОГО оператора (исполнитель не назван или это он).
    # Правило пользователя 03.09.2026: «работу оператора пишите точнее, а не
    # просто работа за машиной — они для этого и пишут свои сообщения, что
    # делали». Часов у них нет, но названия обязаны попасть в расшифровку его
    # часов (ст.321 за 02.09: подстановка бобин, чинка кромки, упаковка гильз).
    untimed_own: List[str] = field(default_factory=list)
    # Простои, которым время достроил код из пар «стоп … пуск» в переписке
    # (мастер писал их РАЗНЫМИ сообщениями, и в одной строке интервала нет).
    # Список строк «11:20–11:48 чинка … — конец из переписки: «…»» — чтобы
    # мастер видел, где бот считал сам, а где цифру он ему не придумал.
    log_timed_stops: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    # Станок ЕСТЬ в переписке, но ИИ не вернул по нему разбор. Нулевые строки
    # такого станка нельзя показывать как «нет данных о работе» — это не
    # простаивавшая машина, а потерянные цифры (прогон (8): так исчез ст.98).
    not_parsed: bool = False
    # Привлекаемый персонал: часы людей, кроме оператора, отработанные на ЭТОМ
    # станке (подмены, наладка). Часть приходит из событий самого станка
    # (performer ≠ оператор), часть — переносом с других станков (оператор
    # другого станка ушёл сюда на подмену). Заполняется в build.
    attracted: List[TechStop] = field(default_factory=list)
    # Часы, которые ОПЕРАТОР ЭТОГО станка отработал на ДРУГИХ станках, но
    # записаны они были в переписке по тому, другому станку (напр. «замена
    # шпулярника на 151: Камбаров 58 бабин», а Камбаров — оператор 251).
    # По методике пользователя (эталон 27.08: у Камбарова в блоке 251 стоят
    # «работа на машине №111 1,67» и «работа на машине №151 2,5») такие часы
    # ОБЯЗАНЫ попасть в работу оператора его собственного станка. Заполняется
    # переносом в build_shift_reports_from_structured.
    elsewhere_extra: List[TechStop] = field(default_factory=list)
    # Станки, куда уходил оператор ЭТОГО станка и где его часы ДЕЙСТВИТЕЛЬНО
    # посчитаны — потому что он там штатный оператор (эталон 26.08: Камбаров с
    # 321 весь день оператор на 251). Заполняет build. Нужен для честной
    # строки отсутствия: «часы посчитаны там» обещает, что их ждут в другом
    # отчёте, и писать это можно только когда там их действительно считают.
    # Если человек оставался своим оператором здесь, его уход — работа в ЕГО
    # блоке по этому станку, а не часы чужого отчёта.
    absence_credited_machines: List[str] = field(default_factory=list)
    # Идёт ли сейчас продвижение «параллельных» операций (см. _promoted_parallel).
    # Нужен как страж рекурсии: чтобы померить настоящую дыру до 12 ч, продвижение
    # на минуту выключают и читают unexplained_downtime — а оно снова зовёт
    # nonabsence_stops. В расчёт отчёта поле не входит.
    _promoting: bool = field(default=False, repr=False, compare=False)

    # ——— расчётные величины ———
    @property
    def rate(self) -> Optional[float]:
        return machine_rates.get_rate(self.machine)

    @property
    def work_hours(self) -> float:
        total = 0.0
        for ln in self.lines:
            h = machine_rates.work_hours(
                self.machine, ln.counter_start, ln.counter_end)
            if h:
                total += h
        return round(total, 2)

    @property
    def output_total(self) -> float:
        return sum((ln.output or 0.0) for ln in self.lines)

    @property
    def stopped_stops(self) -> List[TechStop]:
        """Остановки, при которых станок действительно стоял."""
        return [s for s in self.tech_stops if s.machine_stopped]

    @property
    def own_sub_stops(self) -> List[TechStop]:
        """Устарело (правило 8 отменено): подмена на своей машине теперь = ПРОСТОЙ.

        Пользователь уточнил (26.08.2026): при подмене станок стоит, и это
        простой станка (причина «подмена»), одновременно идущий в работу
        оператора. Поэтому свои подмены больше не выносим на «рабочую» сторону.
        Оставлено пустым для совместимости со старым кодом.
        """
        return []

    @property
    def regular_stops(self) -> List[TechStop]:
        """Реальные простои станка (включая свои подмены — станок стоит)."""
        return list(self.stopped_stops)

    @property
    def own_subs_hours(self) -> float:
        """Устарело: свои подмены теперь в простое станка, не в работе."""
        return 0.0

    @property
    def parallel_stops(self) -> List[TechStop]:
        """Операции оператора при РАБОТАЮЩЕМ станке (навивка шпуль и т.п.)."""
        return [s for s in self.tech_stops if not s.machine_stopped]

    def _lunch_trim(self, lunch: float, other_rows: float) -> float:
        """Сколько из строки «обед» снять, чтобы строки не превысили 12 ч.

        Снимаем ТОЛЬКО избыток сверх 12 ч, а не всё пересечение. Причина: в
        эталоне пользователя 01.09 ст.121 наладка на всю смену уже урезана на
        обед внутри _naladka_minus_test_run (10,49 = 12 − 0,75 обед − 0,76
        работа), и строка «обед 0,75» там НЕ задвоение — вместе они дают ровно
        12 ч. А на ст.321 за 10.09.2026 интервалы операций закрыли 07:00–19:00
        целиком, и обед добавился сверху: 12,75 ч строк при смене 12 ч.
        """
        if lunch <= 0.01:
            return 0.0
        overflow = other_rows + lunch - MACHINE_SHIFT_HOURS
        if overflow <= 0.01:
            return 0.0
        return round(min(lunch, overflow, self._lunch_overlap_in_stops()), 2)

    def _lunch_overlap_in_stops(self) -> float:
        """Сколько минут обеда уже лежит ВНУТРИ интервалов простоя станка.

        Мастера пишут операции крупными окнами («07:00–12:40 навиваю шпули на
        подмену»), и стандартный обед 12:00–12:45 оказывается внутри такого
        окна. Тогда отдельная строка «обед 0,75» задваивает те же 45 минут, и
        строки простоя в сумме дают 12,75 ч при смене 12 ч (прогон 10.09.2026,
        ст.321).

        Вычитаем ровно ПЕРЕСЕЧЕНИЕ и только когда оно есть: строка обеда
        остаётся в отчёте (эталон пользователя её содержит), но сумма строк
        перестаёт превышать 12 ч. Если станок работал по счётчику, пересечение
        не вычитается — наложение счётчика на обед задвоением не считается
        (см. machine_excess).
        """
        if self.lunch_in_downtime <= 0.01:
            return 0.0
        a, b = self.lunch_window_min
        covered: List[Tuple[int, int]] = []
        for s in self.tech_stops:
            if s.start_min is None or s.end_min is None:
                continue
            lo, hi = max(s.start_min, a), min(s.end_min, b)
            if hi > lo:
                covered.append((lo, hi))
        # _union_hours уже отдаёт ЧАСЫ (внутри делит на 60) — второй раз не делим.
        return round(_union_hours(covered), 2) if covered else 0.0

    def _nonabsence_base(self) -> List[TechStop]:
        """Простои станка БЕЗ отсутствия оператора — ровно как их описал мастер.

        В этом списке одни и те же минуты могут занимать ДВЕ разные причины:
        станок передан в наладку, а оператор в это же время чинит пропуски.
        С задвоением разбирается _deduped_nonabsence.
        """
        stops = [s for s in self.regular_stops if not s.is_absence]
        if self.zero_output_all_shift:
            # Счётчик ДОКАЗАЛ, что станок не дал ни одного узла: значит он
            # стоял всю смену, и ЛЮБАЯ операция людей в это время — простой
            # станка, даже та, что помечена параллельной (приём сырья,
            # навивка шпуль, подготовка машины к подмене, перестановка телег).
            # Прогон 16.09.2026, ст.321: параллельные 5,09 ч не попали в
            # простой, баланс съехал на 4,8 ч, а 7,2 ч ушли в «причина не
            # указана». В эталоне пользователя простой 321-й собран именно из
            # операций людей: 3,58 навивка + 4,57 подмена + 3,78 отсутствие.
            have = {id(s) for s in stops}
            stops = stops + [s for s in self.parallel_stops
                             if id(s) not in have and not s.is_absence]
        return stops

    @property
    def nonabsence_stops(self) -> List[TechStop]:
        """Простои станка без отсутствия, в которых минута учтена ОДИН раз.

        Отсутствие оператора (ушёл на другой станок / пришёл поздно / сдал
        смену) считается ОДНОЙ строкой-заглушкой operator_absence_hours,
        которая добивает баланс станка до 12 ч. Если такие простои учитывать
        ещё и здесь, они задваиваются и станок «перерабатывает» сверх 12 ч
        (баг 26.08 на ст.321: две строки «отсутствие оператора» по 10 ч).
        """
        return self._deduped_nonabsence()[0]

    def _deduped_nonabsence(self) -> Tuple[List[TechStop], Dict[str, float]]:
        """Снять минуты, которые станок «стоял» дважды по двум причинам.

        Возвращает (записи простоя, {ярлык: снято часов}).

        Станок не может стоять в одних и тех же минутах по двум причинам — он
        просто стоит. Пока это правило не работало, прогон 25.09.2026, ст.111:
        наладка 09:35–13:48 (4,22 ч) и чинка оператором внутри неё дали строки
        «наладка 5,88 + чинка 4,47» при смене 12 ч и работе по счётчику 3,53 ч,
        то есть станок «простоял» 14,78 ч. Пользователь: «машина была в наладке
        и в это время производилась чинка, из за этого вышло задвоение часов,
        надо исправить, чтобы таких ошибок не повторялось».

        Снимаем со строки, которая описывает ДЕЛО внутри чужого окна, а не с
        окна-обёртки (longer_first): состояние машины («машина в наладке») —
        причина её простоя, а чинка оператора в те же минуты остаётся в ЕГО
        часах (часы человека считаются по другому набору записей и здесь не
        режутся).

        Второй проход нужен потому, что «параллельные» операции продвигаются в
        простой уже после первого снятия (см. _promoted_parallel) и могут
        наложиться на названные остановки.

        Снятое не прячем: ярлыки и часы возвращаются вторым значением и
        называются в отчёте (см. cross_label_deduped). Для станка, который
        простоял всю смену (zero_output_all_shift), окна — это операции одного
        человека, и там действует прежнее правило «снимается с той операции, что
        началась позже»: эталон пользователя по ст.321 за 15.09 («8,25 навивка +
        3,0 отсутствие + 0,75 обед») держит подробную навивку, а не обёртку.
        """
        base = self._nonabsence_base()
        if self.zero_output_all_shift:
            # Окна операций ПЕРЕКРЫВАЮТСЯ, а простой станка — это длина их
            # объединения, а не сумма. Одно и то же время снимаем с операции,
            # которая началась позже (тот же приём, что в
            # _squeeze_time_overlaps для часов оператора). Без этого событие-
            # обёртка на всю смену («машина на подмене» 07:00–16:20) складывалась
            # с подробными записями внутри себя, и ст.321 за 15.09.2026 получал
            # 20,13 ч простоя вместо 12.
            final = self._squeeze_time_overlaps(base)
            return final, self._dedup_lost(base, final)
        deduped = self._squeeze_time_overlaps(base, longer_first=True)
        promoted = self._promoted_parallel(deduped)
        if not promoted:
            return deduped, self._dedup_lost(base, deduped)
        final = self._squeeze_time_overlaps(deduped + promoted,
                                            longer_first=True)
        return final, self._dedup_lost(base + promoted, final)

    def _dedup_lost(self, raw: List[TechStop],
                    final: List[TechStop]) -> Dict[str, float]:
        """Сколько часов ПОТЕРЯЛА каждая строка простоя после снятия минут.

        Сравниваем то, что строки показали бы ДО и ПОСЛЕ (_groups_for), а не
        «снятые минуты» из самого снятия: наложение окон внутри ОДНОЙ причины
        объединяется и там и там, поэтому в разницу попадают только настоящие
        задвоенные минуты между РАЗНЫМИ причинами — ровно те, что видит
        пользователь в отчёте.
        """
        after = self._groups_for(final)
        out: Dict[str, float] = {}
        for label, (hours, _a) in self._groups_for(raw).items():
            gap = round(hours - after.get(label, (0.0, None))[0], 2)
            if gap > 0.01:
                out[label] = gap
        return out

    @property
    def cross_label_deduped(self) -> float:
        """Сколько часов простоя снято со строк как повторные минуты."""
        return round(sum(self._deduped_nonabsence()[1].values()), 2)

    @property
    def cross_label_dedup_detail(self) -> List[Tuple[str, float]]:
        """[(ярлык строки, снято часов)] — по убыванию, для объяснения в отчёте."""
        return sorted(((label, hours) for label, hours
                       in self._deduped_nonabsence()[1].items()
                       if hours > 0.01), key=lambda x: -x[1])

    def _groups_for(self, stops: List[TechStop]) -> dict:
        """Группировка ЛЮБОГО набора остановок по ярлыку: label→(часы, оператор).

        Окна одной причины объединяются, операции без времени складываются как
        есть — ровно то, что делает _nonabsence_grouped_raw для настоящего
        простоя станка. Метод нужен, чтобы «примерить» набор до того, как он
        попал в отчёт (см. _promoted_parallel).
        """
        groups: dict = {}
        intervals: dict = {}
        for s in stops:
            label = s.stop_label
            if s.start_min is not None and s.end_min is not None:
                ivs, active = intervals.get(label, ([], True))
                # Свободные минуты записи, а НЕ её сырое окно: иначе обёртка
                # «07:00–14:04 машина на подмене» заняла бы собой и навивку
                # 07:00–12:40, и ст.321 за 10.09 дала бы 16,25 ч простоя в
                # 12-часовую смену (прогон 25.09.2026).
                ivs.extend(s.windows_min)
                intervals[label] = (ivs, active and s.by_operator)
                continue
            hours, active = groups.get(label, (0.0, s.by_operator))
            groups[label] = (hours + s.hours, active and s.by_operator)
        for label, (ivs, iv_active) in intervals.items():
            hours, active = groups.get(label, (0.0, iv_active))
            groups[label] = (hours + self._union_hours_minus_lunch(ivs),
                             active and iv_active)
        return groups

    @staticmethod
    def _groups_hours(groups: dict) -> float:
        return round(sum(h for h, _a in groups.values()), 2)

    def _promoted_parallel(self, counted: List[TechStop]) -> List[TechStop]:
        """«Параллельная» операция при стоящем станке — это простой станка.

        Параллельной запись помечается потому, что станок в это время ЯКОБЫ
        крутился (навивка шпуль, развивка, подготовка машины). Единственное
        доказательство, что он действительно крутился, — время его работы по
        счётчику. Поэтому если после реальных остановок в смене остались часы,
        которым нечем объяснить станок, а мастер в эти минуты описывает
        «параллельную» работу, станок стоял, и часы обязаны уйти в простой с
        ЕГО ЖЕ причиной. Это то же правило, которое уже работает для станка с
        несдвинувшимся счётчиком (см. zero_output_all_shift выше), только там
        продвигаются все операции сразу.

        Ничего не выдумываем: берём ровно столько, сколько не хватает до 12 ч
        (по хронологии смены), и только те окна, которые не закрыты другим
        простоем. Куда записями покрыть нечего — остаётся честным
        «причина не указана».

        Прогон 22.09.2026, ст.111: счётчик 217649 → 217980 = 331 узел = 0,39 ч
        работы, а мастер описал 07:00–09:44 «продолжаю навивку шпулей»,
        15:17–17:00 и 17:00–18:45 «развивка шпулей» и 10:20–16:20 «стоп машина,
        пропуска». Отчёт выдавал «!!! РАСХОЖДЕНИЕ: станок −5 ч до 12 ч», хотя
        4,7 из этих 5 часов в переписке названы.

        Скользить правило вслепую НЕЛЬЗЯ: «параллельная» запись законна ровно в
        те минуты, когда станок крутился, а сколько он крутился — знает счётчик.
        Станок отработал 9,63 ч из 12 — навивка на 1,37 ч спокойно умещается в
        его работу, и снимать её в простой нельзя (тест
        test_composite_line_does_not_stop_our_machine: склейка «навивка на 251
        после протяжки на 321» не простой нашего станка). Станок отработал 0,39 ч
        — умещаться нечему, и весь остаток «параллельных» окон был при стоящей
        машине. Поэтому потолок продвижения — сумма параллельных окон МИНУС часы
        работы станка.

        Второй потолок важнее: дыра берётся ТАКАЯ, какой её оставили ВСЕ
        существующие механизмы (реальные простои, отсутствие оператора, именованный
        остаток до 12 ч — см. named_residual_hours). Продвигать поверх них нельзя,
        иначе продвижение снимает их работу и баланс падает. Прогон 10.09.2026,
        ст.98: работа 8,52 ч, названные простои 2,33 ч, обед 0,75 ч, и остаток
        0,4 ч уже подписан причиной длинного окна «замена шпулярника в течение всей
        смены». Дыры нет, и первое правило молчало; стоило посчитать дыру только
        по окнам — как 0,08 ч продвинулись, именованный остаток съехал ниже
        допуска, пропал, и станок стал показывать 11,69 ч вместо 12,0.
        """
        if self._promoting or self.balance_unknown or self.zero_output_all_shift:
            return []
        self._promoting = True
        try:
            # unexplained_downtime при выключенном продвижении = сколько часов
            # смены не объяснил НИ ОДИН механизм, включая именованный остаток.
            room = self.unexplained_downtime
        finally:
            self._promoting = False
        if room <= TOLERANCE_H:
            return []
        candidates = sorted(
            (s for s in self.parallel_stops
             if s.start_min is not None and s.end_min is not None
             and s.end_min > s.start_min),
            key=lambda s: (s.start_min, s.end_min))
        if not candidates:
            return []
        claimed = self._union_hours_minus_lunch(
            [(s.start_min, s.end_min) for s in candidates])
        room = min(room, round(claimed - self.work_hours, 2))
        if room <= TOLERANCE_H:
            return []
        taken: List[TechStop] = []
        for s in candidates:
            before = self._groups_for(counted + taken)
            after = self._groups_for(counted + taken + [s])
            added = round(self._groups_hours(after) - self._groups_hours(before),
                          2)
            if added <= 0.01 or added > room:
                continue          # окно уже занято или не влезает в остаток
            taken.append(s)
            room = round(room - added, 2)
            if room <= 0.01:
                break
        return taken

    def _nonabsence_grouped(self) -> dict:
        """Простои без отсутствия, сгруппированные по ярлыку: label→(часы, оператор_работал).

        Операции, идущие ОДНОВРЕМЕННО, занимают у станка не сумму часов, а длину
        общего окна (см. _union_hours): три человека на подмене 07:00–08:00 —
        это 1 ч простоя станка, а не 3. Их личные часы суммируются отдельно, в
        привлекаемом персонале. Правило действует для ЛЮБОЙ причины, у которой
        известен интервал (27.08, ст.151: четыре замены шпулярника дали станку
        5,53 ч и «+1,87 ч сверх 12», хотя часть шла одновременно). Операции без
        времени складываются как есть — окно неизвестно.
        """
        return self._naladka_minus_test_run(self._nonabsence_grouped_raw())

    def _nonabsence_grouped_raw(self) -> dict:
        """То же, но без поправки на пробные узлы наладчика (см. ниже)."""
        return self._groups_for(self.nonabsence_stops)

    def _union_hours_minus_lunch(self, ivs: List[Tuple[int, int]]) -> float:
        """Объединение окон простоя БЕЗ окна обеда.

        Обед — фиксированные 45 мин и он ВСЕГДА стоит отдельной строкой простоя
        (lunch_in_downtime). Если мастер записал состояние станка одним длинным
        окном (07:00–16:20 «машина на подмене»), обед оказывается ВНУТРИ него,
        и строка обеда снимается тримом как задвоение — а «отсутствие
        оператора» недобирает эти 0,75 ч.

        Прогон 15.09.2026, ст.321: бот печатал «9,33 подмена + 2,67 отсутствие»
        без строки обеда, а в эталоне пользователя «8,25 навивка шпуль + 3,0
        отсутствие оператора + 0,75 обед» — те же 12 ч, но обед виден отдельно,
        и остаток после ухода оператора (16:20–19:00) не урезан.

        Вычитаем ТОЛЬКО когда обед действительно встанет отдельной строкой
        (lunch_in_downtime > 0) и только фактическое пересечение.
        """
        total = _union_hours(ivs)
        if self.lunch_in_downtime <= 0.01 or not ivs:
            return total
        a, b = self.lunch_window_min
        inside = []
        for s, e in ivs:
            lo, hi = max(s, a), min(e, b)
            if hi > lo:
                inside.append((lo, hi))
        if not inside:
            return total
        return round(max(0.0, total - _union_hours(inside)), 2)

    @property
    def naladka_test_run_cut(self) -> float:
        """Сколько часов снято с наладки как время работы станка (пробные узлы)."""
        raw = self._nonabsence_grouped_raw().get(NALADKA_LABEL, (0.0, None))[0]
        fixed = self._nonabsence_grouped().get(NALADKA_LABEL, (0.0, None))[0]
        return round(max(0.0, raw - fixed), 2)

    def _naladka_minus_test_run(self, groups: dict) -> dict:
        """Пробные узлы наладчика — работа станка, и это время уходит ИЗ наладки.

        Правило пользователя (02.09.2026, ст.121 за 01.09): счётчик за смену
        сдвинулся (887105 → 887770 = 0,76 ч), потому что наладчики прогоняли
        пробные узлы. Время работы станка считаем КАК ЕСТЬ, а тот же час не
        может второй раз стоять в простое «наладка»: иначе смена длиннее 12 ч.
        Поэтому строка наладки уменьшается ровно на то время, которое машина
        реально крутилась (но не больше самой наладки).

        Два случая:
          * наладка описана НА ВСЮ СМЕНУ и других причин нет — внутрь этого
            окна попадают и обед, и пробные узлы: наладка = 12 − обед − работа
            (11,25 − работа). Это то же правило, что и для дня, полностью
            закрытого наладкой (naladka_all_shift), только там счётчик стоял;
          * наладка вместе с другими причинами переполняет 12 ч — снимаем с
            наладки только ИЗЛИШЕК, не больше времени работы станка. Наложение
            разных причин к этому излишку отношения не имеет: повторные минуты
            строк простоя сняты раньше (см. _deduped_nonabsence).

        Ничего не подгоняется: работа станка остаётся из счётчика, а наладка —
        единственная причина, внутри которой машина физически может крутиться.
        """
        if self.work_hours <= 0.01:
            return groups            # день без работы считает naladka_all_shift
        if self.work_hours > MACHINE_SHIFT_HOURS:
            return groups            # счётчик даёт больше смены — это уже флаг
        naladka, active = groups.get(NALADKA_LABEL, (0.0, None))
        if naladka <= 0.01:
            return groups
        lunch = self.lunch_in_downtime
        others = sum(h for lab, (h, _a) in groups.items()
                     if lab != NALADKA_LABEL)
        if (others <= 0.01
                and naladka + lunch >= MACHINE_SHIFT_HOURS - TOLERANCE_H):
            target = round(MACHINE_SHIFT_HOURS - lunch - self.work_hours, 2)
        else:
            overflow = (naladka + others + self.work_hours + lunch
                        - MACHINE_SHIFT_HOURS)
            cut = min(round(overflow, 2), self.work_hours, naladka)
            target = round(naladka - cut, 2)
        if target >= naladka - 0.01:
            return groups
        out = dict(groups)
        out[NALADKA_LABEL] = (max(target, 0.0), active)
        return out

    @property
    def tech_stops_total(self) -> float:
        return round(sum(h for h, _a in self._nonabsence_grouped().values()), 2)

    @property
    def parallel_hours(self) -> float:
        """Часы параллельных операций — в простой станка не идут."""
        return round(sum(s.hours for s in self.parallel_stops), 2)

    @property
    def absence_hours(self) -> float:
        """Часы, когда оператора не было у станка (единый источник).

        Совпадает с operator_absence_hours — одной строкой-заглушкой до 12 ч
        (см. её описание), чтобы отсутствие не задваивалось между простоями из
        сообщений и расчётом по времени прихода/ухода.
        """
        return self.operator_absence_hours

    @property
    def operator_stop_hours(self) -> float:
        """Часы работы ОПЕРАТОРА при остановленном станке (чинка, бобины…).

        Правило пользователя (03.09.2026, дословно): «если операции
        пересекаются между собой то просто брать максимум». Поэтому берём не
        сырую сумму записей, а единый источник own_operator_stops() — там уже
        снято наложение по времени (_squeeze_time_overlaps: пересечённые минуты
        считаются один раз, полностью вложенные записи дают максимум окна) и
        отфильтрован привлечённый персонал.

        Что было до этого: сумма по regular_stops с признаком by_operator, а он
        показывает лишь «кто-то работал», без проверки фамилии. На ст.151 за
        27.08 пятеро (Вашурина, Петровский, Бектошев, Камбаров, Абдулаев) меняли
        шпулярник ОДНОВРЕМЕННО, 16:15–18:50, и строка итога печатала 10,65 ч
        вместо 1,98 ч самой Вашуриной: чужие часы плюс пятикратный учёт одних и
        тех же минут. Простой станка при этом всегда считался правильно — по
        объединению окон, 2,58 ч (правило Р18: станку максимум, людям сумма).

        Работа на ДРУГИХ станках сюда не входит: у неё свои слагаемые
        (elsewhere и строки правила Р23), иначе она попадёт в итог дважды.
        """
        own = sum(s.hours for s in self.own_operator_stops()
                  if s.machine_stopped and not s.elsewhere
                  and not (s.label or "").startswith(ELSEWHERE_WORK_LABEL))
        return round(own, 2)

    @property
    def operator_elsewhere_hours(self) -> float:
        """Часы, которые оператор отработал на ДРУГОМ станке."""
        return round(sum(s.hours for s in self.tech_stops if s.elsewhere), 2)

    @property
    def operator_elsewhere_machines(self) -> List[str]:
        """Станки, на которые уходил оператор."""
        seen = []
        for s in self.tech_stops:
            if s.elsewhere and s.other_machine and s.other_machine not in seen:
                seen.append(str(s.other_machine))
        return seen

    # ——— привлекаемый персонал (все, кроме оператора этого станка) ———
    @property
    def attracted_own(self) -> List[TechStop]:
        """Операции на ЭТОМ станке, выполненные НЕ оператором станка.

        Подмены и наладки, у которых указан исполнитель, отличный от
        оператора. Их часы — работа привлечённого персонала на этой машине.

        Приблизительное время (hours_estimated) в часы человека НЕ идёт: в
        прогоне 01.09 на ст.111 из сообщения «информация от службы наладки
        (Каленюк Д.В.): ориентировочное окончание работ 10-00» наладчику
        начислили 3 ч, которых никто не подтверждал. В эталоне пользователя
        такой человек стоит в списке с нулём и пометкой «время не уточнено» —
        так и делаем: строка остаётся, часов нет. Простой станка при этом
        сохраняет своё время: машина действительно стояла.
        """
        op = (self.operator or "").strip().lower()
        res: List[TechStop] = []
        for s in self.tech_stops:
            if s.elsewhere:
                continue
            perf = (s.performer or "").strip()
            if not perf or perf.lower() == op:
                continue
            # Прикрытие НА ВРЕМЯ ОБЕДА коллеги — взаимный обмен, а не
            # привлечённый труд: часы уходят в блок того оператора, кто
            # работал на этой машине (см. _LUNCH_COVER_RE). Простой станка
            # при этом сохраняется — машина действительно стояла/работала.
            if _LUNCH_COVER_RE.search(s.reason or ""):
                continue
            res.append(replace(s, hours=0.0) if s.hours_estimated else s)
        return _dedupe_people(res)

    def _state_row_hours_unproven(self, s: TechStop) -> bool:
        """Окно на всю смену на станке без движения счётчика — состояние станка.

        Прогон 25.09.2026: «работы инженерной службы по креплению кордленты»
        07:00–19:00 на простаивавшей 121 и «в службе наладки» 07:00–19:00 на 151
        начислили Пронкину 12 + 12 ч, и вместе с его же 6,63 ч на 111 дали
        30,63 ч за 12-часовую смену. Такие строки описывают СОСТОЯНИЕ машины
        («весь день в инженерной службе», «в наладке»), а не подтверждённую
        смену человека: выпуска нет, ни один мастер не писал, сколько часов в
        этом окне отработал конкретный человек. Его часы — «время не уточнено»,
        как в прецеденте 01.09 (Каленюк, «ориентировочное окончание работ»).
        Простой станка при этом остаётся полным 12 ч: машина стояла.
        """
        if s.transferred or s.start_min is None or s.end_min is None:
            return False
        if self.work_hours > 0.01:
            return False
        window_h = (s.end_min - s.start_min) / 60.0
        return (window_h >= OPERATOR_SHIFT_HOURS - TOLERANCE_H
                and s.hours >= OPERATOR_SHIFT_HOURS - TOLERANCE_H)

    def attracted_all(self) -> List[TechStop]:
        """Свои привлечённые + перенесённые с других станков (уход оператора).

        Обед из часов привлечённого персонала НЕ вычитается — это проверено
        эталоном пользователя (01.09, ст.151: наладчику Пронкину за интервал
        08:00–14:00 стоит ровно 6,0 ч, без вычета 45 мин). Он работал на
        машине, пока станок стоял, и перерыва у него не было.

        А случай «мастер сам назвал часы меньше интервала» (10.09.2026, ст.251:
        стажёр 07:00–16:00, но «работа стажёра окончена (8,5 часов)») решается
        НЕ здесь: модель обязана отдать hours = 8.5 вместо интервала, см.
        правило 6.2971 промпта. Код чужие слова не переписывает.

        Строку-состояние «вся смена» на станке без выпуска из часов человека
        снимает `_state_row_hours_unproven`: человек без подтверждения своего
        времени остаётся в списке с нулём и пометкой «время не уточнено».

        Фамилию, которой нет в переписке этого станка (`performer_claimed`),
        отчёт печатает ролью: строка и её часы остаются, а в документе не
        появляется человек, который здесь не был. Меняем ПОСЛЕ `_dedupe_people`,
        иначе две разные непроверенные фамилии слились бы в одного «наладчика».
        """
        res = []
        for s in list(self.attracted_own) + list(self.attracted):
            if s.hours and self._state_row_hours_unproven(s):
                s = replace(s, hours=0.0,
                            reason=(s.reason or "работа")
                                   + " (время не уточнено)")
            res.append(s)
        out = []
        for s in _dedupe_people(res):
            if s.performer_claimed:
                s = replace(s, performer=_unproven_role(s.is_naladka))
            out.append(s)
        return out

    @property
    def attracted_total(self) -> float:
        return round(sum(s.hours for s in self.attracted_all()), 2)

    def attracted_subs(self) -> List[TechStop]:
        """Привлечённый персонал ТОЛЬКО по подменам (без наладок и прочей работы).

        Решение пользователя (27.08.2026): во втором листе финального файла
        (таблица «ДД.ММ») наладчик в подменах/привлечённых НЕ указывается —
        всё, что связано с наладкой, идёт только в простой машины с причиной
        «наладка». В первом листе («Пояснение ДД.ММ») наладчик остаётся.

        Только подмена, а не «любое не-наладочное событие» (прогон 22.09.2026,
        ст.251): в «фио на подменах» оказался «лола п.» — мастер, которая
        написала в чат распоряжение и стала исполнителем события «работа».
        """
        return [s for s in self.attracted_all()
                if not s.is_naladka
                and (s.is_sub or is_submen_label(s.stop_label))]

    @property
    def attracted_subs_total(self) -> float:
        return round(sum(s.hours for s in self.attracted_subs()), 2)

    @property
    def subs_window_hours(self) -> float:
        """Часы подмен = окно, которое мастер назвал подменой, а не сумма по людям.

        Прогон 22.09.2026, ст.151: трое людей на окнах 07:45–13:00,
        14:16–16:43 и 16:43–18:40 дали «подмены, ч» 17,46 при смене 12 ч —
        станок стоял один раз, а не трижды. В ручном файле пользователя там
        8,66 ч: окна складываются как окна.

        Правило отбора переехало в `is_submen_window` (27.09.2026): раньше здесь
        требовался стоящий станок, из-за чего Петровский на 251 (07:00–08:07,
        1,1 ч у пользователя) в колонку не попадал вовсе, а «замена катушки на
        шпулярнике», которую Демидов записал как остановку, попадала — 321
        давала 4,88 против его 3,33.
        """
        ivs = [(s.start_min, s.end_min) for s in self.tech_stops
               if s.start_min is not None and s.end_min is not None
               and is_submen_window(s, self.operator)]
        if not ivs:
            return 0.0
        # Обед из окна подмены вырезаем только тогда, когда окно НАКРЫЛО весь
        # перерыв: человек у машины в это время быть не мог, и в его файле
        # обед стоит отдельной строкой (22.09.2026, ст.111: «10:01–15:01
        # подмена шпулей» → 4,25, а не 5,00). Когда же окно задевает перерыв
        # только краем, часы мастера считаются целиком — станок в эти минуты
        # стоял с подменщиком у машины, и обед ему в окно никто не вставлял
        # (27.09.2026, ст.98: «12:20-13:10 подмена» → его 0,83, а не 0,42).
        lunch = self.lunch_window_min
        spanned = (self.lunch_in_downtime > 0.01 and lunch
                   and lunch[0] is not None
                   and any(s <= lunch[0] and e >= lunch[1] for s, e in ivs))
        return round(self._union_hours_minus_lunch(ivs) if spanned
                     else _union_hours(ivs), 2)

    @property
    def nothing_produced(self) -> bool:
        """Станок за смену ничего не произвёл и конца смены по счётчику нет.

        Тогда единственное показание и «Срез N из M» в разделе — это вчерашнее
        состояние из утреннего блока, которое мастер привёл как вводную. В
        ручном файле пользователя (22.09.2026, ст.121/601/14тр/15тр/251) такие
        станки идут с пустыми срезами и счётчиками, а не с чужими числами.

        Нулевой выпуск — то же самое, что незаписанный: счётчик за смену не
        сдвинулся (прогон 27.09.2026: ст.151 «1 из 1», ст.121 «3 из 3», ст.91
        «3 из 3» при двух одинаковых показаниях и S=6/12 из утреннего блока).
        Пока правило смотрело только на None, эти строки печатали вчерашние
        цифры, и колонки K/L/M/S разъезжались с его файлом.
        """
        if self.work_hours > 0.01:
            return False
        return not any(ln.output for ln in self.lines)

    def own_operator_stops(self) -> List[TechStop]:
        """Операции, которые за смену выполнил САМ оператор этого станка.

        ЕДИНЫЙ источник и для суммы (operator_explicit_hours), и для строк в
        Excel (operator_work_by_reason). Раньше сумма и строки считались по
        разной логике: в строки шли ВСЕ параллельные операции (parallel_hours,
        в том числе чужие — инструктаж Арташиной на 151), а в сумму — только
        свои. Из-за этого строки блока «Работа оператора» не складывались в
        свой же итог (151 за 27.08: 9,98 + 4,87 + … при итоге 11,25).

        Уход на другой станок ЗАСЧИТЫВАЕТСЯ в часы оператора (правило
        пользователя 27.08: «помощь этого оператора на других станках тоже идёт
        во время работы оператора»), КРОМЕ полного отсутствия — когда человек
        всю смену стоит на другом станке, где он штатный оператор, и его часы
        учтены там (26.08: Камбаров всю смену на 251 → на 321 отсутствие, а не
        11,5 ч работы). Признак ставится в build_shift_reports_from_structured:
        full_absence остаётся только если на целевом станке тот же оператор.

        Дальше список нормализуется ОДНИМ правилом физики: две операции «в
        течение всей смены» у одного человека шли одновременно, поэтому их часы
        не складываются, а берутся один раз (см. _merge_shiftlong_parallel).
        Никаких урезаний под норму и добивок нет — часы считаются как есть,
        расхождение показывается флагом (правило пользователя 28.08).
        """
        op = (self.operator or "").strip().lower()
        res: List[TechStop] = []
        for s in self.tech_stops:
            if s.elsewhere:                 # ушёл работать на другой станок
                if not s.full_absence:
                    res.append(s)
                continue
            perf = (s.performer or "").strip().lower()
            if perf and perf != op:         # это привлечённый персонал
                continue
            if s.machine_stopped:
                if s.by_operator:           # своя операция при стоящем станке
                    res.append(s)
            else:                           # параллельная операция
                res.append(s)
        # Часы, записанные по чужому станку, но отработанные нашим оператором.
        res.extend(self.elsewhere_extra)
        return self._cut_lunch_from_operator(
            self._squeeze_time_overlaps(self._merge_shiftlong_parallel(res)))

    @property
    def lunch_window_min(self) -> Tuple[int, int]:
        """Окно обеда в минутах от полуночи: из события либо 12:00–12:45."""
        if self.lunch_window and self.lunch_window[1] > self.lunch_window[0]:
            return self.lunch_window
        start = int((SHIFT_START_H + LUNCH_START_SPAN) * 60)
        return (start, int(start + LUNCH_FULL_H * 60))

    def _cut_lunch_from_operator(self, stops: List[TechStop]) -> List[TechStop]:
        """Обед — не работа оператора: вырезаем его окно из операций.

        Правило участка: обед ВСЕГДА 45 мин, входит в простой станка и НЕ
        входит в часы сотрудника. Но мастера пишут операции крупными
        интервалами («10:03–12:45 чинка полотна», «07:00–12:40 навиваю шпули
        на подмену»), и окно обеда оказывается ВНУТРИ такой записи.

        Прогон 10.09.2026, ст.321: интервалы Олега покрыли 07:00–19:00
        целиком, оператор получил 12,0 ч и ложный флаг «+0,75 ч сверх нормы» —
        ровно обед, которого он не отрабатывал.

        Простой СТАНКА при этом не меняется: там обед уже стоит отдельной
        строкой (lunch_in_downtime), и вырезать его второй раз нельзя.
        """
        a, b = self.lunch_window_min
        out: List[TechStop] = []
        for s in stops:
            if s.start_min is None or s.end_min is None:
                out.append(s)
                continue
            # Обед снимаем только с тех минут, которые у записи реально
            # остались (windows_min). С сырого окна — задвоение вычитания:
            # наложение уже снял _squeeze_time_overlaps. Прогон 10.09.2026,
            # ст.321: обёртка 07:00–14:04 после навивки 07:00–12:40 свободна с
            # 12:40, обеда в ней почти нет, а снималось все 45 мин — оператор
            # терял 0,67 ч и получал флаг «РАСХОЖДЕНИЕ: оператор −0,67 ч».
            overlap = sum(max(0, min(e, b) - max(st, a))
                          for st, e in s.windows_min)
            if overlap <= 0:
                out.append(s)
                continue
            hours = round(max(0.0, s.hours - overlap / 60.0), 2)
            if hours > 0.01:
                out.append(replace(s, hours=hours))
        return out

    def _squeeze_time_overlaps(self, stops: List[TechStop],
                               longer_first: bool = False
                               ) -> List[TechStop]:
        """Один человек не может делать два дела в одни и те же минуты.

        Если у операций известны интервалы и они пересекаются, в часы
        оператора идёт ОБЪЕДИНЕНИЕ окон, а не сумма: подмена 08:00–10:00 и
        подмена 09:00–11:00 — это 3 ч работы, а не 4. Пересечённая часть
        снимается с той операции, которая началась позже, — строки отчёта
        по-прежнему складываются в свой же итог.

        Вместе с часами запись получает и СВОЁ ОСТАВШЕЕСЯ окно (free_ivs):
        одних цифр часов не хватает, потому что обед и группировка простоя
        считаются по минутам. Без этого снятое наложение снова возвращалось в
        отчёт сырым окном (прогон 25.09.2026, ст.321 за 10.09: 16,25 ч простоя
        в 12-часовую смену).

        Это интервальная арифметика (то же, что _nonabsence_grouped делает
        для простоя станка), а не подгонка под норму: операции без времени
        и непересекающиеся окна остаются как есть.

        longer_first — для простоя СТАНКА (см. _deduped_nonabsence): когда две
        записи начались в одну минуту, занимает их минуты та, что ДЛИННЕЕ,
        потому что длинная запись — это состояние машины («09:35–13:48 машина в
        наладке»), а короткая — дело оператора внутри неё («09:35–10:12 чинка
        пропусков»). Для часов человека прежнее правило (короче — раньше) остаётся.
        """
        timed = [s for s in stops
                 if s.start_min is not None and s.end_min is not None
                 and s.end_min > s.start_min]
        if len(timed) < 2:
            return stops
        covered: List[tuple] = []
        fixed: dict = {}
        for s in sorted(timed, key=lambda x: (x.start_min,
                                              -x.end_min if longer_first
                                              else x.end_min)):
            # Минуты записи берём ЕЁ ОСТАВШИЕСЯ (windows_min), а не сырое окно:
            # иначе повторный проход снимал бы одни и те же минуты дважды.
            own = s.windows_min
            free = _subtract_intervals(own, covered)
            overlap = (sum(e - b for b, e in own)
                       - sum(e - b for b, e in free))
            covered = _merge_intervals(covered + list(own))
            if overlap <= 0:
                continue
            fixed[id(s)] = (round(max(0.0, s.hours - overlap / 60.0), 2), free)
        if not fixed:
            return stops
        res: List[TechStop] = []
        for s in stops:
            entry = fixed.get(id(s))
            if entry is None:
                res.append(s)
                continue
            hours, free = entry
            if hours > 0.01:
                res.append(replace(s, hours=hours, free_ivs=free or None))
        return res

    def _lunch_inside_long(self, long_ones: List[TechStop]) -> float:
        """Сколько обеда попало ВНУТРЬ сменной операции-обёртки.

        Обед — всегда 45 мин и в часы человека не входит (правило участка).
        Считаем пересечение окна обеда с объединением окон длинных операций;
        если окон нет (запись «на протяжении всей смены» без времени), берём
        полное окно обеда — человек всё равно обедал.
        """
        a, b = self.lunch_window_min
        windows = [(s.start_min, s.end_min) for s in long_ones
                   if s.start_min is not None and s.end_min is not None]
        if not windows:
            return LUNCH_FULL_H
        total = 0
        for s, e in _merge_intervals(windows):
            total += max(0, min(e, b) - max(s, a))
        return round(min(LUNCH_FULL_H, total / 60.0), 2)

    def _merge_shiftlong_parallel(self, stops: List[TechStop]
                                  ) -> List[TechStop]:
        """«Всю смену навивал шпули» + «всю смену работал на 78» = ОДНО время.

        Параллельные операции длиной во всю смену выполняются ОДНОВРЕМЕННО,
        поэтому их нельзя складывать: 12 + 12 не дают 24 ч работы. Бот в прогоне
        27.08 дал оператору ст.98 25,84 ч именно из-за сложения.

        Часы объединённой строки — самая длинная из них (общее время, которое
        человек был занят), причины перечисляются через « / ». Ничего не
        подгоняется под норму и не урезается до времени работы машины.

        Достаточно ОДНОЙ операции «на протяжении всей смены»: если человек занят
        весь день, то всё остальное, что за ним записано, шло ВНУТРИ этого же
        времени и прибавляться не может. Прогон 31.08, ст.98: «замена
        шпулярника на протяжении всей смены» 12 ч + две подмены по 0,83 ч
        (8:30–9:20 и 16:15–17:05, обе внутри смены) давали 13,66 ч при норме
        11,25. Остальные операции остаются ОТДЕЛЬНЫМИ строками (пользователь
        читает по ним смену), а сменная строка занимает остаток времени:
        12 = «замена шпулярника» 10,34 + «подмена (2 раза)» 1,66. Это не
        подгонка под норму: общее время взято из самой длинной записи мастера,
        а сумма строк по-прежнему равна operator_hours.

        Если сменная операция шла при РАБОТАЮЩЕЙ машине (замена шпулярника,
        подработка соседнего станка), она длится ровно столько, сколько машина
        работала по счётчику: человек ведёт её, пока она крутится, а когда
        машина встала — он занят уже другим делом (подмена, чинка), и это другое
        время ПРИБАВЛЯЕТСЯ. Так собраны оба эталона пользователя по ст.98:
        27.08 — работа 10,05 + подмены 1,83 = 11,88 (у него 11,82); 01.09 —
        10,69 + 0,83 = 11,52 (у него 11,43). Прежний расчёт давал ровно 12 ч и
        ложный флаг «+0,75 ч сверх нормы».
        """
        long_ones = [s for s in stops
                     if not s.elsewhere
                     and s.hours >= self.operator_norm - 0.5]
        if not long_ones:
            return stops
        others = [s for s in stops if id(s) not in {id(x) for x in long_ones}]
        reasons = []
        for s in long_ones:
            txt = (s.reason or "").strip()
            if txt and txt not in reasons:
                reasons.append(txt)
        all_parallel = not any(s.machine_stopped for s in long_ones)
        if all_parallel and self.work_hours > 0.01 and not self.balance_unknown:
            # Машина шла — значит, сменная операция длилась столько же. Операции
            # при ОСТАНОВЛЕННОЙ машине шли в другое время и прибавляются;
            # параллельные — внутри того же окна, поэтому вычитаются.
            inside = sum(s.hours for s in others if not s.machine_stopped)
            rest = round(self.work_hours - inside, 2)
        else:
            # Машина стояла всю смену, а человек был на ней: его время — это
            # присутствие минус обед. Обед ОБЯЗАТЕЛЬНО вырезаем и здесь:
            # сменная строка создаётся без start_min/end_min, поэтому
            # _cut_lunch_from_operator её не видит и 45 мин оставались внутри.
            # Прогон 15.09.2026, ст.321: обёртка «машина на подмене» 07:00–16:20
            # (9,33 ч) покрывала все детальные записи, rest = 9,33 − 7,23 = 2,10 ч
            # и оператор получил 9,33 ч вместо 8,58 (присутствие 9,33 − обед
            # 0,75). В эталоне пользователя 8,25 ч.
            rest = round(max(s.hours for s in long_ones)
                         - sum(s.hours for s in others)
                         - self._lunch_inside_long(long_ones), 2)
        if rest <= 0.01:
            # Перечисленные операции уже покрывают всю смену — сменная строка
            # не добавляет времени, иначе часы задвоятся.
            return others
        merged = TechStop(rest, " / ".join(reasons),
                          performer=self.operator,
                          is_parallel=any(not s.machine_stopped
                                          for s in long_ones),
                          shiftlong_parallel=any(s.shiftlong_parallel
                                                 for s in long_ones),
                          label_override=" / ".join(reasons) or None)
        return [merged] + others

    # ——— операции, названные без времени (правило пользователя 03.09.2026) ———
    @property
    def untimed_own_groups(self) -> List[tuple]:
        """[(текст, сколько раз)] по операциям оператора без времени.

        Одинаковые по смыслу складываем (5×«чинка кромки» → одна запись
        «(5 раз)»), показываем самую короткую формулировку мастера.
        """
        return _group_untimed(self.untimed_own)

    @property
    def untimed_own_summary(self) -> str:
        """«подстановка бобин, чинка кромки (4 раза), упаковка гильз»."""
        return _summarize_untimed(self.untimed_own)

    @property
    def untimed_all_summary(self) -> str:
        """То же, но по ВСЕМ записям без времени (для простоя станка)."""
        return _summarize_untimed(self.untimed_stops)

    @property
    def control_label(self) -> str:
        """Ярлык часов контроля с перечислением операций без времени.

        Пользователь просит писать работу оператора точнее, а не «работа за
        машиной»: если мастер назвал операции, но не назвал время, названия
        уходят в ту же строку пояснением (стиль его эталона 01.09: «работа по
        контролю за работой машины (в т.ч. …)»).
        """
        detail = self.untimed_own_summary
        if not detail:
            return CONTROL_LABEL
        return f"{CONTROL_LABEL} (в т.ч. {detail} — время не указано)"

    @property
    def unexplained_label(self) -> str:
        """Ярлык необъяснённого простоя станка.

        Если причины в переписке названы, но без времени, честнее написать их,
        а не «причина не указана»: не указано именно ВРЕМЯ.
        """
        detail = self.untimed_all_summary
        if not detail:
            return UNEXPLAINED_LABEL
        return f"время не указано у причин: {detail}"

    def _operator_work_rows(self) -> List[tuple]:
        """[(описание, часы)] операций оператора ДО ограничения сменой."""
        # group key = label; value = [hours, count, longest_reason]
        groups: dict = {}
        order: List[str] = []

        # Ярлык «прочее» — это НЕ одна операция, а «причину не распознали».
        # Склеивать по нему разные дела нельзя: у пользователя в эталоне они
        # стоят отдельными строками (16.09 ст.321: «0,33 перестановка
        # телег/сбор отходов» и «0,25 заполнение журнала, чата»), а бот
        # печатал одну строку «прочее (2 раз) 0,33». Поэтому для нераспознанных
        # причин ключ группировки — сам текст записи мастера.
        def _key(label: str, reason: str) -> str:
            if label in (OTHER_LABEL, NO_REASON_LABEL):
                return label + "|" + " ".join(str(reason or "").split()).lower()
            return label
        if self.no_operator_all_shift:
            # Станок весь день у инженерной службы (или в очереди на наладку, и
            # фамилии оператора нет) — своего оператора нет, блок работы
            # оператора пустой (эталон 27.08 ст.111/121, 02.09 ст.111/121).
            return []

        def add(label: str, hours: float, reason: str = "") -> None:
            if hours <= 0.01:
                return
            key = _key(label, reason)
            if key not in groups:
                order.append(key)
                groups[key] = [0.0, 0, "", label]
            g = groups[key]
            g[0] += hours
            g[1] += 1
            if len(reason) > len(g[2]):
                g[2] = reason

        if self.operator_control_printed > 0.01:
            add(self.control_label, self.operator_control_printed)
        for s in self.own_operator_stops():
            add(s.label, s.hours, s.reason or "")
        rows = [(_describe(label, cnt, reason), round(h, 2))
                for key in order
                for h, cnt, reason, label in [groups[key]]]
        rows.sort(key=lambda x: -x[1])
        return rows

    def operator_work_by_reason(self) -> List[tuple]:
        """Операции оператора за смену: [(описание, часы)], одинаковое сложено.

        Для блока «Работа оператора всего» в Excel. Объединяет одинаковые
        операции (правило читаемости: 5×чинка по 1 ч → «чинка (5 раз) 5 ч»).
        Строки в сумме дают ровно operator_hours: явные операции
        (own_operator_stops) плюс контроль за работой машины.
        """
        if self.no_operator_all_shift:
            # Станок весь день у инженерной службы (или в очереди на наладку, и
            # фамилии оператора нет) — своего оператора нет, блок работы
            # оператора пустой (эталон 27.08 ст.111/121, 02.09 ст.111/121).
            return []
        return self._cap_rows_to_shift(self._operator_work_rows())[0]

    def _cap_rows_to_shift(self, rows: List[tuple]) -> tuple:
        """(строки после среза, (описание срезанной строки, снятые часы) или None).

        Блок «Работа оператора» печатается теми же часами, что и его итог, а
        итог ограничен сменой 07:00–19:00 (правило 25.09.2026). Если названные
        операции влезают в 12 ч только с наложением, строки не могут в сумме
        давать больше: лишний объём снимается с самой длинной строки. Срез
        обязан быть назван в отчёте (operator_rows_clip) — молча убирать 2 ч
        у человека из его строки нельзя.
        """
        over = round(sum(h for _d, h in rows) - MACHINE_SHIFT_HOURS, 2)
        if over <= 0.01:
            return rows, None
        i = max(range(len(rows)), key=lambda k: rows[k][1])
        desc, hours = rows[i]
        cut = list(rows)
        cut[i] = (desc, round(hours - over, 2))
        cut = [x for x in cut if x[1] > 0.01]
        cut.sort(key=lambda x: -x[1])
        return cut, (desc, over)

    @property
    def operator_rows_clip(self) -> tuple:
        """(описание, часы) строки, которой не хватило места в 12-часовой смене.

        Пустой tuple ('', 0.0), если резки не было. Часы названных операций,
        снятые при печати блока «Работа оператора» — их обязан увидеть мастер,
        потому что пересеклись окна в переписке и код не решает, какая запись
        лишняя.
        """
        return self._cap_rows_to_shift(self._operator_work_rows())[1] or ("", 0.0)

    def attracted_by_person(self) -> List[tuple]:
        """[(описание, часы)] привлечённого персонала, одинаковое объединяем.

        Строка с нулём часов («время не уточнено») нужна, только если у человека
        за смену нет ни одной работы с временем: иначе рядом с «Пронкин — 6 ч»
        встала бы вторая строка «Пронкин — 0 ч».
        """
        stops = self.attracted_all()
        with_hours = {(s.performer or "?").strip().lower()
                      for s in stops if s.hours > 0.01}
        groups: dict = {}
        order: List[tuple] = []
        for s in stops:
            who = (s.performer or "?").strip()
            if s.hours <= 0.01 and who.lower() in with_hours:
                continue
            key = (who, s.label)
            if key not in groups:
                order.append(key)
                groups[key] = [0.0, 0, ""]
            g = groups[key]
            g[0] += s.hours
            g[1] += 1
            if len(s.reason or "") > len(g[2]):
                g[2] = s.reason or ""
        rows = []
        for who, lab in order:
            h, cnt, reason = groups[(who, lab)]
            rows.append((f"{who} — {_describe(lab, cnt, reason)}", round(h, 2)))
        rows.sort(key=lambda x: -x[1])
        return rows

    def parallel_by_reason(self) -> List[tuple]:
        """Параллельные операции по причинам: [(ярлык, часы)]."""
        groups: dict = {}
        for s in self.parallel_stops:
            groups[s.label] = groups.get(s.label, 0.0) + s.hours
        rows = [(label, round(h, 2)) for label, h in groups.items()]
        rows.sort(key=lambda x: -x[1])
        return rows

    def _absence_label(self) -> str:
        """Самый информативный ярлык для строки отсутствия оператора.

        Приоритет: ушёл на конкретный станок → пришёл поздно → сдал смену
        рано → просто «отсутствие оператора».

        Если человек ушёл работать на другой станок, в ярлык добавляется, что
        его часы посчитаны ТАМ. Это обещание держится только над уходом на
        станок, где человек — свой оператор (absence_credited_machines): его
        время там и стоит в блоке оператора. Во всех остальных случаях уход
        считается его РАБОТОЙ по этому станку (правило пользователя «помощь
        этого оператора на других станках тоже идёт во время работы
        оператора»), и писать «посчитаны там» — значило бы послать читателя в
        отчёт, где этих часов нет (25.09.2026, ст.321: Петровский на 0,27 ч
        уходил «смотреть ошибку» на 251, где оператор Гудкова; его часы стояли
        в блоке 321, а на 251 их никто не ждал). Часы работника не задваиваются
        между станками (иначе за смену выходит больше, чем он отработал).
        """
        for s in self.regular_stops:
            if s.is_absence and s.other_machine:
                there = machine_rates._norm_key(s.other_machine) in \
                    self.absence_credited_machines
                return ("отсутствие оператора (работа на №"
                        + str(s.other_machine)
                        + (", часы посчитаны там)" if there else ")"))
        if self.operator_start_span > 0.01 and self.operator_start:
            return "отсутствие оператора (пришёл в " + self.operator_start + ")"
        if self.data_gap_before_shift > 0.01 and self.first_info_time:
            # Про приход человека мы ничего не знаем — знаем только, с какого
            # времени по станку есть данные. Так и пишем, без «пришёл в» и без
            # длительности: в эту строку-заглушку может попасть и другое
            # необъяснённое время смены (сколько именно приходится на пустое
            # начало — сказано в предупреждении).
            return ("отсутствие оператора (данные по станку с "
                    + str(self.first_info_time) + ")")
        tail = (MACHINE_SHIFT_HOURS - self._operator_end_span
                - self.handover_coverage_hours)
        if tail > 0.01 and self.operator_shift_end:
            return ("отсутствие оператора (смена до "
                    + self.operator_shift_end + ")")
        return "отсутствие оператора"

    def _absence_stub_rows(self) -> List[tuple]:
        """Разделить заглушку до 12 ч на подтверждённую и необъяснённую части.

        `operator_absence_hours` — остаток смены, и когда у станка есть уход на
        другой станок, `_absence_label()` на весь остаток вешает «работа на
        №251». Прогон 25.09.2026, ст.321: Петровский документировал уход
        17:51–18:06 (0,25 ч, ещё 0,02 ч на 111), а подписью «работа на №251»
        оказывались накрыты 0,95 ч. Часы человека в другом месте — только те,
        которые он там реально записал; остальное время смены причиной не
        обросло и обязано лежать под «причина не указана».
        """
        total = self.operator_absence_hours
        if total <= 0.01:
            return []
        there: dict = {}
        for s in self.regular_stops:
            if s.is_absence and s.other_machine:
                key = machine_rates._norm_key(s.other_machine)
                there[key] = there.get(key, 0.0) + s.hours
        if not there:
            return [(self._absence_label(), total)]
        rows: List[tuple] = []
        left = round(total, 2)
        for key, hours in sorted(there.items(), key=lambda kv: -kv[1]):
            take = round(min(hours, left), 2)
            if take <= 0.01:
                continue
            credited = key in self.absence_credited_machines
            rows.append(("отсутствие оператора (работа на №" + str(key)
                         + (", часы посчитаны там)" if credited else ")"),
                         take))
            left = round(left - take, 2)
        if left > 0.01:
            rows.append((UNEXPLAINED_LABEL, left))
        return rows

    def downtime_by_reason(self) -> List[tuple]:
        """Простой, сгруппированный по причинам: [(ярлык, часы, оператор_работал)].

        В простой станка входят: остановки из сообщений, подмены, обед
        (45 мин — станок стоит) и остаток смены, если смена оператора
        короче смены станка.
        """
        groups: dict = dict(self._nonabsence_grouped())
        if self.lunch_in_downtime:
            hours, _a = groups.get(LUNCH_LABEL, (0.0, False))
            groups[LUNCH_LABEL] = (hours + self.lunch_in_downtime, False)
        # ВАЖНО: параллельные операции оператора (навивка/подготовка/контроль)
        # в простой станка НЕ идут. Они перекрываются либо временем работы
        # станка, либо уже названными остановками (наладка/чинка/замена
        # шпулярника), поэтому отдельной строкой «операции оператора при
        # стоящем станке» станок бы «переработал» сверх 12 ч (эталон 27.08
        # ст.151: +3,15 ч). В эталоне пользователя такой строки простоя нет —
        # навивка учитывается только в часах ОПЕРАТОРА (operator_explicit_hours),
        # а простой станка объясняют реальные остановки. Что осталось
        # необъяснённым — честно уходит в «причина не указана».
        if self.zero_output_downtime_hours:
            # Счётчик не сдвинулся: станок стоял всю смену, причина названа
            # словами мастера, но без времени (прогон 10.09.2026, ст.321).
            groups[self.zero_output_label] = (
                groups.get(self.zero_output_label, (0.0, True))[0]
                + self.zero_output_downtime_hours, True)
        if self.named_residual_hours:
            # Остаток смены с НАЗВАННОЙ причиной (см. named_residual_hours).
            label = self.named_residual_label
            hours, active = groups.get(label, (0.0, True))
            groups[label] = (hours + self.named_residual_hours, active)
        # Отсутствие оператора — остаток до 12 ч (см. operator_absence_hours).
        # Всего остаток подписать «работа на №X» нельзя: подтверждены только
        # реально записанные уходы, остальное — время без причины.
        for label, stub_hours in self._absence_stub_rows():
            hours, _a = groups.get(label, (0.0, False))
            groups[label] = (hours + stub_hours, False)
        if self.engineering_all_shift:
            # Машина весь день отдана инженерной службе. По эталону
            # пользователя (лист 27.08, ст.111 и 121) это ОДНА строка простоя
            # «наладка / инженерная служба» на все 12 ч, а не набор мелких
            # причин: своего оператора на станке нет, работавшие люди идут в
            # привлекаемый персонал. Раньше причина сваливалась в «прочее»
            # (маркера «инженерн» нет ни в одной категории), и станок ещё и
            # ошибочно набирал 12 операторских часов.
            return [(ENGINEERING_LABEL, MACHINE_SHIFT_HOURS, False)]
        if self.naladka_all_shift_no_operator:
            # Тот же случай, только вместо инженерной службы — очередь на
            # наладку, и фамилии оператора нет. Правило пользователя
            # (03.09.2026): «там просто пишется 12 часов наладка» — без строки
            # обеда, потому что обедать на станке некому.
            return [(NALADKA_LABEL, MACHINE_SHIFT_HOURS, False)]
        # Обед снимаем только на избыток сверх 12 ч (см. _lunch_trim): иначе
        # строки простоя в сумме дают 12,75 ч при смене 12 ч (прогон
        # 10.09.2026, ст.321 — интервалы операций закрыли всю смену).
        lunch = groups.get(LUNCH_LABEL, (0.0, False))[0]
        other = sum(h for label, (h, _a) in groups.items() if label != LUNCH_LABEL)
        trim = self._lunch_trim(lunch, other)
        if trim > 0.01:
            h, active = groups[LUNCH_LABEL]
            groups[LUNCH_LABEL] = (max(0.0, h - trim), active)
        rows = [(label, round(h, 2), active) for label, (h, active) in groups.items()]
        rows = [row for row in rows if row[1] > 0.001]
        rows.sort(key=lambda x: -x[1])
        return rows

    @property
    def named_residual_hours(self) -> float:
        """Остаток до 12 ч, причину которого мастер НАЗВАЛ, но не назвал время.

        Применяется ОДНОМУ случаю: мастер записал одну работу на полсмены
        («7:00-15:39 подставляла шпулярник. 205 шт.» — прогон 16.09.2026,
        ст.251, 8,65 ч), а станок по счётчику отработал 5,73 ч. Вместе они
        больше 12 ч, поэтому окно оставлено параллельным (_parallelize_
        shiftlong_swaps) — но машина в него ЧАСТО стояла, и остаток смены
        честнее отнести к той же причине, чем в «причина не указана». В
        эталоне пользователя: «2,85 простой замена шпул» (12 − 5,73 работа −
        0,9 наладка − 2,52 подмена).

        Причины, названные БЕЗ времени, сюда не берутся намеренно: у них есть
        свой механизм — остаток остаётся необъяснённым, но подписан словами
        мастера (unexplained_label; эталон 02.09 ст.321 «время не указано у
        причин: Чинка кромки …, наладка машины»). Перенос такого остатка в
        простой ломал два теста и менял отчёт 02.09.
        """
        if self.balance_unknown or self.no_operator_all_shift:
            return 0.0
        if self.zero_output_all_shift:
            return 0.0          # там свой механизм zero_output_downtime_hours
        covered = (self.work_hours + self.tech_stops_total
                   + self.lunch_in_downtime + self.operator_absence_hours)
        rest = round(MACHINE_SHIFT_HOURS - covered, 2)
        if rest <= TOLERANCE_H:
            return 0.0
        if self.shiftlong_swap_label:
            return rest
        # МАЛЫЙ остаток (не больше часа) при причине, названной мастером БЕЗ
        # времени: отнести его к этой причине честнее, чем оставить станок
        # «недоработавшим». Прогон 16.09.2026, ст.151: мастер написал «Стоп.
        # Обрыв нити верхней основы … Устранил. В работе» и ни одной метки
        # времени, станок по счётчику отработал 11,61 ч из 12 → остаток 0,39 ч
        # и ложный флаг «станок −0,39 ч до 12 ч». В эталоне пользователя эти
        # часы стоят строками «0,18 простой обрыв» + «0,1 отсутствие оператора»
        # (сумма 11,89 — у него тоже недобор, значит данные действительно
        # неполные, и флаг пугал зря).
        #
        # Ограничение жёсткое: только ОДИН ярлык причины и остаток ≤ 1 ч.
        # Большой остаток остаётся необъяснённым с перечислением причин
        # (эталон 02.09 ст.321: 10,95 ч и «время не указано у причин: …»).
        if rest <= 1.0:
            labels = {classify_stop(t)[0] for t in self.untimed_stops if t}
            labels.discard("")
            if len(labels) == 1:
                return rest
        return 0.0

    @property
    def shiftlong_swap_label(self) -> str:
        """Ярлык длинного окна подстановки/подмены, оставленного параллельным."""
        for s in self.tech_stops:
            if s.shiftlong_parallel:
                return s.machine_label or s.stop_label
        return ""

    @property
    def named_residual_label(self) -> str:
        """Причина остатка (см. named_residual_hours).

        Ярлык длинного окна, а если остаток мал и причина названа без времени —
        её ярлык («обрыв нити»). Иначе «причина не указана».
        """
        if self.shiftlong_swap_label:
            return self.shiftlong_swap_label
        labels = {classify_stop(t)[0] for t in self.untimed_stops if t}
        labels.discard("")
        if len(labels) == 1:
            return labels.pop()
        return UNEXPLAINED_LABEL

    @property
    def machine_downtime(self) -> float:
        """Сколько станок не работал от нормы 12 ч."""
        return round(max(0.0, MACHINE_SHIFT_HOURS - self.work_hours), 2)

    @property
    def accounted_downtime(self) -> float:
        """Простой с причиной: остановки + обед + остаток смены + параллельное.

        Свои подмены сюда НЕ входят — они идут во время работы станка
        (own_subs_hours), а не в простой.

        Плюс та часть параллельных операций, которая не влезла во время
        работы станка: если станок работал 0 ч, а навивка шла 5 ч, значит
        станок в это время стоял, и часы обязаны объяснять простой.

        Машина в инженерной службе — весь день ремонт, 12 ч. Так же считается
        станок, который всю смену стоял в очереди на наладку без оператора:
        строка простоя там одна на все 12 ч (правило 03.09.2026).
        """
        if self.no_operator_all_shift:
            return MACHINE_SHIFT_HOURS
        # Обед — за вычетом избытка сверх 12 ч, чтобы итог совпадал с суммой
        # строк downtime_by_reason (правило Р22: строки складываются в итог).
        other = (self.tech_stops_total + self.operator_absence_hours
                 + self.zero_output_downtime_hours
                 + self.named_residual_hours)
        return round(other + self.lunch_in_balance, 2)

    @property
    def lunch_in_balance(self) -> float:
        """Обед ровно в том объёме, в каком он вошёл в баланс станка.

        Отличается от lunch_in_downtime, когда строки простоя уже переполнили
        смену и обед урезан до нуля (22.09.2026, ст.151: четыре причины на
        14,78 ч). Пояснению это различие и нужно: говорить про «обед отдельной
        строкой» там, где строки обеда в отчёте нет, — обман.
        """
        lunch = self.lunch_in_downtime
        other = (self.tech_stops_total + self.operator_absence_hours
                 + self.zero_output_downtime_hours
                 + self.named_residual_hours)
        return round(lunch - self._lunch_trim(lunch, other), 2)

    @property
    def machine_balance(self) -> float:
        """Работа станка + свои подмены + объяснённый простой. В норме = 12 ч.

        Своя подмена (заправка полотна) — часть времени работы станка, поэтому
        стоит на «рабочей» стороне баланса, а не в простое.
        """
        if self.engineering_all_shift:
            return round(self.work_hours + self.accounted_downtime, 2)
        return round(self.work_hours + self.own_subs_hours
                     + self.accounted_downtime, 2)

    @property
    def unexplained_downtime(self) -> float:
        """Работа станка + объяснённый простой не добирают 12 ч — разница.

        Если время работы станка неизвестно (нет нормы или показаний
        счётчика), необъяснённый простой посчитать нельзя: иначе вся смена
        уходит в «причина не указана» и получается ложный недостаток.
        """
        if self.balance_unknown:
            return 0.0
        return round(max(0.0, MACHINE_SHIFT_HOURS - self.machine_balance), 2)

    @property
    def rate_missing(self) -> bool:
        """Станка нет в справочнике норм — время работы посчитать нельзя."""
        return self.rate is None

    @property
    def counters_missing(self) -> bool:
        """Ни по одной строке нет пары показаний счётчика."""
        return not any(ln.counter_start is not None and ln.counter_end is not None
                       for ln in self.lines)

    @property
    def zero_output_all_shift(self) -> bool:
        """Счётчик за смену НЕ СДВИНУЛСЯ: станок не произвёл ни одного узла.

        Показания есть и начало равно концу (прогон 10.09.2026, ст.321:
        «Общ.сч. -118526» в 06:55 и «Общ.сч. -118526» в конце смены). Это НЕ
        «нет данных» и НЕ ошибка: станок честно простоял всю смену, а причина
        обычно названа словами («Машина … поставлена на подмену», «Навиваю
        шпули на подмену»). Отличаем от no_counters_at_all: там показаний нет
        вовсе, и причина неизвестна.
        """
        if self.balance_unknown:
            return False
        for ln in self.lines:
            if (ln.counter_start is not None and ln.counter_end is not None
                    and abs(ln.counter_end - ln.counter_start) > 1e-9):
                return False
        return bool(self.lines)

    @property
    def zero_output_downtime_hours(self) -> float:
        """Сколько часов простоя объясняет «станок стоял всю смену».

        Станок не работал вообще (zero_output_all_shift), а причины в
        переписке НАЗВАНЫ, но без времени. Эти часы — реальный простой, а не
        «данные испорчены»: добиваем ими баланс до 12 ч и называем причину
        словами мастера. Ничего не выдумываем: время работы станка доказано
        счётчиком (0 узлов), остаётся только подписать, ПОЧЕМУ он стоял.

        Если названных причин нет — возвращаем 0: остаток честно уйдёт в
        «причина не указана».
        """
        if not self.zero_output_all_shift or self.no_operator_all_shift:
            return 0.0
        # Добиваем остаток ТОЛЬКО если мастер назвал причину словами (пусть и
        # без времени). Если записей нет вовсе — дыра честно остаётся «причина
        # не указана», не выдумываем «отсутствие оператора» (тест
        # test_zero_output_without_reasons_stays_unexplained).
        if not (self.untimed_stops or self.untimed_own):
            return 0.0
        covered = round(self.tech_stops_total + self.lunch_in_downtime
                        + self.operator_absence_hours, 2)
        rest = round(MACHINE_SHIFT_HOURS - self.work_hours - covered, 2)
        return rest if rest > 0.01 else 0.0

    @property
    def zero_output_label(self) -> str:
        """Подпись простоя «стоял всю смену»: причины словами мастера."""
        detail = self.untimed_all_summary
        text = "станок не работал всю смену (счётчик не сдвинулся)"
        return f"{text}: {detail}" if detail else text

    @property
    def no_counters_at_all(self) -> bool:
        """За смену НЕТ вообще ни одного показания счётчика (ни нач., ни кон.).

        Правило участка (26.08.2026): такая машина за смену ничего не выдала —
        значит весь день была в наладке или в инженерной службе.
        """
        for ln in self.lines:
            if ln.counter_start is not None or ln.counter_end is not None:
                return False
        return True

    def _discussion_text(self) -> str:
        """Весь текст обсуждения по станку в нижнем регистре (для поиска ФИО).

        Собираем всё, где могли назвать человека: оператор, причины остановок,
        исполнители подмен/наладки, записи без времени, ФИО на подменах.
        """
        parts = [self.operator or "", self.subs_fio or ""]
        parts += [s.reason or "" for s in self.tech_stops]
        parts += [s.performer or "" for s in self.tech_stops]
        parts += [s.reason or "" for s in self.attracted]
        parts += [s.performer or "" for s in self.attracted]
        parts += list(self.untimed_stops)
        return " ".join(parts).lower()

    @property
    def balance_unknown(self) -> str:
        """Причина, по которой баланс времени считать нельзя ('' — можно).

        Без нормы или без счётчика работа станка выходит 0 ч, и любой
        «недостаток времени» будет ложным — такие смены помечаем как
        «нет данных», а не как нарушение.

        Исключение — машина без оператора: в инженерной службе или всю смену в
        очереди на наладку. Там счётчик и не нужен, весь день закрыт одной
        строкой простоя на 12 ч.
        """
        if self.no_operator_all_shift:
            return ""
        if self.rate_missing:
            return f"нет нормы выработки для станка {self.machine or '—'}"
        if self.counters_missing:
            return "нет показаний счётчика (нужны начальное и конечное)"
        return ""

    @property
    def machine_shortfall(self) -> float:
        """Недостаток времени по станку (с допуском TOLERANCE_H)."""
        if self.balance_unknown:
            return 0.0
        gap = MACHINE_SHIFT_HOURS - self.machine_balance
        return round(gap, 2) if gap > TOLERANCE_H else 0.0

    @property
    def machine_excess(self) -> float:
        """Сумма превысила 12 ч (с допуском) — значит, часы задвоены.

        Обед (45 мин) — фиксированная величина по правилу участка, а время
        работы приходит из счётчика и может слегка на него наложиться. Такое
        наложение не «задвоение часов», поэтому обед в проверке на превышение
        не учитываем: иначе на ст.98 за 27.08 (работа 10,05 + подмена 1,83 +
        обед 0,75 = 12,63) появлялся бы ложный флаг «+0,63 ч сверх 12».

        Наложение простоев с разными причинами здесь уже не вычитается: такие
        минуты сняты со строк простоя до расчёта (см. _deduped_nonabsence), и
        превышение остаётся только там, где его действительно нечем объяснить.

        Обед вычитается в ТОМ объёме, в каком он вошёл в баланс
        (lunch_in_balance), а не фиксированные 45 мин: когда строки простоя уже
        переполнили смену, строки обеда в отчёте нет (22.09.2026, ст.151:
        четыре причины на 15,24 ч, обед срезан до 0), и прощать по 0,75 ч за
        несуществующий обед не за что.
        """
        if self.balance_unknown:
            return 0.0
        gap = (self.machine_balance - self.lunch_in_balance
               - MACHINE_SHIFT_HOURS)
        return round(gap, 2) if gap > TOLERANCE_H else 0.0

    @property
    def engineering_all_shift(self) -> bool:
        """Станок весь день в инженерной службе (ремонт), а не в работе.

        Правило участка: если про машину написано, что она в инженерной
        службе, и по счётчику она не работала, то весь день (12 ч) — это
        ремонт в инженерной службе. Оператора на ней нет, значит и обеда
        в её простое нет.
        """
        if self.work_hours > 0.01:
            return False
        # Причины смотрим и в перенесённом привлекаемом персонале: на стоявшем
        # весь день станке событие «работы инженерной службы …» приходит с kind
        # «работа» и исполнителем, поэтому в tech_stops не попадает (25.09.2026,
        # ст.121: без этого станок печатал «отсутствие оператора 11,25 ч»
        # вместо «наладка / инженерная служба 12 ч»).
        texts = ([s.reason or "" for s in self.tech_stops]
                 + [s.reason or "" for s in self.attracted]
                 + list(self.untimed_stops))
        if any(m in (t or "").lower()
               for t in texts for m in _ENGINEERING_MARKERS):
            return True
        # Нет вообще показаний счётчика и в обсуждении фигурирует Каленюк —
        # значит станок весь день в инженерной службе (ремонт).
        if self.no_counters_at_all and any(
                p in self._discussion_text() for p in _ENGINEERING_PEOPLE):
            return True
        return False

    @property
    def naladka_all_shift(self) -> bool:
        """Станок весь день в наладке.

        Правило участка (26.08.2026): если про машину написали «в стопе,
        нужна наладка» и дальше в обсуждении НЕТ сообщения «машина в работе»
        (и по счётчику она не работала), значит она весь день в наладке —
        11,25 ч наладка + 45 мин обед = 12 ч.

        В отличие от инженерной службы, оператор при машине стоит, но его
        личных часов из этого не следует: наладка — время службы наладки
        (правило Г от 03.09.2026), а смену оператора добивать до 11,25 ч
        приказом владельца от 28.09.2026 запрещено. Поэтому наладка закрывает
        день СТАНКА, а человек получает только названные им работы.
        """
        if self.engineering_all_shift:
            return False
        if self.work_hours > 0.01:
            return False
        texts = [s.reason or "" for s in self.tech_stops] + list(
            self.untimed_stops)
        low = " ".join(texts).lower()
        # Нет вообще показаний счётчика и в обсуждении фигурирует
        # Пронкин/Шалыминов — станок весь день в наладке.
        if self.no_counters_at_all and any(
                p in self._discussion_text() for p in _NALADKA_PEOPLE):
            return True
        if "налад" not in low:
            return False
        # Если где-то сказано, что машину потом пустили — это не весь день.
        # «пустил» ищем отдельно: простое подстрокой ловило и «ВЫпустил нитки»
        # (работа оператора, станок в наладке), из-за чего день, закрытый
        # наладкой, перставал им считаться.
        if any(w in low for w in ("в работе", "работает", "запустил",
                                  "запущен")) or _RESUMED_RE.search(low):
            return False
        # НАЛАДКА ОБЯЗАНА ЗАНИМАТЬ СМЕНУ, а не упоминаться в ней. Слово
        # «наладка» в тексте + нулевой счётчик — ещё не «станок весь день в
        # наладке»: мастер мог вызвать наладчика на две минуты, а всё остальное
        # время станок стоял на подмене или в навивке.
        #
        # Прогон 16.09.2026, ст.321: наладка 0,10 ч (1% простоев), остальные
        # 9,68 ч — подмена шпуль и навивка, а код решил «весь день в наладке» и
        # добавил филлер «наладка (весь день)» 2,22 ч, которого в эталоне
        # пользователя нет вовсе (у него 3,78 отсутствие + 3,58 навивка +
        # 4,57 подмена). То же на ст.321 за 15.09: наладка 0,77 ч (4%) при
        # 19,23 ч прочих простоев.
        #
        # Признак «весь день» — наладка составляет БОЛЬШУЮ часть простоев
        # (≥50%), либо других простоев почти нет. Эталонные дни, где станок
        # действительно весь день в наладке (26.08 ст.321/121, 02.09
        # ст.111/121), дают долю 100% и правилом сохраняются.
        # Свой же филлер «наладка (весь день)» в расчёт не берём: свойство
        # пересчитывается на каждое обращение, и добавленная ниже строка
        # иначе засчиталась бы как «прочий простой» и отменила признак
        # (тест test_naladka_all_shift_untimed_tops_up_to_12).
        def _is_filler(s) -> bool:
            return "весь день" in (s.reason or "").lower()

        naladka_h = sum(s.hours for s in self.tech_stops
                        if not s.elsewhere and not _is_filler(s)
                        and (s.is_naladka or NALADKA_LABEL == s.label))
        other_h = sum(s.hours for s in self.tech_stops
                      if not s.elsewhere and not _is_filler(s)
                      and not s.is_naladka and NALADKA_LABEL != s.label)
        # Записи БЕЗ времени: если мастер написал «в очереди на наладку»,
        # это наладка, иначе — прочий простой.
        for text in self.untimed_stops:
            low = (text or "").lower()
            if "налад" in low:
                continue
            other_h += 1.0
        if other_h > 1.0 and naladka_h < 0.5 * other_h:
            return False
        return True

    @property
    def naladka_all_shift_no_operator(self) -> bool:
        """Станок весь день в наладке, и своего оператора на нём не было.

        Правило пользователя (03.09.2026, дословно): «если машина весь день в
        наладке или инженерной службе, у неё не надо писать в простое обед
        оператора — там просто пишется 12 часов наладка».

        Обед — это обед ОПЕРАТОРА, поэтому он появляется только когда человек
        на станке был. Эталон пользователя это подтверждает с двух сторон:
        02.09 ст.111/121 и 22.08 (машина без фамилии) — строки обеда нет,
        а 01.09 ст.121, где оператор назван (Вашурина), — «11,25 наладка +
        0,75 обед». Значит признак ровно один: названа ли фамилия оператора.
        """
        return self.naladka_all_shift and not (self.operator or "").strip()

    @property
    def no_operator_all_shift(self) -> bool:
        """Своего оператора на станке не было всю смену (наладка/инженерная)."""
        return self.engineering_all_shift or self.naladka_all_shift_no_operator

    @property
    def operator_absent_all_shift(self) -> bool:
        """Оператор назван, но у станка его не было почти всю смену.

        Прогул или перевод на другой участок (ст.321 за 21.09.2026: Демидов,
        «отсутствие 07:00–19:00»). От `no_operator_all_shift` отличается тем, что
        фамилия в переписке есть — и поэтому такой оператор может молча попасть
        в колонку «фио на подменах», где ему не место: подменять на станке, у
        которого он не стоял, человек не мог.
        """
        if not (self.operator or "").strip():
            return False
        need = MACHINE_SHIFT_HOURS - TOLERANCE_H
        return any(s.is_absence and s.hours >= need for s in self.tech_stops)

    @property
    def no_shift_data(self) -> bool:
        """По станку за смену нет вообще никаких данных.

        В эталоне пользователя такой станок подписан «нет данных / станок не
        работал» (02.09: ст.601, 14тр, 15тр), а не «отсутствие оператора»:
        человека к нему в этот день просто не ставили.
        """
        if (self.operator or "").strip():
            return False
        return not (self.lines or self.tech_stops or self.attracted
                    or self.untimed_stops or self.subs_hours)

    @property
    def naladka_note(self) -> str:
        """Формулировка из переписки про станок, весь день стоящий в наладке."""
        texts = [s.reason or "" for s in self.tech_stops] + list(
            self.untimed_stops)
        best = ""
        for t in texts:
            low = t.lower()
            if "налад" in low and "весь день" not in low and len(t) > len(best):
                best = t.strip()
        return best

    @property
    def operator_block_note(self) -> str:
        """Подпись к блоку «Работа оператора всего» ('' — обычная смена)."""
        if self.engineering_all_shift:
            return "машина в инженерной службе"
        if self.naladka_all_shift_no_operator:
            return (self.naladka_note
                    or "весь рабочий день станок не работал, в наладке")
        if self.no_shift_data:
            return "нет данных / станок не работал"
        if not (self.has_operator and self.operator_hours > 0.01):
            return "отсутствие оператора"
        return ""

    @property
    def has_operator(self) -> bool:
        """Был ли на станке оператор (или наладчик) — от этого зависит обед.

        Фамилия оператора — достаточное доказательство. Без фамилии человека
        доказывают только его ОПЕРАЦИИ (tech_stops/subs) или показания
        счётчика: станок крутился — значит кто-то его вёл.

        Строка ассортимента сама по себе доказательством НЕ является. Прогон
        16.09.2026, ст.111: по машине была единственная запись «Отходы НПА
        187х2 после развивки шпулей 6,2 кг» (08:44), модель завела из неё
        строку с ассортиментом «НПА 187х2» и без счётчиков — has_operator стал
        True, норма 9,52 ч, и бот начислил несуществующему оператору 9,52 ч
        «работы по контролю за работой машины» плюс 0,75 ч обеда. В эталоне
        пользователя: «Работа оператора всего — отсутствие оператора», машина
        0 из 12 ч, строки обеда нет.

        Так же читаются и остальные два признака, иначе они врут:
        • ОДИНАРНОЕ показание счётчика (только начальное или только конечное) —
          это цифра из переписки, а не движение машины. Прогон 24.09.2026,
          ст.601: мастер прислал «Общий счетчик 3083» без второго значения, и
          бот начислил 11,25 ч контроля станции, которая всю смену простояла в
          инженерной службе;
        • запись простоя доказывает человека только когда в это время ОН сам
          что-то делал. Прогон 24.09.2026, ст.15тр («машина в стопе до
          15.10.2026 г.», фамилии нет) и ст.251 («отсутствие оператора»):
          стоящий станок и отсутствующий человек — не работа оператора, а бот
          клал их в `tech_stops` и выдавал 11,25 ч + обед. В эталоне
          пользователя за те же даты у 14тр/15тр/601 стоит «нет данных / станок
          не работал» и 0 часов оператора.
        """
        if self.no_operator_all_shift:
            return False
        if (self.operator or "").strip():
            return True
        if self.subs_hours:
            return True
        if any(s.by_operator for s in self.tech_stops):
            return True
        return any((ln.output or 0) > 0 for ln in self.lines)

    @property
    def lunch_hours(self) -> float:
        """Обед — всегда 45 минут, если на станке был человек."""
        return LUNCH_FULL_H if self.has_operator else 0.0

    @property
    def lunch_in_downtime(self) -> float:
        """Обед в простое станка — всегда полные 45 мин, если человек был.

        По правилу участка обед — фиксированные 45 мин, и в эталоне
        пользователя строка «простой обед 0,75» стоит всегда (лист 27.08:
        ст.98 работа 10 + подмена 1,82 + обед 0,75 — сумма чуть больше 12, и
        это норма). Раньше обед урезался до «свободного места» в 12 ч, из-за
        чего на ст.98 в отчёте бота стояло 0,12 ч вместо 0,75 ч. Наложение
        счётчика на обед не считается задвоением — см. machine_excess.

        ИСКЛЮЧЕНИЕ — плавающий обед (16.09.2026): если на время перерыва станок
        принял другой человек и машина продолжала работать, простоя нет и
        строка «обед» не печатается. Эталон пользователя за 16.09: ст.321,
        ст.151 и ст.251 без строки обеда, ст.98 (обед никто не принимал) — с
        ней. См. lunch_machine_covered.
        """
        if not self.has_operator:
            return 0.0
        if self.lunch_machine_covered:
            return 0.0
        return LUNCH_FULL_H

    @property
    def lunch_machine_covered(self) -> bool:
        """Во время обеда станок вёл ДРУГОЙ человек — простоя не было.

        Два признака (достаточно одного):
          • мастер прямо написал, что машину приняли / не останавливали
            (lunch_handed_over, см. _LUNCH_HANDOVER_RE);
          • окно обеда перекрыто операцией, у которой исполнитель — НЕ
            оператор этого станка (коллега действительно был у машины).
        """
        if self.lunch_handed_over:
            return True
        a, b = self.lunch_window_min
        op = (self.operator or "").strip()
        for s in list(self.tech_stops) + list(self.attracted):
            if s.start_min is None or s.end_min is None:
                continue
            if s.machine_stopped:
                # Станок в это время СТОЯЛ (наладка, чинка) — значит простой
                # был, и обед остаётся отдельной строкой. Эталон 01.09,
                # ст.121: наладка Пронкина 07:00–19:00 + обед 0,75 = 12 ч;
                # без этой проверки наладчик засчитывался как «принявший
                # станок», строка обеда исчезала и баланс съезжал на 11,24.
                continue
            if min(s.end_min, b) - max(s.start_min, a) <= 0:
                continue
            perf = (s.performer or "").strip()
            if perf and not _same_person_name(perf, op):
                return True
        return False

    @property
    def lunch_trimmed(self) -> bool:
        """Обед пришлось урезать — работа + простои и так почти закрыли 12 ч."""
        return self.has_operator and self.lunch_in_downtime < LUNCH_FULL_H - 0.01

    @property
    def machine_work_norm(self) -> float:
        """Максимум, сколько станок может работать: 12 ч − обед.

        С оператором это 11,25 ч, без него (например, ремонт в инженерной
        службе) — все 12 ч.
        """
        return round(MACHINE_SHIFT_HOURS - self.lunch_hours, 2)

    @property
    def work_over_norm(self) -> float:
        """Насколько работа по счётчику больше предела 12 ч − обед.

        Станок стоит на обеде 45 мин, значит работать он может максимум
        11,25 ч. Больше — повод проверить показания счётчика или норму T.

        Пока баланс времени не считается вовсе (нет нормы или счётчика),
        проверять нечего: иначе под строчкой «⛔ баланс не считаю» печатался бы
        совет «проверьте показания счётчика», которого в отчёте быть не может.
        """
        if self.balance_unknown:
            return 0.0
        gap = self.work_hours - self.machine_work_norm
        return round(gap, 2) if gap > TOLERANCE_H else 0.0

    @property
    def absence_after_shift(self) -> float:
        """Часы смены станка, на которые у оператора смена уже кончилась.

        Станок работает 12 ч (07:00–19:00). Если у оператора смена короче
        (например 8-часовая), остаток — отсутствие оператора на станке.

        ПЕРЕДАЧА СМЕНЫ (handover): если после ухода оператора его подхватил
        другой человек (привлечённый персонал), станок не простаивал —
        второго оператора вёл кто-то ещё. Поэтому «отсутствие» уменьшаем на
        часы привлечённого персонала, которые перекрыли этот хвост. Пример
        (эталон 25.08, ст.321): Арташина сдала смену в 08:20, дальше станок
        вёл Сотволдиев — хвоста-простоя «нет оператора» тут быть не должно.
        """
        gap = MACHINE_SHIFT_HOURS - self._operator_end_span
        if gap <= 0.01:
            return 0.0
        # Привлечённый персонал, покрывший смену после ухода оператора.
        covered = self.handover_coverage_hours
        gap = gap - covered
        return round(gap, 2) if gap > 0.01 else 0.0

    @property
    def absence_before_shift(self) -> float:
        """Часы до прихода оператора на станок — отсутствие оператора (простой).

        Если оператор пришёл на станок позже 07:00 (был занят на другом
        станке), время до прихода станок стоял без своего оператора. Это
        простой «отсутствие оператора», а не недостаток его времени. Пример
        26.08, ст.321: Камбаров пришёл в 17:02 → 10 ч отсутствия, а не
        «недостаток 10 ч».
        """
        gap = self.operator_start_span
        return round(gap, 2) if gap > 0.01 else 0.0

    @property
    def has_absence_signal(self) -> bool:
        """Есть ли признак, что оператора не было у станка часть смены.

        Либо мастер прямо написал про отсутствие/уход (is_absence-простой),
        либо оператор пришёл позже 07:00 (operator_start), либо его смена
        кончилась раньше 19:00 и хвост не перекрыт передачей смены.
        """
        if any(s.is_absence for s in self.regular_stops):
            return True
        if self.operator_start_span > 0.01:
            return True
        tail = (MACHINE_SHIFT_HOURS - self._operator_end_span
                - self.handover_coverage_hours)
        return tail > 0.01

    @property
    def operator_absence_hours(self) -> float:
        """Отсутствие оператора у станка — ОДНОЙ строкой, как остаток до 12 ч.

        По методике пользователя (эталон 26.08, ст.321) «отсутствие оператора»
        — это заглушка, добивающая баланс станка до 12 ч: 12 − работа −
        реальные простои − обед − параллельное − то, что перекрыл сменщик.
        Так отсутствие всегда одно и станок не может «переработать» сверх 12 ч.
        Считается только при наличии признака отсутствия (has_absence_signal);
        без него остаток идёт в необъяснённый простой, а не в «отсутствие».
        """
        if self.engineering_all_shift:
            return 0.0
        if not self.has_operator:
            # Человека на станке не было ВОВСЕ (фамилия не названа, своих
            # операций нет, счётчик за смену не сдвинулся), но какие-то данные
            # по машине за смену есть — значит весь день станок простоял без
            # оператора. Эталон
            # 16.09.2026, ст.111: «Работа оператора всего — отсутствие
            # оператора», в листе-таблице «11,25 | отсутв опер», строки обеда
            # нет (обедать некому). Норма 11,25, а не 12: 45 мин обеда в
            # отсутствие человека не проставляем.
            if self.no_shift_data:
                return 0.0
            # Заглушка ДОБИРАЕТ баланс до 12 ч, а не добавляется к нему. Если
            # станок уже объяснён реальным простоем на всю смену («машина в
            # стопе до 15.10.2026 г.», прогон 24.09.2026 ст.15тр; «наладка»
            # 22.09 ст.15тр), второй строки «отсутствие оператора» быть не
            # может — иначе 12 ч смены превращаются в 23,25 ч простоя.
            residual = (MACHINE_SHIFT_HOURS - self.work_hours
                        - self.tech_stops_total - self.lunch_in_downtime)
            return round(max(0.0, min(OPERATOR_SHIFT_HOURS, residual)), 2)
        if not self.has_absence_signal:
            return 0.0
        residual = (MACHINE_SHIFT_HOURS - self.work_hours
                    - self.tech_stops_total - self.lunch_in_downtime
                    - self.handover_coverage_hours)
        return round(residual, 2) if residual > 0.01 else 0.0

    @property
    def handover_coverage_hours(self) -> float:
        """Часы привлечённого персонала, покрывающие хвост после ухода оператора.

        Считается только когда смена оператора закончилась раньше 19:00
        (operator_shift_end задан). Тогда работа другого человека на этом
        станке трактуется как передача смены, а не как параллельная подмена.
        Ограничена длиной хвоста, чтобы не уводить «отсутствие» в минус.
        """
        gap = MACHINE_SHIFT_HOURS - self._operator_end_span
        if gap <= 0.01:
            return 0.0
        # Учитываем только те окна привлечённых, которые ДЕЙСТВИТЕЛЬНО
        # попадают в хвост после ухода оператора. Раньше бралась сумма всех их
        # часов, и хвост «покрывался» людьми, которые давно ушли.
        # Прогон 16.09.2026, ст.321: последняя запись Демидова — «16:00-16:15
        # заполнение журнала и чата», хвост 16:15–19:00 (2,75 ч), а Гузеев
        # работал 13:20–15:30 и Петровский 11:00–11:45 — оба ДО хвоста. Их
        # 2,92 ч «покрыли» хвост, отсутствие оператора обнулилось, баланс
        # станка съехал на 9,13 ч, и 2,87 ч ушли в «причина не указана».
        # В эталоне пользователя: «3,78 простой отсутствие оператора».
        tail_start = SHIFT_START_H * 60.0 + self._operator_end_span * 60.0
        day_end = SHIFT_START_H * 60.0 + MACHINE_SHIFT_HOURS * 60.0
        cover = 0.0
        for s in self.attracted_all():
            if s.start_min is None or s.end_min is None:
                cover += s.hours        # время неизвестно — считаем как раньше
                continue
            overlap = min(s.end_min, day_end) - max(s.start_min, tail_start)
            if overlap > 0:
                cover += overlap / 60.0
        return round(min(gap, cover), 2)

    @property
    def has_handover(self) -> bool:
        """Была ли передача смены другому человеку в середине смены."""
        return bool((self.operator2 or "").strip()
                    and (self.operator2_start or "").strip())

    @staticmethod
    def _hhmm_to_span(value: Optional[str]) -> Optional[float]:
        """«08:20» → 1.33 (часов от начала смены 07:00). None, если не разобрать."""
        s = (value or "").replace(".", ":").strip()
        if not s:
            return None
        try:
            hh, mm = s.split(":")[:2]
            span = int(hh) + int(mm) / 60.0 - SHIFT_START_H
            if 0 < span <= MACHINE_SHIFT_HOURS:
                return round(span, 2)
        except ValueError:
            pass
        return None

    @property
    def operator2_hours(self) -> float:
        """Часы принявшего смену (привлекаемый персонал), presence-based.

        По методике пользователя (эталон 25.08, ст.321: Сотволдиев 9,92 ч):
        принявший ведёт станок от передачи до конца смены (19:00) минус обед,
        если обед попадает в его окно. Это его личное присутствие за станком —
        от времени работы станка по счётчику НЕ зависит (он и чинит, и ведёт).
        """
        if not self.has_handover:
            return 0.0
        start = self._hhmm_to_span(self.operator2_start)
        if start is None:
            return 0.0
        span = MACHINE_SHIFT_HOURS - start          # от передачи до 19:00
        lunch = LUNCH_FULL_H if start <= LUNCH_START_SPAN else 0.0
        return round(max(0.0, span - lunch), 2)

    @property
    def operator_lunch(self) -> float:
        """Обед, вычитаемый из НОРМЫ первого оператора этого станка.

        Обед за смену один — 45 мин, и вычитать его дважды у одного человека
        нельзя. Поэтому обед НЕ вычитается здесь, если его окно (около 12:00)
        не попало в присутствие оператора на этом станке:
        - он сдал станок и ушёл ДО обеда (эталон 25.08: Арташина на 321 =
          1,33 ч без вычета) — обедал уже на новом станке;
        - он пришёл на станок ПОСЛЕ обеда (31.08: Вашурина на 121 с 16:30) —
          обед у него вычтен на том станке, где он был до обеда.
        """
        if not self.has_operator:
            return 0.0
        end = self._hhmm_to_span(self.operator_shift_end)
        if end is not None and end <= LUNCH_START_SPAN:
            return 0.0
        if self.operator_start_span > LUNCH_START_SPAN:
            return 0.0
        return LUNCH_FULL_H

    @property
    def model_shift_end_unconfirmed(self) -> bool:
        """Конец смены 19:00 в записях мастера НЕ подтверждён.

        Модель ставит operator_shift_end = «19:00» по умолчанию, даже когда в
        разделе про конец смены нет ни слова. Доверять такому значению больше,
        чем последней записи мастера, нельзя.

        Подтверждением считаем ЛЮБОЕ из:
          • в тексте остановок/причин есть «конец смены» или «19:00»;
          • есть операция, которая реально дошла до 19:00 (end_min == 1140).

        Прогон 16.09.2026: ни один из четырёх станков «конец смены» не назвал,
        но у №251 есть запись «18:45-19:00 заполнение чата и журнала» (интервал
        до 19:00 → подтверждено), а у №321 последняя запись — «16:00-16:15
        заполнение журнала и чата», и ни текста про конец смены, ни интервала до
        19:00 нет → НЕ подтверждено, человек ушёл в 16:15.
        """
        end = (self.operator_shift_end or "").replace(".", ":").strip()
        if end not in ("19:00", ""):
            return False        # названо другое время — ему и верим
        texts = ([s.reason or "" for s in self.tech_stops]
                 + list(self.untimed_stops) + list(self.untimed_own))
        if _SHIFT_END_RE.search(" ".join(texts)):
            return False
        if any(s.end_min == int(SHIFT_START_H * 60) + int(MACHINE_SHIFT_HOURS * 60)
               for s in self.tech_stops):
            return False
        return True

    @property
    def _operator_end_span(self) -> float:
        """Час конца присутствия оператора от 07:00.

        Приоритет: явный конец смены, подтверждённый текстом → завершающая
        запись мастера («заполнение журнала и чата») → полная смена до 19:00.

        Порядок важен: model_shift_end_unchecked проверяется ПЕРЕД разбором
        operator_shift_end, иначе значение «19:00», которое модель проставила
        по умолчанию, всегда возвращало 12,0 и хвост после ухода человека не
        попадал в «отсутствие оператора».
        """
        end = (self.operator_shift_end or "").replace(".", ":")
        # Явного конца смены в разделе нет (или он равен 19:00, который модель
        # проставила по умолчанию). Если мастер ЗАКРЫЛ смену записью
        # «заполнение журнала и чата» РАНЬШЕ 19:00 — человек ушёл тогда, а
        # остаток до 19:00 станок стоял без оператора.
        # Прогон 16.09.2026, ст.321: Демидов закончил в 16:15, хвост 2,75 ч —
        # «отсутствие оператора» (в эталоне пользователя 3,78 ч).
        # Осторожно: учитываем только когда «19:00» в тексте раздела НЕ
        # подтверждено (model_shift_end_unconfirmed), иначе ломаются дни, где
        # мастер честно написал «19:00 конец смены» и потом отдельно заполнял
        # журнал уже после окончания смены.
        if self.model_shift_end_unconfirmed and self.closing_activity_end:
            span = self.closing_activity_end / 60.0 - SHIFT_START_H
            if 0 < span < MACHINE_SHIFT_HOURS:
                return round(span, 2)
        if end:
            try:
                hh, mm = end.split(":")[:2]
                span = int(hh) + int(mm) / 60.0 - SHIFT_START_H
                if 0 < span <= MACHINE_SHIFT_HOURS:
                    return round(span, 2)
            except ValueError:
                pass
        return MACHINE_SHIFT_HOURS

    @property
    def data_gap_before_shift(self) -> float:
        """Пустое начало смены: по станку ещё нет ни одного сообщения.

        Правило пользователя (03.09.2026): «смена начинается с 7 утра у всех,
        и если сообщения по этому станку начинаются намного позже, например с
        8 утра, то этот час идёт тоже в простой машины и пишется по нему
        отсутствие оператора».

        Применяется только когда:
          * мастер НЕ назвал время прихода оператора — operator_start сильнее,
            это прямые слова о человеке, а не вывод из времени сообщений;
          * разрыв больше допуска 20 мин — «намного позже», а не «в 07:05»;
          * в балансе станка для этого разрыва есть место. Если счётчик и
            названные простои уже закрыли 12 ч, значит станок в этот час
            работал, а поздняя переписка — только особенность записи. Тогда
            часы не выдумываем: разрыв 0, а в отчёт идёт предупреждение.
        """
        if self.operator_start:
            return 0.0
        gap = self._hhmm_to_span(self.first_info_time)
        if gap is None or gap <= TOLERANCE_H:
            return 0.0
        room = (MACHINE_SHIFT_HOURS - self.work_hours
                - self.tech_stops_total - self.lunch_in_downtime)
        if room <= TOLERANCE_H:
            return 0.0
        return round(min(gap, room), 2)

    @property
    def operator_start_span(self) -> float:
        """Час прихода оператора на станок от 07:00. 0, если пришёл к началу.

        Если времени прихода нет, но по станку до какого-то часа вообще нет
        данных, начало смены считается от появления данных (см.
        data_gap_before_shift): смена у всех с 07:00, и пустой час — это время
        без оператора у станка.
        """
        start = self._hhmm_to_span(self.operator_start)
        if start is not None:
            return start
        return self.data_gap_before_shift

    @property
    def operator_shift_span(self) -> float:
        """Длина ПРИСУТСТВИЯ оператора на станке: от прихода до конца смены.

        Обычно 07:00→19:00 (12 ч). Если оператор пришёл позже (был на другом
        станке) — считаем только от прихода; время до прихода уходит в простой
        «отсутствие оператора», а не в его недостаток времени.
        """
        span = self._operator_end_span - self.operator_start_span
        return round(max(0.0, span), 2)

    @property
    def operator_norm(self) -> float:
        """Сколько сотрудник ДОЛЖЕН отработать именно на этом станке.

        Смена оператора минус обед. Часы, которые он отработал на другом
        станке, из нормы НЕ вычитаются: по правилу участка это отсутствие
        оператора на данном станке, и оно должно быть видно как недостаток
        времени здесь, а как отработанное время — на том станке.
        Для полной смены до 19:00 это привычные 11,25 ч. Если на станке
        человека не было (машина в инженерной службе), нормы нет — иначе
        получится ложный недостаток 12 ч.
        """
        if not self.has_operator:
            return 0.0
        if self.operator_norm_hours and self.operator_norm_hours > 0.01:
            # Норма названа словами в переписке — она точнее вывода из времени
            # прихода/ухода (эталон 14.09, ст.321: стажёр 8 ч, а не 11,25).
            return round(float(self.operator_norm_hours), 2)
        norm = self.operator_shift_span - self.operator_lunch
        return round(max(0.0, norm), 2)

    @property
    def lunch_deducted(self) -> float:
        """Сколько обеда вычитается из часов сотрудника — нисколько.

        Обед теперь входит в простой станка (станок стоит 45 мин), поэтому
        его нет ни в работе станка, ни в операциях оператора, и вычитать
        второй раз нельзя.
        """
        return 0.0

    @property
    def parallel_extra(self) -> float:
        """Параллельные часы, которые НЕ перекрыты работой станка.

        Навивка шпулей при работающем станке уже внутри времени работы
        станка — второй раз её считать нельзя. Но если станок работал
        меньше, чем длилась навивка (например, работа 0,5 ч, а навивка
        1,4 ч), остаток — это реально отработанное время оператора, и
        терять его нельзя.
        """
        return round(max(0.0, self.parallel_hours - self.work_hours), 2)

    @property
    def elsewhere_extra_hours(self) -> float:
        """Часы оператора на других станках, перенесённые сюда (см. поле)."""
        return round(sum(s.hours for s in self.elsewhere_extra), 2)

    @property
    def full_absence_hours(self) -> float:
        """Часы, когда оператор был на другом СВОЁМ станке (чистое отсутствие).

        Это не его работа на этом станке и не «контроль»: часы учтены на том
        станке, где он в это время был штатным оператором.

        ВАЖНО: если те же часы всё-таки попали в его операции по ЭТОМУ станку
        (строка «работа на машине №X» / «оператор переведён на №X»), второй раз
        их вычитать нельзя — иначе у человека появляется ложный недостаток
        (прогон 27.08 (7).xlsx: ст.251 — оператор 8,58 вместо 11,25, 2,67 ч на
        №111 были и в строках, и в вычете).
        """
        counted = {round(s.hours, 2) for s in self.own_operator_stops()}
        return round(sum(s.hours for s in self.tech_stops
                         if s.elsewhere and s.full_absence
                         and round(s.hours, 2) not in counted), 2)

    @property
    def operator_explicit_hours(self) -> float:
        """Явно названные операции ОПЕРАТОРА (кроме «контроля за машиной»).

        Правило пользователя (27.08.2026, дословно): «время работы оператора на
        подменах идёт во время его часов работы, или помощь этого оператора на
        других станках тоже идёт во время работы оператора; так же если у
        оператора написано "машина стоп, продолжаю навивать шпули" — это время
        тоже идёт во время его работы».

        Поэтому сюда входит ВСЁ, что он делал сам: операции при остановленном
        станке (чинка, наладка, своя подмена, навивка при стопе), параллельные
        операции при работающем станке, работа на других станках — и та, что
        записана в переписке по ЕГО станку (elsewhere), и та, что записана по
        чужому станку (elsewhere_extra, перенос в build). Не включает только
        «контроль за работой машины» — это время работающего станка
        (operator_control_hours). Операции ПРИВЛЕЧЁННОГО персонала
        (performer ≠ оператор) сюда не идут — это чужие часы.
        """
        return round(sum(s.hours for s in self.own_operator_stops()), 2)

    @property
    def parallel_own_hours(self) -> float:
        """Свои операции при РАБОТАЮЩЕМ станке — они уже внутри работы машины.

        Нужны, чтобы не задваивать время: навивка шпуль при работающей машине
        стоит отдельной строкой в блоке оператора, поэтому из «контроля за
        работой машины» это время вычитается.
        """
        return round(sum(s.hours for s in self.own_operator_stops()
                         if not s.machine_stopped), 2)

    @property
    def away_own_hours(self) -> float:
        """Часы его блока, отработанные на ЧУЖОМ станке (строка правила Р23).

        Строка «работа на машине №151» стоит в блоке оператора отдельно, значит
        в «контроль за работой своей машины» те же минуты второй раз идти не
        могут: человек физически был у другой машины. До правила Е (бобины и
        шпулярник) это получалось случайно — «замена шпулярника, 58 бабин»
        считалась параллельной операцией и вычиталась через parallel_own_hours.
        Как только такая работа стала простоем, из вычета она выпала, и у
        Камбарова (27.08, ст.251) появилось 11,49 ч вместо проверенных вами
        11,25 — те же 2,5 ч посчитались дважды.

        Берём только строки, которых НЕТ в parallel_own_hours (там условие
        `not machine_stopped`), чтобы не вычесть одно и то же время дважды.
        Уход на другой станок из СВОИХ остановок (`elsewhere`) сюда не входит
        специально: он так себя вёл и до правила Е, а трогать это — отдельное
        решение (см. ниже про 19.08).
        """
        return round(sum(s.hours for s in self.own_operator_stops()
                         if s.machine_stopped and not s.elsewhere
                         and (s.label or "").startswith(
                             ELSEWHERE_WORK_LABEL)), 2)

    def away_own_by_machine(self) -> List[tuple]:
        """[(номер станка, часы)] по строкам правила Р23 — для читаемости итога.

        Слагаемое «работа на других станках» иначе не проверить глазами: в
        тексте отчёта видно только уход по своим сообщениям (↗️), а часы,
        записанные в переписке ЧУЖОГО станка, в блоке этого станка не
        показывались. Ст.251 за 27.08: 5,17 ч = 2,67 ч ухода на 111 + 2,5 ч
        замены шпулярника на 151.
        """
        res: dict = {}
        order: List[str] = []
        for s in self.own_operator_stops():
            label = s.label or ""
            if (not s.machine_stopped or s.elsewhere
                    or not label.startswith(ELSEWHERE_WORK_LABEL)):
                continue
            num = label[len(ELSEWHERE_WORK_LABEL):].strip() or "?"
            if num not in res:
                order.append(num)
                res[num] = 0.0
            res[num] += s.hours
        return [(n, round(res[n], 2)) for n in order]

    @property
    def operator_led_raw_hours(self) -> float:
        """Время работающего станка «на операторе» — ДО потолка присутствия.

        Правило пользователя (03.09.2026, дословно): «если оператор работал
        больше, то такое может быть — не нужно уменьшать ему время работы, как
        например с 98 машиной: у неё минимум работа по машине 10.2, а отчёт
        ставит 9.75, чтобы было 11.25 ровно, но так не надо делать».

        То есть время работы машины по счётчику — это НИЖНЯЯ граница часов
        оператора, а не то, что надо сжать до нормы. Из него вычитается только
        то, что уже посчитано отдельно (параллельные операции, часы на другом
        станке — away_own_hours) или отработано не им (полное отсутствие,
        передача смены другому человеку).
        """
        led = (self.work_hours - self.parallel_own_hours - self.away_own_hours
               - self.full_absence_hours - self.handover_coverage_hours)
        return round(max(0.0, led), 2)

    @property
    def operator_machine_led_hours(self) -> float:
        """Часы станка, которые оператор реально «вёл»: минимум и потолок.

        НИЖНЯЯ граница — время работающего станка (operator_led_raw_hours),
        нормой (operator_norm = присутствие минус обед) оно больше НЕ обрезается:
        приказ владельца от 28.09.2026 — «смены не могут быть больше 11,25… если
        не хватает или переизбыток, то оставляй как есть». Обрез по норме прятал
        переизбыток (станок работал дольше нормы человека, а отчёт молча ставил
        11,25), и вычитал обед второй раз: обед уже учтён в простое станка (см.
        lunch_deducted), в работе машины его нет.

        ВЕРХНЯЯ граница — физическое присутствие человека у станка
        (operator_shift_span = от прихода до конца смены). Это не «добивка»,
        запрещённая приказом, а запрет на выдуманное время: при смене до 15:00
        (8 ч) счётчик может давать 10,19 ч работы машины, но «вести» этот станок
        человек мог только 8 ч — остальные часы у станка он отсутствовал, и
        дарить их его строке нельзя (тест 03.09.2026: «часы станка не дарим
        оператору»). Снятое потолком присутствия называется словами через
        operator_span_clip и повторяется в Excel.

        Предел смены 07:00–19:00 (12 ч) остался в operator_hours; срезанные им
        часы видно через operator_ceiling_clip.
        """
        return round(min(self.operator_led_raw_hours,
                         max(0.0, self.operator_shift_span)), 2)

    @property
    def operator_span_clip(self) -> float:
        """Сколько часов «контроля» снял потолок присутствия человека (0, если не снял).

        Часов, которых человек у станка физически не был, в его строке стоять не
        может — это выдуманное время, а не «переизбыток, который оставляем как
        есть». Снятие видно словами и в отчёте, и в Excel; молча оно не теряется.
        """
        return round(max(0.0, self.operator_led_raw_hours
                         - self.operator_shift_span), 2)

    @property
    def operator_control_hours(self) -> float:
        """«Работа по контролю за работой машины» — ТОЛЬКО время работы станка.

        Правило пользователя (27.08.2026): «если машина работает — это время
        идёт во время работы оператора». Правило (03.09.2026, ст.98, и
        подтверждено приказом 28.09.2026): «не нужно их добивать до 11,25, если
        не хватает или переизбыток — оставляй как есть». Значит этой строкой мы
        часы до нормы НЕ закрываем: прибавляется ровно то, что станок реально
        проработал по счётчику и что не посчитано отдельно.

        До 28.09.2026 сюда шёл остаток до нормы, и у оператора почти всегда
        выходило ровно 11,25 — реального недостатка времени отчёт не показывал
        (прогон 26.09.2026, ст.98: названо 8,64 ч операций, станок работал 9,4 ч,
        а в отчёте стояло 11,25 из 11,25).

        Часы, которые человек провёл на ДРУГОМ станке как его штатный оператор
        (full_absence), вычтены в operator_machine_led_hours: в это время он
        физически не вёл этот станок, и его часы посчитаны там (26.08: Камбаров
        с 321 весь день на 251 → контроля на 321 нет).
        """
        if not self.has_operator:
            return 0.0
        # zero_output_all_shift (станок по счётчику не сделал ни одного узла)
        # попадает в base сам: работа машины 0 ч, вести было нечего. И добор к
        # ней не применяется: «контроль за работой машины», которой весь день
        # стояла, — выдуманное время. Прогон 15.09.2026, ст.111: Дремкова весь
        # день подменяла шпули, а бот добивал ей 7,05 ч «контроля» и выдавал
        # 11,25 из 11,25 при эталоне пользователя 3,92 ч.
        base = round(max(0.0, self.operator_machine_led_hours), 2)
        if self.zero_output_all_shift or self.balance_unknown:
            # `balance_unknown` — тот же случай в другой форме: показаний
            # счётчика нет вовсе (151 за 29.09: одно утреннее число 790782 без
            # вечернего), поэтому и «работы машины», которую он контролировал,
            # нет ни в чём. До переноса по №135 сюда не доходило — у стоявшего
            # станка часов оператора и так не было; как только его оператор
            # получил свои строки из чужих тем, добор начал рисовать 0,69 ч
            # «контроля» машине, время работы которой неизвестно.
            return base
        # ДОБОР ОСТАТКА (приказ владельца от 30.09.2026, №140). До него этой
        # строкой закрывался весь остаток до нормы, с 28.09.2026 она прибавляла
        # только время работы станка — и у человека появлялся крас флаг
        # «недостаток», которого в его ручном отчёте нет (прогон 29.09: ст.111
        # 10,69 против его 11,25, ст.321 10,13 против 11,25). Теперь остаток
        # добирается, но только когда разрыв небольшой — до 1,5 ч; больше —
        # считается, что минут реально не было, и добирать их нельзя.
        # Потолок добора — присутствие человека у станка (operator_shift_span):
        # часы, когда его на станке не было, строкой «контроль» не закрываются
        # никогда. Часы на другом СВОЁМ станке (full_absence) из нормы вычтены:
        # они посчитаны там, а не потеряны.
        target = round(self.operator_norm - self.full_absence_hours, 2)
        gap = round(target - (self.operator_explicit_hours + base), 2)
        if TOLERANCE_H < gap <= OPERATOR_PAD_MAX_H:
            room = round(max(0.0, self.operator_shift_span - base), 2)
            base = round(base + min(gap, room), 2)
        return base

    @property
    def operator_control_printed(self) -> float:
        """Сколько «контроля за машиной» печатать строкой: строки = итог.

        operator_hours может быть обрезан потолком смены (см. ниже), а слагаемые
        блока «Работа оператора» обязаны сложиться в ИТОГ, а не в сумму до
        обрезки, иначе лист показывает 13,05 ч при итоге 12,00 ч.
        Срезается именно филлер: это единственное слагаемое, которого в
        переписке нет — часы мастера при резке не теряются.
        """
        spare = round(self.operator_hours - self.operator_explicit_hours, 2)
        return round(max(0.0, min(self.operator_control_hours, spare)), 2)

    @property
    def _operator_hours_by_formula(self) -> float:
        """Часы оператора по формуле, но БЕЗ потолка смены в 12 ч.

        Отдельно от operator_hours только ради одного: чтобы срезанные потолком
        часы было чем показать в отчёте (operator_ceiling_clip), а не молча
        потерять.

        Нормой (11,25 ч) итог НЕ обрезается и НЕ добивается — приказ владельца
        от 28.09.2026: «не нужно их добивать до 11,25, если не хватает или
        переизбыток то оставляй как есть». Обрез по норме стоял здесь, когда
        станок отрабатывал всю смену (прогон 16.09.2026, ст.151: строки дали
        11,61 ч при норме 11,25), и прятал переизбыток. Недостаток прятал
        филлер в operator_control_hours. Оба убраны; физический предел смены
        07:00–19:00 (12 ч) остался — он из правила владельца от 25.09.2026.
        """
        total = self.operator_explicit_hours + self.operator_control_hours
        return round(max(0.0, total), 2)

    @property
    def operator_hours(self) -> float:
        """Время работы сотрудника за смену.

        Сумма его операций: явные операции (operator_explicit_hours) плюс
        время, когда он вёл работающий станок (operator_control_hours). Раньше
        сюда прибавлялось ПОЛНОЕ время работы станка, из-за чего у операторов с
        параллельными операциями получалось ложное «превышение» (напр. 151 за
        24.08 давал +7,9 ч). Теперь итог не задваивается, но и не подгоняется
        под норму: сколько сложилось — столько и есть, недостаток и переизбыток
        видны отдельными строками (приказ владельца от 28.09.2026).
        """
        if self.no_operator_all_shift:
            # Станок весь день у инженерной службы или в очереди на наладку без
            # фамилии оператора — своего оператора на нём нет (эталон 27.08 и
            # 02.09, ст.111/121: «Работа оператора всего — 0»). Часы людей,
            # которые там что-то делали, идут в привлекаемый персонал, а не в
            # часы оператора станка.
            return 0.0
        total = self._operator_hours_by_formula
        # ПОТОЛОК СМЕНЫ. Правило пользователя от 25.09.2026 (дословно): «больше
        # 12 часов не может быть работы оператора, так как их смена максимум
        # 12 часов с 7 до 19:00». Человек физически не может отработать больше
        # своей смены, поэтому выше предела итог не поднимается НИКОГДА — даже
        # когда правило 03.09 («не уменьшать время оператора») тянет его вверх
        # (прогон 21.09.2026, ст.251: 8,5 ч названных операций + 4,55 ч
        # «контроля за машиной» = 13,05 ч, т. е. на 1,05 ч больше смены).
        #
        # Срезается в первую очередь то, чего в переписке нет: филлер «контроль
        # за работой машины» (operator_control_printed берёт уже ограниченный
        # итог, и слагаемые по-прежнему складываются в него — правило Р22).
        # Если же и ОДНИ названные мастером операции больше 12 ч, итог всё
        # равно не проходит: такие окна пересеклись, и это отдельный сигнал
        # (operator_rows_over_shift), а не повод печатать несуществующую смену.
        if total > MACHINE_SHIFT_HOURS:
            total = MACHINE_SHIFT_HOURS
        return round(max(0.0, total), 2)

    @property
    def operator_rows_over_shift(self) -> float:
        """Часы названных операций, которым не хватило места в 12-часовой смене.

        Появляется там, где мастер описал пересекающиеся окна (12,28 ч работы
        при смене 07:00–19:00). Код не вправе решать, какая из записей лишняя,
        поэтому в итог идёт потолок смены, а остаток называется в отчёте —
        человеку видно, какие минуты надо разобрать вручную.
        """
        return round(max(0.0, round(self.operator_explicit_hours, 2)
                         - MACHINE_SHIFT_HOURS), 2)

    @property
    def operator_ceiling_clip(self) -> float:
        """Сколько часов оператора отрезал потолок смены (0, если не резал).

        Без этой цифры обрезка была бы молчаливой: в отчёте стояло бы 12,00 ч,
        и никто не увидел бы, что мастер описал 13,05 ч. Снимаем с «контроля за
        работой машины» — единственного слагаемого, которого в переписке нет.
        """
        if self.no_operator_all_shift:
            return 0.0
        return round(max(0.0, self._operator_hours_by_formula
                         - self.operator_hours), 2)

    def operator_hours_parts(self) -> List[tuple]:
        """Слагаемые часов оператора: [(название, часы)] — сумма = operator_hours.

        Нужны для строки итога. Раньше она печаталась по другой формуле («работа
        при станке + операции при остановке»), и слагаемые не складывались в свой
        же итог: на ст.151 за 27.08 выходило «5,72 + 10,65 = 11,25». Причина —
        работа станка это ВРЕМЯ МАШИНЫ, а часы человека собираются из его
        операций плюс контроль за работой машины (правило Р22: строки обязаны
        складываться в итог, ровно как в блоке operator_work_by_reason).

        Разбиение идёт по тем же строкам own_operator_stops(), поэтому наложение
        по времени уже снято (правило «пересеклись — берём максимум»), а часы на
        других станках стоят отдельным слагаемым и не задваиваются.
        """
        if self.no_operator_all_shift or not self.has_operator:
            return []
        rows = self.own_operator_stops()
        # Слагаемые не должны пересекаться между собой, иначе итог снова
        # разъедется. Уход на другой станок (elsewhere) всегда machine_stopped,
        # поэтому из «операций при остановке» он исключён, а строки правила Р23
        # берутся ровно тем же условием, что в away_own_hours.
        away = round(sum(s.hours for s in rows if s.elsewhere)
                     + self.away_own_hours, 2)
        total = self.operator_hours
        parts = [("операции при остановке станка", self.operator_stop_hours),
                 ("операции при работающем станке", self.parallel_own_hours),
                 ("работа на других станках", away),
                 ("контроль за работой машины",
                  self.operator_control_printed)]
        # Итог мог быть обрезан потолком смены (12 ч) — тогда слагаемые обязаны
        # сложиться в ОБРЕЗАНЫЙ итог, а не в «сколько вышло до обрезки». Снимаем
        # с филлера «контроль за работой машины»: это единственное слагаемое,
        # которое мастер не называл (прогон 16.09.2026, ст.151: строки 11,72 ч
        # при итоге 11,25 ч).
        summed = round(sum(h for _n, h in parts), 2)
        if summed - total > 0.01:
            # Снимаем с филлера, а если его не хватает — с самой длинной
            # строки: слагаемые обязаны сложиться в итог (Р22), а итог не может
            # быть больше смены (25.09.2026). Сколько часов не влезло и откуда,
            # печатает отчёт: operator_ceiling_clip (с разбором «филлер или
            # названные операции») и operator_rows_clip (какая строка укоротилась).
            over = round(summed - total, 2)
            from_control = min(over, self.operator_control_hours)
            if from_control > 0.01:
                parts = [(n, h - from_control
                          if n == "контроль за работой машины" else h)
                         for n, h in parts]
            left = round(sum(h for _n, h in parts), 2) - total
            if left > 0.01:
                i = max(range(len(parts)), key=lambda k: parts[k][1])
                parts[i] = (parts[i][0], round(parts[i][1] - left, 2))
        return [(name, round(h, 2)) for name, h in parts if h > 0.01]

    @property
    def operator_deviation(self) -> float:
        """Отклонение от нормы: <0 — недостаток, >0 — переработка."""
        return round(self.operator_hours - self.operator_norm, 2)

    @property
    def operator_shortfall(self) -> float:
        """Недостаток времени сотрудника (с допуском TOLERANCE_H).

        Часы, которые человек провёл на ДРУГОМ своём станке (full_absence), из
        нормы вычитаются: они не потеряны, они посчитаны в блоке того станка.
        Иначе на станке, откуда он ушёл, появляется ложный недостаток ровно на
        размер отсутствия (прогон (9) 27.08: ст.321 «оператор −6 ч», где эти 6 ч
        стоят у того же человека на ст.251).
        """
        if self.balance_unknown or not self.has_operator:
            return 0.0
        gap = (self.operator_norm - self.full_absence_hours
               - self.operator_hours)
        return round(gap, 2) if gap > TOLERANCE_H else 0.0

    @property
    def operator_excess(self) -> float:
        """Переработка сверх нормы — повод проверить данные.

        Допуск ровно такой же, как у недостатка: 20 минут (правило пользователя
        28.08 — «расхождение максимум может быть в 20 минут»). Ничего не
        подгоняем: если вышло больше, показываем флаг.
        """
        if self.balance_unknown or not self.has_operator:
            return 0.0
        gap = self.operator_hours - self.operator_norm
        return round(gap, 2) if gap > TOLERANCE_H else 0.0

    @property
    def excess_from_machine_time(self) -> bool:
        """Переработка вышла из времени работы станка, а не из ошибки в данных.

        Если контроль за машиной пришлось поднять до времени работы станка по
        счётчику (правило 03.09.2026: часы не урезаем под 11,25), итог законно
        выходит за норму. Тогда в отчёте это объясняется, а не помечается как
        «проверьте данные».

        Потолок смены в это оправдание не входит: если часы пришлось обрезать
        до 12 ч (правило 25.09.2026), значит «времени работы станка» на всю
        историю не хватило бы физически, и данные надо проверять, а не
        объяснять счётчиком. Потолок присутствия человека — по той же причине:
        станок по счётчику работал дольше, чем оператор у него был, и это
        расхождение в данных, а не законная переработка.
        """
        if not self.operator_excess:
            return False
        if self.operator_ceiling_clip > 0.01:
            return False
        if self.operator_span_clip > 0.01:
            return False
        room = (self.operator_norm - self.operator_explicit_hours
                - self.full_absence_hours)
        return self.operator_machine_led_hours > room + 0.01

    @property
    def operator_present(self) -> float:
        """Совместимость с прежним расчётом: смена − обед − отсутствие."""
        return round(max(0.0, MACHINE_SHIFT_HOURS - self.lunch_hours
                         - self.absence_hours), 2)


def _fmt_h(value: float) -> str:
    """3.29 → «3,29 ч (3 ч 17 мин)»-совместимый короткий вид «3,29»."""
    text = f"{round(value, 2):.2f}".rstrip("0").rstrip(".")
    return (text.replace(".", ",") or "0")


def _fmt_hm(value: float) -> str:
    """Часы → «3 ч 17 мин»."""
    total = int(round(value * 60))
    h, m = divmod(total, 60)
    parts = []
    if h:
        parts.append(f"{h} ч")
    if m or not h:
        parts.append(f"{m} мин")
    return " ".join(parts)


def _fmt_int(value) -> str:
    try:
        return f"{int(round(float(value))):,}".replace(",", " ")
    except (TypeError, ValueError):
        return str(value)


def _balance_gap_line(r: ShiftMachineReport, balance: float) -> str:
    """Чем именно объясняется разница баланса станка с 12 ч.

    До этого сюда попадала любая разница и любая называлась «в пределах допуска»,
    хотя допуск ±20 мин: ст.98 за 21.09 печатала «расхождение 42 мин — в пределах
    допуска». Честный ответ в том, из чего она складывается: проверка на
    превышение (machine_excess) сознательно не считает обед станка, — значит,
    из него и состоит остаток. Задвоение минут здесь не упоминается: повторные
    минуты сняты со строк простоя до расчёта (см. _deduped_nonabsence) и
    называются в блоке «Почему станок простаивал».
    """
    gap = round(balance - MACHINE_SHIFT_HOURS, 2)
    tol = int(round(TOLERANCE_H * 60))
    if abs(gap) <= TOLERANCE_H:
        return (f"       ✅ расхождение {_fmt_hm(abs(gap))} — в пределах "
                f"допуска ±{tol} мин")
    if gap > 0:
        why = []
        if r.lunch_in_balance > 0.01:
            why.append(f"обед станка ({_fmt_hm(r.lunch_in_balance)})")
        if why and gap <= round(r.lunch_in_balance, 2) + TOLERANCE_H:
            return (f"       ✅ расхождение +{_fmt_hm(gap)} — это не "
                    f"переработка. Отдельно от 12 ч здесь: "
                    f"{', '.join(why)}. Проверка на превышение такие часы не "
                    f"учитывает")
    return (f"       ⚠️ расхождение {_fmt_hm(abs(gap))} — вне допуска "
            f"±{tol} мин, проверьте данные")


def format_shift_report(r: ShiftMachineReport) -> str:
    out: List[str] = []
    head = f"🏭 Станок №{r.machine or '—'}"
    if r.brand:
        head += f" ({r.brand})"
    if r.date:
        head += f" — {r.date}"
    out.append(head)
    if r.operator:
        out.append(f"👷 Оператор: {r.operator}")
    out.append("")

    out.append("📦 Выпуск и работа:")
    for ln in r.lines:
        h = machine_rates.work_hours(r.machine, ln.counter_start, ln.counter_end)
        descr = ln.assortment or "—"
        extra = ", ".join(x for x in (ln.client, f"№{ln.order_no}" if ln.order_no else None) if x)
        if extra:
            descr += f" ({extra})"
        if ln.output is not None and h is not None:
            out.append(f"   • {descr}: выпуск {_fmt_int(ln.output)} узл. → "
                       f"{_fmt_h(h)} ч ({_fmt_hm(h)})")
        elif ln.output is not None:
            out.append(f"   • {descr}: выпуск {_fmt_int(ln.output)} узл. "
                       f"(нет нормы для станка — время не посчитать)")
        else:
            out.append(f"   • {descr}: нет показаний счётчика")
    if r.rate:
        out.append(f"   Норма выработки: {_fmt_h(r.rate)} узл/мин")
    out.append(f"   Итого выпуск: {_fmt_int(r.output_total)} узл. | "
               f"Работа станка: {_fmt_h(r.work_hours)} ч ({_fmt_hm(r.work_hours)})")
    out.append("")

    # Срезы и число подмен утреннего блока — вчерашнее состояние станка, а не
    # результат смены (прогон 22.09.2026, ст.121: «Срез 3 из 3, Подмена 12 из
    # 17» при машине, весь день стоявшей в инженерной службе).
    if not r.nothing_produced:
        if r.subs_count or r.subs_hours:
            line = "🔁 Подмены"
            if r.subs_count:
                line += f": {r.subs_count}"
            if r.subs_hours:
                line += f" ({_fmt_h(r.subs_hours)} ч)" if r.subs_count else f": {_fmt_h(r.subs_hours)} ч"
            if r.subs_fio:
                line += f", на подмене — {r.subs_fio}"
            out.append(line)
        if r.cuts:
            out.append(f"✂️ Срезов: {r.cuts}")
    if r.stopped_stops:
        out.append(f"🛠 Технические остановки ({_fmt_h(r.tech_stops_total)} ч):")
        for s in r.stopped_stops:
            out.append(f"   • {_fmt_h(s.hours)} ч — {s.reason or 'без причины'}")
    if r.parallel_stops:
        out.append(f"🔄 Операции при работающем станке "
                   f"({_fmt_h(r.parallel_hours)} ч) — оператор не писал «стоп»:")
        for s in r.parallel_stops:
            out.append(f"   • {_fmt_h(s.hours)} ч — {s.reason or 'без причины'}")
        if r.parallel_extra:
            out.append(f"   ↳ из них {_fmt_h(r.parallel_extra)} ч не влезли во "
                       f"время работы станка ({_fmt_h(r.work_hours)} ч) — "
                       f"значит, станок в это время стоял, часы ушли в простой")
    if r.elsewhere_extra:
        # Часы, записанные в темах ДРУГИХ станков, но выполненные нашим
        # оператором (приказ №135 от 30.09.2026). В Excel они стоят строками
        # блока «Работа оператора», а в чате раньше не показывались вовсе:
        # итог «10,56 из 11,25» висел без единой строчки, откуда он взялся.
        out.append(f"↗️ Работа в чужих темах "
                   f"({_fmt_h(round(sum(s.hours for s in r.elsewhere_extra), 2))} ч)"
                   f" — её часы принадлежат оператору этого станка:")
        for s in r.elsewhere_extra:
            out.append(f"   • {_fmt_h(s.hours)} ч — {s.reason or 'без причины'}")
    if r.subs_count or r.cuts or r.tech_stops:
        out.append("")

    reasons = r.downtime_by_reason()

    def _who(label: str, by_operator: bool) -> str:
        """Пояснение к строке простоя: кому засчитаны часы."""
        if label.startswith("отсутствие оператора (ушёл"):
            return "часы засчитаны тому станку"
        return "оператор занят" if by_operator else "оператор не работал"

    if r.balance_unknown:
        out.append("⏸ Простои с причинами (время работы станка неизвестно):")
        if reasons:
            for label, hours, by_operator in reasons:
                out.append(f"   • {label} — {_fmt_h(hours)} ч "
                           f"({_fmt_hm(hours)}), {_who(label, by_operator)}")
        else:
            out.append("   • в сообщениях нет остановок с указанным временем")
    else:
        out.append(f"⏸ Почему станок простаивал ({_fmt_h(r.machine_downtime)} ч):")
        if reasons:
            for label, hours, by_operator in reasons:
                out.append(f"   • {label} — {_fmt_h(hours)} ч ({_fmt_hm(hours)}), "
                           f"{_who(label, by_operator)}")
        if r.unexplained_downtime > 0.01:
            out.append(f"   • ❓ {r.unexplained_label} — "
                       f"{_fmt_h(r.unexplained_downtime)} ч "
                       f"({_fmt_hm(r.unexplained_downtime)})")
        if r.cross_label_deduped > TOLERANCE_H:
            detail = ", ".join(f"«{label}» {_fmt_h(hours)} ч"
                               for label, hours in r.cross_label_dedup_detail)
            out.append(f"   • из этих часов {_fmt_h(r.cross_label_deduped)} ч "
                       f"— одни и те же минуты, названные двумя разными "
                       f"причинами: станок в них стоял ОДИН раз, повтор снят со "
                       f"строк простоя ({detail}). Часы оператора и работа по "
                       f"счётчику не тронуты")
        if not reasons and r.unexplained_downtime <= 0.01:
            out.append("   • простоя нет")
    if r.untimed_stops:
        out.append("")
        out.append("🕓 Простои без времени (в часы не попали — мастер не "
                   "указал начало и конец):")
        for s in r.untimed_stops:
            out.append(f"   • {s}")
    if r.log_timed_stops:
        out.append("")
        out.append("🕒 Этим простоям время посчитал код: мастер писал «стоп» и "
                   "«пуск» отдельными сообщениями, интервала в одной строке "
                   "нет:")
        for s in r.log_timed_stops:
            out.append(f"   • {s}")
    out.append("")

    out.append(f"📊 Итоги смены (норма: станок {_fmt_h(MACHINE_SHIFT_HOURS)} ч, "
               f"из них работа максимум {_fmt_h(r.machine_work_norm)} ч, "
               f"сотрудник {_fmt_h(r.operator_norm)} ч, "
               f"допуск ±{int(round(TOLERANCE_H * 60))} мин):")

    if r.engineering_all_shift:
        out.append(f"   🔧 Машина в инженерной службе: весь день "
                   f"{_fmt_h(MACHINE_SHIFT_HOURS)} ч — ремонт в инженерной "
                   f"службе. Норма работы на неё не ставится, обеда и "
                   f"недостатка времени по станку нет.")
        if r.operator_elsewhere_hours:
            where = ", ".join(r.operator_elsewhere_machines)
            out.append(f"   ↗️ Оператор в это время на станке "
                       f"{where or 'другом'} — {_fmt_h(r.operator_elsewhere_hours)}"
                       f" ч подмены (эти часы засчитаны тому станку).")
        if r.parallel_extra:
            out.append(f"   👷 Операции оператора при стоящем станке "
                       f"(навивка и т.п.): {_fmt_h(r.parallel_extra)} ч — "
                       f"идут в его личные часы, станку время не добавляют.")
        if r.warnings:
            out.append("")
            out.append("⚠️ Проверьте данные:")
            for w in r.warnings:
                out.append(f"   • {w}")
        return "\n".join(out)

    if r.naladka_all_shift_no_operator:
        out.append(f"   🔧 Станок весь день в наладке: "
                   f"{_fmt_h(MACHINE_SHIFT_HOURS)} ч — фамилии оператора по "
                   f"станку нет, значит обедать на нём некому: строки обеда и "
                   f"часов оператора не ставим (правило 03.09).")
        for label, hours, _by in r.downtime_by_reason():
            out.append(f"       • {_fmt_h(hours)} ч — {label}")
        if r.attracted_total:
            out.append(f"   🧑‍🔧 Привлекаемый персонал: "
                       f"{_fmt_h(r.attracted_total)} ч")
        if r.warnings:
            out.append("")
            out.append("⚠️ Проверьте данные:")
            for w in r.warnings:
                out.append(f"   • {w}")
        return "\n".join(out)

    if r.balance_unknown:
        out.append(f"   ⛔ Баланс времени не считаю: {r.balance_unknown}.")
        out.append(f"   ⚙️ Станок: учтённый простой "
                   f"{_fmt_h(r.accounted_downtime)} ч из 12 ч, "
                   f"время работы неизвестно.")
        # Часы человека печатаем тем же источником, что и обычный итог
        # (слагаемые + итог): станок без счётчика может СТОЯТЬ весь день, а
        # его оператор в это время работать в чужих темах (приказ №135 от
        # 30.09.2026, прогон 29.09 — ст.151, Вашурина: 10,56 ч из тем 111,
        # 121 и 251). Прежняя строка «операции при остановке 0 ч» эти часы
        # прятала: в чате выходило, что человек не работал, хотя в Excel его
        # блок стоял полный.
        body = " + ".join(f"{name} {_fmt_h(h)} ч"
                          for name, h in r.operator_hours_parts()) or "0 ч"
        out.append(f"   👷 Сотрудник: {body} = {_fmt_h(r.operator_hours)} из "
                   f"{_fmt_h(r.operator_norm)} ч")
        out.append(f"   🍽 Обед: {_fmt_hm(r.lunch_hours)}")
        if r.warnings:
            out.append("")
            out.append("⚠️ Проверьте данные:")
            for w in r.warnings:
                out.append(f"   • {w}")
        return "\n".join(out)

    balance = r.machine_balance
    out.append(f"   ⚙️ Станок: работа {_fmt_h(r.work_hours)} ч"
               + (f" + подмена на станке {_fmt_h(r.own_subs_hours)} ч"
                  if r.own_subs_hours else "")
               + f" + простой {_fmt_h(r.accounted_downtime)} ч = "
               f"{_fmt_h(balance)} из {_fmt_h(MACHINE_SHIFT_HOURS)} ч")
    if r.machine_shortfall:
        cause = ("это те простои, что мастер написал без времени (список выше)"
                 if r.untimed_stops else
                 "нет причины простоя или пропущено показание счётчика")
        out.append(f"       ⚠️ НЕДОСТАТОК ВРЕМЕНИ по станку: "
                   f"{_fmt_h(r.machine_shortfall)} ч "
                   f"({_fmt_hm(r.machine_shortfall)}) — {cause}")
    elif r.machine_excess:
        out.append(f"       ⚠️ ПРЕВЫШЕНИЕ на {_fmt_h(r.machine_excess)} ч "
                   f"({_fmt_hm(r.machine_excess)}) — часы простоя задвоены "
                   f"или пересекаются, проверьте данные")
    elif abs(balance - MACHINE_SHIFT_HOURS) > 0.01:
        out.append(_balance_gap_line(r, balance))
    else:
        out.append("       ✅ время станка сходится")

    # Слагаемые часов сотрудника берём одним источником с блоком его работ,
    # иначе строка не складывается в свой же итог (ст.151 за 27.08 печатала
    # «5,72 + 10,65 = 11,25»): работа станка — это время МАШИНЫ, а часы
    # человека собираются из его операций плюс контроль за работой машины.
    parts = r.operator_hours_parts()
    body = " + ".join(f"{name} {_fmt_h(h)} ч" for name, h in parts) or "0 ч"
    out.append(f"   👷 Сотрудник: {body} = {_fmt_h(r.operator_hours)} из "
               f"{_fmt_h(r.operator_norm)} ч")
    if r.operator_elsewhere_hours:
        where = ", ".join(r.operator_elsewhere_machines)
        out.append(f"       ↗️ уходил на станок {where or 'другой'} — "
                   f"{_fmt_h(r.operator_elsewhere_hours)} ч "
                   f"({_fmt_hm(r.operator_elsewhere_hours)}): в его часы это "
                   f"входит, а для этого станка — отсутствие оператора")
    away_rows = r.away_own_by_machine()
    if away_rows:
        # Иначе слагаемое «работа на других станках» нечем проверить: эти часы
        # мастер записал в переписке ДРУГОГО станка (правило Р23).
        where = ", ".join(f"№{num} — {_fmt_h(h)} ч" for num, h in away_rows)
        out.append(f"       ↗️ работал на станках: {where} — часы записаны в "
                   f"переписке тех станков, здесь они только в его итоге")
    if r.operator_shift_span < MACHINE_SHIFT_HOURS:
        # Откуда взялась короткая смена: сдал станок рано, пришёл поздно или по
        # станку просто нет данных с начала смены. Без этого в строке стояло
        # «до None».
        if r.operator_shift_end:
            when = f" (до {r.operator_shift_end})"
        elif r.operator_start:
            when = f" (с {r.operator_start})"
        elif r.first_info_time:
            when = f" (данные по станку с {r.first_info_time})"
        else:
            when = ""
        out.append(f"       ℹ️ смена сотрудника короче: "
                   f"{_fmt_h(r.operator_shift_span)} ч{when}")
    if r.operator_shortfall:
        # Часы простоя без работы оператора не могут превышать сам недостаток —
        # иначе из-за округления получается «0,52 ч, в т.ч. 0,53 ч».
        idle = min(r.absence_hours, r.operator_shortfall)
        out.append(f"       ⚠️ НЕДОСТАТОК ВРЕМЕНИ сотрудника: "
                   f"{_fmt_h(r.operator_shortfall)} ч "
                   f"({_fmt_hm(r.operator_shortfall)})"
                   + (f", в т.ч. {_fmt_h(idle)} ч — простой, где оператор "
                      f"не работал" if idle > 0.01 else ""))
    elif r.operator_excess:
        if r.excess_from_machine_time:
            out.append(f"       ℹ️ переработка {_fmt_h(r.operator_excess)} ч "
                       f"({_fmt_hm(r.operator_excess)}): станок по счётчику "
                       f"работал {_fmt_h(r.work_hours)} ч — это время у "
                       f"оператора не урезаем, часы как есть")
        else:
            out.append(f"       ⚠️ переработка {_fmt_h(r.operator_excess)} ч "
                       f"({_fmt_hm(r.operator_excess)}) — проверьте данные")
    else:
        out.append(f"       ✅ время сотрудника в норме "
                   f"(отклонение {_fmt_hm(abs(r.operator_deviation))})")
    if r.operator_ceiling_clip > 0.01:
        # Потолок смены (12 ч) срезал часы — пишем openly, какие именно и
        # откуда: иначе в отчёте стояло бы «12,00» без следа потерянных
        # 1,05 ч (21.09.2026, ст.251).
        #
        # Срезается не всегда филлер: когда одни названные операции длиннее
        # смены (14 ч по записям мастера при 07:00–19:00), «контроля за работой
        # машины» в обрезке нет вовсе, и прежняя фраза про него врёт.
        from_rows = r.operator_rows_over_shift
        from_filler = round(r.operator_ceiling_clip - from_rows, 2)
        why = []
        if from_filler > 0.01:
            why.append(f"{_fmt_h(from_filler)} ч «контроля за работой машины»")
        if from_rows > 0.01:
            why.append(f"{_fmt_h(from_rows)} ч названных мастером операций")
        out.append(f"       ⚠️ по записям у оператора "
                   f"{_fmt_h(r.operator_hours + r.operator_ceiling_clip)} ч, "
                   f"а смена 07:00–19:00 — только {_fmt_h(MACHINE_SHIFT_HOURS)} "
                   f"ч: {', '.join(why) if why else _fmt_h(r.operator_ceiling_clip) + ' ч'} "
                   f"в итог не вошли")
    clip_desc, clip_hours = r.operator_rows_clip
    if clip_hours > 0.01:
        # Строки блока «Работа оператора» сложены в тот же итог, что и сам итог
        # (правило Р22), а он ограничен сменой. Лишнее снимается с самой длинной
        # строки — убирать часы человека молча нельзя.
        out.append(f"       ⚠️ строки работы оператора длиннее смены: со строки "
                   f"«{clip_desc}» снято {_fmt_h(clip_hours)} ч — окна в "
                   f"переписке пересеклись, разберите их вручную")
    if r.operator_span_clip > 0.01:
        # Станок по счётчику работал дольше, чем человек у него был. Часы сверх
        # присутствия в строку оператора не идут — иначе отчёт рисует работу,
        # которой физически не было; что именно снято, сказано здесь, и в Excel
        # то же самое (молча потолок ничего не теряет).
        out.append(f"       ⚠️ станок по счётчику работал {_fmt_h(r.work_hours)} ч, "
                   f"а оператор у станка был {_fmt_h(r.operator_shift_span)} ч: "
                   f"{_fmt_h(r.operator_span_clip)} ч «контроля за работой машины» "
                   f"в его часы не вошли — времени у станка сверх присутствия не "
                   f"было. Сверьте, кто вёл станок в эти часы")
    if r.lunch_hours:
        out.append(f"   🍽 Обед: {_fmt_hm(r.lunch_hours)} — входит в простой "
                   f"станка, в часы сотрудника не входит. Поэтому работать "
                   f"станок может максимум {_fmt_h(r.machine_work_norm)} ч.")
        if r.lunch_trimmed and not r.balance_unknown:
            out.append(f"       ⚠️ в 12 ч смены из обеда уместилось только "
                       f"{_fmt_hm(r.lunch_in_downtime)}: работа по счётчику и "
                       f"простои почти закрыли смену — проверьте показания")
    if r.work_over_norm:
        out.append(f"       ⚠️ по счётчику станок работал "
                   f"{_fmt_h(r.work_hours)} ч — это больше предела "
                   f"{_fmt_h(r.machine_work_norm)} ч (12 ч − обед). "
                   f"Проверьте показания счётчика или норму отходов.")

    if r.warnings:
        out.append("")
        out.append("⚠️ Проверьте данные:")
        for w in r.warnings:
            out.append(f"   • {w}")
    return "\n".join(out)


def _digest_flag(r: ShiftMachineReport) -> str:
    """Один самый важный флаг станка для короткой сводки.

    В сводку идёт РОВНО ОДНА пометка на станок: смысл сводки — сказать, куда
    смотреть, а не пересказать отчёт. Порядок важности: сначала то, из-за чего
    цифр нет вообще, потом недостаток/переработка, потом замечания.
    """
    if r.balance_unknown:
        return f"⛔ баланс не считаю: {r.balance_unknown}"
    if r.machine_shortfall > TOLERANCE_H:
        return f"⚠️ недостаток по станку {_fmt_h(r.machine_shortfall)} ч"
    if r.machine_excess > TOLERANCE_H:
        return f"⚠️ превышение по станку {_fmt_h(r.machine_excess)} ч"
    if r.operator_excess > TOLERANCE_H:
        tail = " (объяснено счётчиком)" if r.excess_from_machine_time else ""
        return f"⚠️ у сотрудника +{_fmt_h(r.operator_excess)} ч{tail}"
    if r.operator_shortfall > TOLERANCE_H:
        return f"⚠️ у сотрудника −{_fmt_h(r.operator_shortfall)} ч"
    if r.warnings:
        return f"⚠️ замечаний: {len(r.warnings)}"
    return "✅"


def format_shift_digest(reports: List[ShiftMachineReport],
                        date: str = "") -> str:
    """КОРОТКАЯ сводка по смене: одна строка на станок.

    Просьба пользователя (04.09.2026): «когда данные обработались… чтобы он
    просто отправлял файл без большой информации о том, что есть в отчёте по
    каждому станку, чтобы не было ошибки что ответ слишком большой». Полные
    отчёты по станкам — в Excel и в файле для 1С; здесь только куда смотреть.

    Причина жёсткая: у Telegram лимит 4096 знаков на сообщение, а один
    полный отчёт по станку доходит до ~2 500 знаков и на плотной смене
    (много простоев и привлечённых) лимит перебивает — бот падал с
    «Bad Request: message is too long».
    """
    out: List[str] = []
    head = "✅ Отчёт готов"
    if date:
        head += f" за {date}"
    out.append(f"{head} — станков: {len(reports)}.")
    out.append("")
    for r in reports:
        name = f"№{r.machine or '—'}"
        who = f" {r.operator}" if r.operator else ""
        if r.no_shift_data:
            out.append(f"• {name} — нет данных / станок не работал")
            continue
        if r.engineering_all_shift:
            out.append(f"• {name} — инженерная служба весь день, "
                       f"{_fmt_h(MACHINE_SHIFT_HOURS)} ч")
            continue
        if r.naladka_all_shift_no_operator:
            out.append(f"• {name} — наладка весь день, "
                       f"{_fmt_h(MACHINE_SHIFT_HOURS)} ч, оператор не назван")
            continue
        if r.balance_unknown:
            out.append(f"• {name}{who} — {_digest_flag(r)}")
            continue
        out.append(f"• {name}{who} — станок {_fmt_h(r.work_hours)} ч работы "
                   f"+ {_fmt_h(r.accounted_downtime)} ч простоя, сотрудник "
                   f"{_fmt_h(r.operator_hours)} из {_fmt_h(r.operator_norm)} ч "
                   f"{_digest_flag(r)}")
    out.append("")
    out.append("Подробности по каждому станку — в файлах ниже: Excel (бланк "
               "смены и лист «Пояснение» с расшифровкой простоев) и выгрузка "
               "для 1С.")
    return "\n".join(out)



def _to_float(value) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip().replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return None


def _parse_tech_stops(machine: dict) -> List[TechStop]:
    """Собрать остановки из структуры ИИ.

    Поддерживает два вида: готовый список tech_stops:[{hours,reason}] и
    «экселевский» вид — строка часов «0,5+2,78+4,5» + строка причин
    «наладка+чинка+отсут опер» (параллельные списки через «+»).
    """
    stops: List[TechStop] = []
    raw = machine.get("tech_stops")
    if isinstance(raw, list):
        for item in raw:
            if isinstance(item, dict):
                h = _to_float(item.get("hours"))
                if h:
                    stops.append(TechStop(
                        round(h, 2), item.get("reason") or "",
                        other_machine=item.get("other_machine")))
        if stops:
            return stops
    hours_expr = machine.get("stops_hours") or machine.get("Q")
    reasons_expr = machine.get("stops_reasons") or machine.get("R")
    if hours_expr:
        hour_parts = [p for p in str(hours_expr).replace(",", ".").split("+") if p.strip()]
        reason_parts = [p.strip() for p in str(reasons_expr or "").split("+")]
        for i, hp in enumerate(hour_parts):
            h = _to_float(hp)
            if h is None:
                continue
            reason = reason_parts[i] if i < len(reason_parts) else ""
            stops.append(TechStop(round(h, 2), reason))
    return stops


def _time_to_min(value) -> Optional[int]:
    """«09:55», «9ч.55м», «10-45» → минуты от полуночи."""
    if value is None:
        return None
    import re
    m = re.search(r"(\d{1,2})\s*[:.чh;\-]\s*(\d{2})", str(value))
    if m:
        return int(m.group(1)) * 60 + int(m.group(2))
    m2 = re.fullmatch(r"\s*(\d{1,2})\s*", str(value))
    return int(m2.group(1)) * 60 if m2 else None


def _detect_other_machine(reason: str, own_machine) -> Optional[str]:
    """Найти в формулировке номер ДРУГОГО станка («навивка шпулей на 251»).

    Номер обязан быть в справочнике норм: в переписке полно чисел рядом с
    «на» («подмена на 90 шп.», «навито 247 из 303»), и без этой проверки
    подмена превращается в уход на несуществующий станок.
    """
    import re
    own = machine_rates._norm_key(own_machine)
    known = set(machine_rates.known_machines())
    nums = [m.group(1) for m in re.finditer(_ELSEWHERE_RE,
                                            (reason or "").lower())]
    # Свой станок назван местом работы — оператор никуда не уходил. Прогон
    # 21.09.2026, ст.251: «продолжение навивки шпулей на 251 по завершению
    # протяжки узлов на 321» дало «отсутствие оператора (ушёл на станок 321)»
    # и 1,37 ч «работы на других станках», хотя текст говорит о работе СВОИМИ
    # руками на своей машине, а 321 в нём — законченное дело.
    if own and own in nums:
        return None
    for num in nums:
        if num != own and num in known:
            return num
    return None


def _work_at_own_machine(reason: str, own_machine) -> bool:
    """Запись называет СВОЙ станок местом работы, а чужой — только упоминается.

    Модель склеивает два дела в одну строку: «продолжение навивки шпулей на 251
    по завершению протяжки узлов на 321» (прогон 21.09.2026, ст.251,
    17:37–18:59). Классификатор видит «протяжк» и ставит наш станок в простой на
    1,37 ч, хотя протяжка была НА 321 и уже закончена, а на 251 в это время
    навивали шпули при работающей машине (в переписке: 17:42 «В работе»,
    18:16 «Пуск машины»).

    Признак: в форме «на <номер>» упомянуты и СВОЙ станок, и другой из
    справочника норм. Одного чужого номера мало («ушёл на подмену на 251
    машину» для ст.98 — это уход), поэтому требуется именно пара «свой +
    чужой» в одной записи.
    """
    low = (reason or "").lower()
    nums = [m.group(1) for m in re.finditer(_ELSEWHERE_RE, low)]
    own = machine_rates._norm_key(own_machine)
    known = set(machine_rates.known_machines())
    return own in nums and any(n != own and n in known for n in nums)


def _validated_other_machine(value, reason: str, own_machine) -> Optional[str]:
    """other_machine из ответа ИИ — только РЕАЛЬНЫЙ станок и только УХОД.

    Модель ставит other_machine по любой фразе «N машина …», включая «6 машина
    в подработке» (прогон 09.09.2026, ст.98). Подработка — это ВТОРАЯ машина
    ПАРАЛЛЕЛЬНО своей: оператор никуда не уходил. Без проверки 12 ч «замены
    шпулярника в течении смены» уезжали на чужой (да ещё и отсутствующий в
    парке) станок, контроль за своей машиной добавлялся сверху, и оператор
    получал 23,6 ч при норме 11,25 с ложным флагом «+12,35 ч».

    Поэтому номер, пришедший от ИИ, проверяется так же, как найденный в тексте
    (_detect_other_machine): станок обязан быть в справочнике норм, а слова
    «в подработке» отменяют уход даже для известного номера — это параллельная
    работа (см. machine_stopped_for: «78 маш. в подработке» — наша РАБОТАЕТ).
    Если номер ИИ не прошёл проверку, пробуем найти уход в тексте причины.
    """
    num = machine_rates._norm_key(str(value).replace(" ", "")) if value else ""
    known = set(machine_rates.known_machines())
    if (num and num != machine_rates._norm_key(own_machine) and num in known
            and "подработк" not in (reason or "").lower()):
        return num
    return _detect_other_machine(reason, own_machine)


def _lunch_covered_in_text(text: str) -> bool:
    """Обед прошёл при ПЕРЕДАННОЙ машине — станок не стоял, строки обеда нет.

    Смотрим по сообщениям (строкам раздела): слово «обед» и передача машины
    должны стоять В ОДНОМ сообщении. Иначе «передал машину в наладку» в 8 утра
    отменяло бы обед в 12:00. Прогон 20.09.2026, ст.151: «12:45-13:30- обед.
    Передаю машину под наблюдение Петровскому» и отдельным сообщением «Взял
    151 машину под наблюдение на время обеда» — станок вели, простоя не было.
    """
    for line in (text or "").splitlines():
        if _LUNCH_WORD_RE.search(line) and _LUNCH_TAKEOVER_RE.search(line):
            return True
    return False


# ─────────── время простоя из пар «стоп → пуск» ───────────
#
# Мастер пишет остановку и пуск РАЗНЫМИ сообщениями, каждое со своим временем:
# «11:20 стоп машина, чинка на 2 полотнах» и «11:48 пуск машина». Интервала в
# одной строке нет, поэтому ИИ по такому событию отдаёт только начало (или
# только конец). До этой правки такое событие уезжало в «время не указано у
# причин», а станок печатал «!!! РАСХОЖДЕНИЕ: станок −2,33 ч до 12 ч» (прогон
# 27.09.2026, ст.321) — хотя минуты простоя в переписке стояли прямым текстом.
#
# Считаем их кодом, не моделью: окно берётся ТОЛЬКО из строк состояния самой
# машины, и событию добавляется граница, если его время уже лежит внутри этого
# окна. Событие, которое пришлось на минуты работающей машины, остаётся без
# времени — выдумывать простой по «16:35 замена катушки» (без слова «стоп»)
# нельзя, это правило 24.09.2026.
_LOG_STOP_STATE_RE = re.compile(
    r"стоп|останов|встала|не работ|простой", re.IGNORECASE)
_LOG_RUN_STATE_RE = re.compile(
    r"\bпуск\b|запуск|запусти|в работу|в работе|работает|"
    r"передан\w* в работ|продолжи\w* работ", re.IGNORECASE)
_LOG_LUNCH_WORD_RE = re.compile(r"обед|перерыв", re.IGNORECASE)
# Время строки: «11:20», «13: 49», «9,39». Разделитель ОБЯЗАТЕЛЕН — иначе
# показания счётчика («1450», «1000») читаются как 14:50 и 10:00. Дата
# «05.08.2026» не мешает: перед числом стоит точка или цифра.
_LOG_TIME_RE = re.compile(r"(?<![\d.,:])(\d{1,2})\s*[:,]\s*(\d{2})(?![\d])")
# Общая лексика переписки: в окне простоя таких слов достаточно у каждой
# причины, сопоставлять по ним нельзя.
_LOG_STOP_WORD_RE = re.compile(
    r"останов|простой|чинк|наладк|срез|ремонт|замена|поломк|обрыв|стоп",
    re.IGNORECASE)
_LOG_WORK_KIND_RE = re.compile(
    r"работа|подмен|обед|перерыв|отсутств|навивк|развивк", re.IGNORECASE)

# ——— Как мастер пишет останов и пуск (приказы владельца от 29.09.2026) ———
#
# Прогон 28.09.2026, ст.321: мастер ведёт смену одними парами
# «07:04: Чинка пропуска на 3 полотне» → «07:19: Вычинил». Ни «стопа», ни
# «пуска» в этих строках нет, и прежнее окно по ним не открывалось — простой
# лежал в отчёте строкой «причина не указана». Хозяин просит считать минуты
# именно по такой паре и 29.09 разъяснил словарь: «мастер может писать вычинена
# / пуск / устранено и тд», «при обрыве тоже идет остановка», «при подстановки
# шпуль тоже машина в стопе».
#
# Одиночная строчка про чинку НИЧЕГО не даёт: окно останется незакрытым и, как
# и раньше, в расчёт не возьмётся. Это правило 24.09.2026 — «16:35 замена
# катушки» без слова «стоп» простым станка быть не может.

# Останов — операция, которую на ходу не делают: чинка, ремонт, обрыв нити,
# подстановка шпуль, сошедшая шпуля.
_LOG_FIX_OPEN_RE = re.compile(
    r"чинк|починк|ремонт|обрыв|оборв|подстав|"
    r"сош(?:ё|е)?л\w* шпул|шпул\w* сош(?:ё|е)?л|сходят шпул",
    re.IGNORECASE)
# «Если в начале смены пишется состояние машины как в наладке и далее,
# например в 9 утра, "передана оператору" — эти 2 часа это наладка» (приказ
# владельца от 29.09.2026). Станок в наладке не мотает полотно, поэтому такая
# строка открывает окно простоя наравне с «стоп».
#
# Берём только СОСТОЯНИЕ машины, а не всякое слово «наладка»: «Требуется
# служба наладки», «Пропуски во время наладки», «после наладки шпульного
# стола», «принем машины в работу от службы наладки» — это план, воспоминание
# или пуск, и окно по ним открывать нельзя.
_LOG_NALADKA_STATE_RE = re.compile(
    r"(?:\bмашин\w*|\bстанк\w*)[^.;]{0,12}?\b(?:в|на)\b[^.;]{0,9}?\bналадк"
    r"|\b(?:передаю|передал\w*|передам|отдаю|отдал\w*|поставл\w*|ставлю|"
    r"взял\w*|взята|беру)\b[^.;]{0,20}?\b(?:в|на)\b[^.;]{0,9}?\bналадк",
    re.IGNORECASE)
# Утреннее состояние мастер пишет и ДО начала смены: «06:58 Машина в службе
# наладки» (251 за 25.09), «151 машина(в службе наладки до ❓)» (25.09, 28.09).
# Такую отметку видим, но часами простоя она становится только с 07:00 —
# раньше смены нет.
_LOG_EARLY_STATE_MIN = 20
# То же слово как цель, план или воспоминание — не состояние машины:
# «09:47 Включаю машину для спуска узлов для чинки» (251, 28.09) пишет про
# ПУСК, а не про останов, и открывать по нему окно нельзя.
_LOG_FIX_PURPOSE_RE = re.compile(
    r"(?:для|во\s*время|в\s*теч\w*|после|перед|нужна|требуется|будет|"
    r"планир\w*)\s+[^.;]{0,14}$", re.IGNORECASE)
# Отрицание рядом со словом про остановку: «Нити шпулярника … обрывов со
# шпулярника не обнаружено», «полотна чистые, без обрывов и дыр» (251, 28.09
# 11:47). Машина тут стоит или мотает — из строки не следует, а выдуманное
# окно простоя дороже пропущенного.
_LOG_FIX_NEGATED_RE = re.compile(
    r"(?:без|нет)\s+\S*обрыв|нет\s+\S*(?:обрыв|дыр|несоответств|замеч)|"
    r"не\s+(?:обн\w*|выявл\w*|замеч\w*|установл\w*|был\w*|буд\w*)",
    re.IGNORECASE)
# Пуск: ремонт завершён — машина снова работает. Здесь же «Машина передана
# оператору» (Пронкин, 22.09 15:27 и 25.09 07:20; Шалыминов, 26.09/27.09 09:35):
# по приказу 29.09 утренние часы «в наладке» кончаются ровно этой фразой.
# «Наладка выполнена» (Александр Р., 25.09 08:13) и «Калинюк выполнил наладку
# стола» (28.09 13:20) закрывают окно по тому же основанию — наладка закончена.
# Пристрастное «по окончанию данной операции производите подмену шпуль» (лола п.,
# 14:17) — задание, а не пуск: форма «окончанию» под «законченную» не попадает,
# а она ниже смотрит на слово про ремонт в той же фразе.
_LOG_FIX_DONE_RE = re.compile(
    r"вычин|починил|выналад|устранил|устран[её]н|исправл|"
    r"передан\w* оператор\w*|принял\w* машин|"
    r"наладк\w*\s+(?:уже\s+)?выполн|выполн\w*\s+наладк", re.IGNORECASE)
_LOG_FIX_END_RE = re.compile(r"законч|оконч", re.IGNORECASE)

# ——— Стопка одного шпинделя станок не останавливает ———
#
# Приказ 29.09.2026: «про остановку одного шпинделя не влияет на работу машины».
# «11:56 Стоп шпиндель √2 … Вью шпули на шпинделях √1,3,4,5» (111 за 26.09 и
# 27.09 — 49 и 83 мин) и «первый шпиндель стоп» (251 за 14.09) — навивка идёт
# остальными шпинделями, общий счётчик растёт, и такие минуты простым станка
# быть не могут. Тем же словом гасится и «стоп навивка / стоп-наводка»: встанет
# навивочный аппарат, а сам станок мотает полотно (правило 24.09 про навивку).
_LOG_SPINDLE_RE = re.compile(r"шпиндел", re.IGNORECASE)
_LOG_UNIT_STOP_RE = re.compile(
    r"стоп[-\s,]*(наводк|навивк|развивк)|(навивк|развивк)[-\s,]*стоп",
    re.IGNORECASE)
_LOG_MACHINE_WORD_RE = re.compile(r"машин|станок", re.IGNORECASE)
# «Оператор ушёл на подмену или другую машину — его машина стоп» (приказ
# владельца от 29.09.2026). Ищем ушедшего человека и ДРУГОЙ номер в той же
# фразе: «**16:58** стоп навивка. Перешла в работу на 151 машину» (111 за
# 26.09 и 27.09), «14:45- ушла на подмену на 111м» и «15:55- перешла нумеровать
# шпули на 151м» (251 за 28.09), «08:10: Ушел на 151 на перезаправу» (251 за
# 26.09). Без этого строка проходила как «чужая машина» и состояние нашей
# машины по ней не решалось вовсе.
_LOG_OPERATOR_LEFT_RE = re.compile(
    r"\b(?:переш|отош|уш|отправ|переключ)[ёе]?л[а-яё]{0,3}\b"
    r".{0,40}?(?:на|в)\s+№?\s*\d{2,3}(?![\d])",
    re.IGNORECASE)
# ЯВНОЕ состояние станка: слово «машина/станок» СТОИТ ПЕРЕД словом про останов.
# «16:07 … Машина остановлена для нумерации челноков» (28.09, ст.111) мастер
# пишет не первым предложением, и отметку «стоп» по первой фразе код не видит.
# Приказ 29.09: «если написана машина остановлена для нумерации челноков значит
# это простой машины, пуска не было».
# «время останова машины» (диспетчер, 24.09) под этот порядок не попадает — там
# машина стоит ПОСЛЕ слова, и это план, а не состояние.
_LOG_MACHINE_STOP_STATE_RE = re.compile(
    r"(?:\bмашин\w*|\bстанк\w*)([^.;]{0,18}?)(?:остановл\w*|остановил[а-яё]{0,4}|"
    r"в\s+стоп\w*|не\s+работ\w*|встала|стоит)",
    re.IGNORECASE)
# Показание общего счётчика в строке переписки: «Общ. сч. - _234542_»,
# «Об. Сч. 234563», «общ.сч 304851», «Общий счётчик 21574050». Нужно как
# доказательство: счётчик стоит — машина не работала, и отсутствие слова «пуск»
# означает, что станок так и ушёл со смены (приказ 29.09: «время брать можно по
# счётчикам, если по времени отправки не решить или не написано время в
# сообщении»).
_LOG_TOTAL_COUNTER_RE = re.compile(
    r"(?<![\w])(?:общ(?:ий)?|об)\s*\.?\s*(?:сч|ся|сь|ще)(?:ет|ёт)?[а-яё]*"
    r"\s*[.:]?\s*(?:[-–—:]\s*)?_?(\d{4,})",
    re.IGNORECASE)
# «При повторном не переброси машина будит остановлена» (321, 28.09) — обещание
# на будущее, а не состояние станка в эту минуту.
_LOG_FUTURE_RE = re.compile(r"\bбуд(?:ет|ите|ит|им|у|и?тя)\b", re.IGNORECASE)
# ——— «Машина на подмене»: станок ждёт заправки полотна и не мотает ———
#
# Приказ владельца от 29.09.2026 по ст.111 за 28.09: «нет — это не отсутствие
# заказа. по 111 машине же написны останоки по оператору и это типо было время
# навивки шпуль. Там тоже в начала смены писалось что машина на подмене. Если
# машина на подмене и оператор пишет навивку шпуль в это же время что и подмена
# то машина в стопе».
#
# Ищем СОСТОЯНИЕ, а не всякое слово про подмену: «на подмену» (это направление:
# «перешла на подмену»), «подмена начата», «шпули нужны для подмены» станок не
# описывают. Номер машины перед словом обязателен — так же, как в остальных
# словарях переписки: «Состояние машины: Машина на подмене» (27.09), «Машина
# в рабочем состоянии, на подмене» (26.09).
_SUBMEN_STATE_RE = re.compile(
    r"(?:\bмашин\w*|\bстанк\w*)[^.;]{0,30}?\bна\s+подмен[её]\b", re.IGNORECASE)
# Подмена кончилась — станок пошёл, и окно состояния закрывается: «15:55 подмена
# закончена» (111, 28.09), «8:06 подмена окончена» (26.09). «Подмена начата»
# началом смены не считается — её часы уже названы подменой.
_SUBMEN_STATE_END_RE = re.compile(
    r"\bподмена\s+(?:уже\s+)?(?:законч|оконч|заверш|окончен)\w*",
    re.IGNORECASE)


def _log_clauses(seg: str) -> List[str]:
    """Фразы куска строки: «стоп-наводка на 111. Машина 251 остановилась».

    Хозяин 29.09 разрешил читать состояние машины и из чужой строки, если в ней
    назван её номер («брат, состояние можно, если назван номер»), — а для этого
    фразы надо видеть по отдельности: в этой строке одна про 111, другая про 251.
    """
    return [p.strip(" :,:-") for p in re.split(r"[.;!?]", seg) if p.strip(" :,:-")]


def _log_first_clause(seg: str) -> str:
    """Первое предложение куска строки — до «.» или «;».

    Слово «стоп» мастер пишет ПЕРВЫМ («11:20 стоп машина, чинка»); если оно
    всплыло в середине фразы, это обычно не состояние машины, а разговор о
    планах. Прогон 24.09.2026, ст.111: диспетчер в 14:14 написал «На подмену шпулей
    привлекаемые сотрудники: …, ориентировочное время останова машины на
    подмену с 15.00» — по этому слову окно простоя открывалось на 14:14–15:22
    и дотягивало чужие события до 15:22, чего мастер про свою машину не писал.
    """
    parts = _log_clauses(seg)
    return parts[0] if parts else ""


def _log_machine_res(own_machine):
    """Свой номер и чужие номера станка для строк переписки.

    Нужен и отметкам состояния (_log_state_marks), и проверке пуска
    (_log_strong_run): решение о нашей машине по чужому номеру принимать
    нельзя (приказ 29.09: «состояние можно, если назван номер»).
    """
    own_key = str(own_machine or "").strip()
    own_re = (re.compile(r"(?<![\w\d])" + re.escape(own_key) + r"(?![\w\d])")
              if own_key else None)
    others = [m for m in machine_rates.known_machines()
              if machine_rates._norm_key(m) != machine_rates._norm_key(
                  own_machine)]
    other_res = [re.compile(r"(?<![\w\d])" + re.escape(o) + r"(?![\w\d])")
                 for o in others]
    return own_re, other_res


def _submen_state_clause(seg: str, own_re, other_res) -> str:
    """Фраза строки, где машина названа «на подмене» (или подмена закончена).

    `_log_watch_clause` здесь не годится: он оставляет ПЕРВУЮ фразу, а состояние
    мастер дописывает в конец строки — «11:45-12:30 обед. Передаю навивку шпулей
    … Машина на подмене» (ст.111 за 28.09). Фразы с номером чужой машины
    пропускаем: приказ 29.09 — «состояние можно, если назван номер», а чужая
    подмена нашу машину не ставит.
    """
    for clause in _log_clauses(seg):
        if (any(r.search(clause) for r in other_res)
                and not (own_re and own_re.search(clause))):
            continue
        if (_SUBMEN_STATE_RE.search(clause)
                or _SUBMEN_STATE_END_RE.search(clause)):
            return clause
    return ""


def _log_state_marks(section_text: str, own_machine) -> List[Tuple[int, str, str]]:
    """Строки смены состояния станка: [(минуты, вид, текст)].

    Вид — «stop», «run», а также «submen»/«submen_end» (станок назван «на
    подмене» и подмена названа законченной); последние читают только окна
    состояния, окна «стоп … пуск» их не трогают.

    Одна строка может содержать несколько времён («10:51-11:10- Пропуск узлов,
    наладка. 11:10- Машина передана в работу») — режем её по временим и решаем
    про каждый кусок отдельно, иначе «11:10 передана в работу» уехало бы под
    время 10:51.

    Состояние решаем по фразе, а не по куску целиком: «11:06 стоп-наводка на
    111. Машина 251 остановилась» для 251 — останов, хотя «стоп» в первой фразе
    относится к навивке другой машины (приказ 29.09: «состояние можно, если
    назван номер»).

    Придуманный по чужим словам «останов» дороже пропущенного «пуска»:
    лишнее окно создаёт простой там, где станок работал, а незакрытое окно
    всё равно отбрасывается.
    """
    if not section_text:
        return []
    own_re, other_res = _log_machine_res(own_machine)
    lo = int(SHIFT_START_H * 60)
    hi = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
    earliest = lo - _LOG_EARLY_STATE_MIN
    out: List[Tuple[int, str, str]] = []
    for line in (section_text or "").splitlines():
        found = list(_LOG_TIME_RE.finditer(line))
        if not found:
            continue
        for i, m in enumerate(found):
            try:
                hour, minute_of_hour = int(m.group(1)), int(m.group(2))
            except ValueError:
                continue
            if hour > 23 or minute_of_hour > 59:
                continue
            total = hour * 60 + minute_of_hour
            if total < earliest or total > hi:
                continue
            total = max(total, lo)
            end = found[i + 1].start() if i + 1 < len(found) else len(line)
            seg = line[m.end():end].strip(" :–-")
            if not seg:
                continue
            if (_LOG_OPERATOR_LEFT_RE.search(seg)
                    and any(r.search(seg) for r in other_res)):
                # Ушли НА ДРУГУЮ машину — стоит наша (приказ 29.09.2026).
                # Проверять это надо ДО фильтра «строка про другой станок»:
                # номер в ней назван чужой, а машина от этого встаёт своя.
                out.append((total, "stop", seg))
                continue
            if (any(r.search(seg) for r in other_res)
                    and not (own_re and own_re.search(seg))):
                # Строка про другой станок (чужая тема, пересказ) — состояние
                # нашей машины по ней решать нельзя. Если же наш номер назван,
                # строку читаем: приказ 29.09 — «состояние можно, если назван
                # номер».
                continue
            if _log_run_at(seg, own_re, other_res):
                out.append((total, "run", seg))
            elif _log_stop_at(_log_watch_clause(seg, own_re), seg):
                out.append((total, "stop", seg))
            # Состояние «на подмене» мастер пишет СЛОВОМ ПРО ПОДМЕНУ, и оно
            # стоит в строке рядом с пуском («датчик … работает исправно»,
            # 06:40, ст.111 за 28.09). Окна «стоп … пуск» от этого не меняются,
            # поэтому отметку отдаём ОТДЕЛЬНО, а не в тот же выбор.
            submen_clause = _submen_state_clause(seg, own_re, other_res)
            if submen_clause:
                kind = ("submen" if _SUBMEN_STATE_RE.search(submen_clause)
                        else "submen_end")
                out.append((total, kind, submen_clause))
    return out


def _log_watch_clause(seg: str, own_re) -> str:
    """Фраза, по которой решаем состояние НАШЕЙ машины.

    «11:06 стоп-наводка на 111. Машина 251 остановилась» — строку пишет
    Арташина про свою навивку, и для 251 состоянием является вторая фраза, где
    её номер назван прямо. Своего номера в строке нет — как и раньше, смотрим
    первую фразу.
    """
    if own_re is not None:
        for clause in _log_clauses(seg):
            if own_re.search(clause):
                return clause
    return _log_first_clause(seg)


def _log_run_at(seg: str, own_re, other_res) -> bool:
    """Запускает ли кусок строки нашу машину.

    Слово пуска, привязанное к чужому номеру, нашу машину не запускает: «16:58
    стоп навивка. Перешла в работу на 151 машину — заправка нити» (111,
    26.09/27.09) по приказу 29.09 означает обратное — «когда оператор уходит на
    подмену или другую машину, то его машина стоп».
    """
    for clause in _log_clauses(seg):
        if not (_LOG_RUN_STATE_RE.search(clause) or _LOG_FIX_DONE_RE.search(clause)
                or (_LOG_FIX_END_RE.search(clause)
                    and _LOG_FIX_OPEN_RE.search(clause))):
            continue
        if own_re is not None and own_re.search(clause):
            return True
        if any(r.search(clause) for r in other_res):
            continue
        return True
    return False


def _log_stop_at(clause: str, seg: str) -> bool:
    """Останов ли эта фраза — по слову «стоп» или по слову про работу на стоянке.

    «стоп» ищем во фразе, а обед — по всему куску строки: окно обеда станка этим
    циклом не открывается, иначе 45 минут посчитались бы дважды
    (lunch_in_downtime).
    """
    if not clause or _LOG_LUNCH_WORD_RE.search(seg):
        return False
    if _spindle_only_stop(clause):
        # Остановлен один шпиндель или навивочный аппарат, а станок мотает
        # остальными шпинделями (приказ 29.09).
        return False
    if _LOG_STOP_STATE_RE.search(clause):
        return True
    m = _LOG_FIX_OPEN_RE.search(clause) or _LOG_NALADKA_STATE_RE.search(clause)
    if not m:
        return False
    if _LOG_FIX_PURPOSE_RE.search(clause[:m.start()]):
        return False
    if re.search(r"(?:не|ни|без)\s+$", clause[max(0, m.start() - 5):m.start()],
                 re.IGNORECASE):
        # «шпули не сошли», «обрывов нет» — отрицание прямо перед словом.
        return False
    around = clause[max(0, m.start() - 30):m.start() + 45]
    return not _LOG_FIX_NEGATED_RE.search(around)


def _log_is_restart_only(text: str) -> bool:
    """«Вычинил», «Пуск», «Устранено» — пуск машины, а не ПРИЧИНА простоя.

    Прогон 28.09.2026, ст.321: модель отдала «вычинил» событием без времени, и в
    отчёте слово висело отдельной причиной остановки, хотя мастер пишет им
    обратное — станок пошёл (приказ 29.09: «мастер может писать вычинена / пуск /
    устранено»). В расшифровке работы оператора слово остаётся.
    """
    t = (text or "").strip()
    if not t or len(t) > 40 or _LOG_STOP_STATE_RE.search(t):
        return False
    return bool(_LOG_RUN_STATE_RE.search(t) or _LOG_FIX_DONE_RE.search(t))


def _log_stop_windows(section_text: str, own_machine) -> List[Tuple[int, int, str]]:
    """Окна простоя по переписке: «стоп» открывает окно, «пуск» закрывает.

    Повторное «стоп» внутри открытого окна — это та же остановка, о которой
    мастер пишет подробнее («17:20 стоп машина на срез», «17:30 машина в стопе
    замена 5 сошедших катушек»), поэтому окно НЕ закрывается, а текст причины
    дополняется.

    Незакрытое окно НЕ используется. Дотягивать простой до 19:00 нельзя: у
    станка №151 за 14.09.2026 мастер написал «11:15 стоп машина, чинка полотна»
    и дальше только показания счётчика (763212 → 764019 → 765337 → 766068), то
    есть машина между этим РАБОТАЛА, а слова «пуск» в теме нет. По такому логу
    честный ответ — «время не указано», а не останов 11:15–19:00 (7,75 ч),
    который переворачивал баланс станка в «+3,82 ч сверх 12 ч».
    """
    marks = sorted(_log_state_marks(section_text, own_machine),
                   key=lambda t: t[0])
    windows: List[Tuple[int, int, str]] = []
    start: Optional[int] = None
    text = ""
    for minute, kind, seg in marks:
        if kind in ("submen", "submen_end"):
            # Слово про подмену — не пуск и не останов: окно «стоп … пуск» по
            # нему не открывается и не закрывается (его читает только окно
            # состояния — см. _submen_state_windows).
            continue
        if kind == "stop":
            if start is None:
                start, text = minute, seg
            elif seg not in text:
                text = (text + "; " + seg)[:200]
            continue
        if start is not None:
            if minute > start:
                windows.append((start, minute, text))
            start, text = None, ""
    return windows


def _log_strong_run(seg: str, own_machine) -> bool:
    """Пошло бы НАШЕ полотно по словам этой строки, или это только рассказ о деле.

    Окно «на подмене» закрывает настоящий пуск машины. «13:20 Калинюк Д. В.
    выполнил наладку стола — шпинделей √1,2» (ст.111 за 28.09) словарь пуска
    узнаёт по слову «выполнена наладка» и ставит отметку «run», но станок в эту
    минуту стоял на подмене: наладили ШПУЛЬНЫЙ СТОЛ, а не пустили машину. Чужой
    пуск («прием машины 251 в работу», 11:33) нашу машину тем более не запускает.
    """
    own_re, other_res = _log_machine_res(own_machine)
    for clause in _log_clauses(seg):
        if not _LOG_RUN_STATE_RE.search(clause):
            continue
        if own_re is not None and own_re.search(clause):
            return True
        if any(r.search(clause) for r in other_res):
            continue
        return True
    return False


def _submen_state_windows(section_text: str,
                          own_machine) -> List[Tuple[int, int]]:
    """Минуты, которые станок простоял «на подмене» по своим строкам состояния.

    Открывает окно «машина на подмене», закрывает — «подмена закончена/окончена»
    или настоящий пуск машины (см. _log_strong_run). Если мастер ни того, ни
    другого не написал, окно тянется до 19:00: состояние станка он обязан снять
    в конце смены, и «на подмене» со словами «Конец смены» значит, что так она и
    ушла.
    """
    marks = sorted(_log_state_marks(section_text, own_machine),
                   key=lambda t: t[0])
    end = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
    windows: List[Tuple[int, int]] = []
    start: Optional[int] = None
    for minute, kind, seg in marks:
        if kind == "submen":
            if start is None:
                start = minute
            continue
        if start is None:
            continue
        if kind == "submen_end" or (kind == "run"
                                    and _log_strong_run(seg, own_machine)):
            if minute > start:
                windows.append((start, minute))
            start = None
    if start is not None and end > start:
        windows.append((start, end))
    return _merge_intervals(windows)


def _log_line_time(line: str) -> Optional[int]:
    """Время отправки строки переписки: «Татьяна Арташина, 16:07: …».

    Первое время в строке — время сообщения; времена внутри текста («19:00
    Конец смены») относятся к событиям, а не к отправке.
    """
    lo = int(SHIFT_START_H * 60) - _LOG_EARLY_STATE_MIN
    hi = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
    for m in _LOG_TIME_RE.finditer(line):
        try:
            total = int(m.group(1)) * 60 + int(m.group(2))
        except ValueError:
            continue
        if lo <= total <= hi:
            return max(total, int(SHIFT_START_H * 60))
    return None


def _log_explicit_stop_states(section_text: str,
                              own_machine) -> List[Tuple[int, str]]:
    """Строки, где мастер ЯВНО записал состояние станка: «машина остановлена …».

    Отметку «стоп» ищет по любой фразе строки, а не по первой, как
    `_log_state_marks`: состояние может стоять в конце длинного сообщения с
    показаниями счётчиков. Фраза с номером ДРУГОЙ машины не считается (приказ
    29.09: «состояние можно, если назван номер» — своего).
    """
    if not section_text:
        return []
    others = [m for m in machine_rates.known_machines()
              if machine_rates._norm_key(m) != machine_rates._norm_key(
                  own_machine)]
    other_res = [re.compile(r"(?<![\w\d])" + re.escape(o) + r"(?![\w\d])")
                 for o in others]
    out: List[Tuple[int, str]] = []
    for line in section_text.splitlines():
        minute = _log_line_time(line)
        if minute is None:
            continue
        for clause in _log_clauses(line):
            m = _LOG_MACHINE_STOP_STATE_RE.search(clause)
            if not m:
                continue
            if "не " in m.group(1) or "ни " in m.group(1):
                continue      # «машина не останавливалась»
            if _LOG_FUTURE_RE.search(clause):
                continue      # «машина будит остановлена» — обещание, не факт
            if any(r.search(clause) for r in other_res):
                continue      # строка про другой станок
            out.append((minute, clause.strip()[:200]))
    return out


def _log_counter_points(section_text: str) -> List[Tuple[int, int]]:
    """Показания общего счётчика вместе с минутой сообщения: [(минута, число)].

    Читает проверенный счётчик (`counter_check.counter_readings`): он отделяет
    общий счётчик от срезового («Со.сч.1000 из 1450»), не берёт числа из
    размеров полотна и знает опечатки. Минуту берёт ВРЕМЯ ОТПРАВКИ сообщения
    («Евгения Вашурина, 12:22: …»), как и просит приказ 29.09: сначала время
    отправки, счётчик — доказательством.

    Рядом идёт поиск по метке «Общ.сч»: вечернюю сводку мастер пишет то
    «Общ. сч. 234563», то «Общ.ся-304851» (251 за 28.09), и читатель счётчиков
    такой опечатки не знает. Берём только ОБЩИЙ счётчик — метка «общ/об» стоит
    перед числом, поэтому срезовые числа («срез.сч-731») сюда не попадают.
    """
    from . import counter_check
    seen: set = set()
    out: List[Tuple[int, int]] = []

    def add(minute, value):
        if minute is None:
            return
        try:
            pair = (int(minute), int(value))
        except (TypeError, ValueError):
            return
        if pair not in seen:
            seen.add(pair)
            out.append(pair)

    try:
        for minute, _author, value in counter_check.counter_readings(
                section_text or ""):
            add(minute, value)
    except Exception:
        pass
    for line in (section_text or "").splitlines():
        minute = _log_line_time(line)
        for m in _LOG_TOTAL_COUNTER_RE.finditer(line):
            add(minute, m.group(1))
    return sorted(out)


def _log_counter_stopped(section_text: str, from_min: int) -> bool:
    """Вырос ли общий счётчик после from_min: доказательство, что машина шла.

    Доказательство ищет только когда показания есть (минимум два разных
    сообщения): без счётчиков в теме код ничего не утверждает, и решение
    остаётся за словами мастера.
    """
    values = [v for t, v in _log_counter_points(section_text) if t >= from_min]
    if len(values) < 2:
        return True
    return values[-1] <= values[0]


def _log_open_stop_tail(section_text: str,
                        own_machine) -> List[Tuple[int, int, str]]:
    """Последний останов без пуска: станок записан остановленным до конца смены.

    Приказ владельца от 29.09.2026: «если написана машина остановлена для
    нумерации челноков значит это простой машины, пуска не было». `_log_stop_windows
    такие окна НЕ отдаёт: там незакрытое окно отбрасывается намеренно (151 за
    14.09 — «11:15 стоп машина, чинка полотна», а дальше только растущий счётчик,
    то есть машина шла). Здесь же обратное проверяется по счётчику: пока он стоит
    на месте, остановки из переписки хватает, чтобы назвать хвост смены.

    Часов это НЕ добавляет: окно идёт в `_name_uncovered_log_windows`, где у
    строки потолок — уже посчитанный необъяснённый остаток смены.
    """
    hi = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
    states = _log_explicit_stop_states(section_text, own_machine)
    if not states:
        return []
    runs = [t for t, k, _s in _log_state_marks(section_text, own_machine)
            if k == "run"]
    last_run = max(runs) if runs else None
    tail = [t for t in states if last_run is None or t[0] >= last_run]
    if not tail:
        return []
    start, text = max(tail, key=lambda t: t[0])
    end = max([_log_line_time(l) or 0 for l in (section_text or "").splitlines()]
              + [start])
    end = min(max(end, start), hi)
    if end - start < 5 or not _log_counter_stopped(section_text, start):
        return []
    return [(start, end, text)]


# Слова, которыми мастер пишет ПОКАЗАНИЯ за смену, а не дело станка: «2 срез-731
# узлов- сч-304851», «Общ.ся-304851; срез.сч-731; подмена 2 из 2; навито 0 из
# 303». Приказ 29.09 разрешает брать из таких строк ВРЕМЯ (показания не
# двигаются — станок стоял), но называть их ПРИЧИНОЙ простоя нельзя.
_LOG_COUNTER_WORDS_RE = re.compile(
    r"\b(?:общ\w*|об|сч[а-яё]*|счет\w*|счёт\w*|срез\w*|узл\w*|подмен\w*"
    r"|навит\w*|развит\w*|лист\w*|мониторинг\w*|вес\w*|итог\w*|начал\w*"
    r"|конц\w*|конец|смен\w*|сред\w*|шт|кг|гр)\b", re.IGNORECASE)


def _log_is_counter_report(text: str) -> bool:
    """Строка со счётчиками и итогами среза: дела станка в ней не названо."""
    rest = re.sub(r"\d+", " ", str(text or "").lower())
    rest = _LOG_COUNTER_WORDS_RE.sub(" ", rest)
    return len(re.findall(r"[а-яё]{4,}", rest)) < 2


def _log_counter_freezes(section_text: str) -> List[Tuple[int, int]]:
    """Промежутки, где общий счётчик не вырос: в это время станок стоял.

    Приказ владельца от 29.09.2026 (дословно): «время брать можно по счётчикам
    если по времени отправки не решить или не написано время в сообщении».
    Доказательство — два показания одного числа: счётчик считает узлы, и пока
    он стоит на месте, машина ничего не выработала. Рост между показаниями
    значит обратное, поэтому такое окно времени не даёт.
    """
    lo = int(SHIFT_START_H * 60)
    hi = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
    pts = sorted((min(max(t, lo), hi), v)
                 for t, v in _log_counter_points(section_text))
    runs: List[Tuple[int, int]] = []
    k = 0
    while k < len(pts) - 1:
        if pts[k + 1][1] != pts[k][1]:
            k += 1
            continue
        j = k
        while j + 1 < len(pts) and pts[j + 1][1] == pts[k][1]:
            j += 1
        if pts[j][0] > pts[k][0]:
            runs.append((pts[k][0], pts[j][0]))
        k = j
    return runs


def _log_cause_time(section_text: str, cause: str) -> Optional[int]:
    """Минута сообщения, в котором мастер написал эту причину.

    Разбор пересказывает строку своими словами, поэтому ищем не подстроку, а
    совпадение слов (`_log_word_stems`): 60 % слов причины должны встретиться в
    строке переписки. Берём время ОТПРАВКИ строки — первый способ по приказу
    29.09; счётчик подключается только там, где им не решить.
    """
    stems = _log_word_stems(cause)
    if len(stems) < 2:
        return None
    best, best_score = None, 0.0
    for line in (section_text or "").splitlines():
        minute = _log_line_time(line)
        if minute is None:
            continue
        score = len(stems & _log_word_stems(line)) / float(len(stems))
        if score > best_score:
            best, best_score = minute, score
    return best if best_score >= 0.6 else None


# Как далеко показание счётчика может стоять ОТ причины, чтобы быть её
# доказательством: мастер пишет о деле, а следующее показание приходит в конце
# часа. Дальше этого окно принадлежит другой причине, не этой.
_LOG_COUNTER_ANCHOR_MIN = 90


def _name_untimed_causes_by_counters(r: ShiftMachineReport,
                                     section_text: str,
                                     own_machine,
                                     elsewhere_ivs: List[Tuple[int, int]] = (),
                                     untimed_naladka: Optional[Dict[str, bool]]
                                     = None) -> None:
    """Причина без времени получает минуты, по которым стоят счётчики.

    Приказ владельца от 29.09.2026: «время брать можно по счётчикам, если по
    времени отправки не решить или не написано время в сообщении». Прогон
    28.09.2026, ст.251: «12:09 На машине был убавлена подача помогающего вала…»
    — интервала нет ни в строке, ни в разметке разбора, и часы ушли в
    «причина не указана», хотя общий счётчик с 12:22 по 18:50 стоит на 304851:
    станок в это время не выработал ни узла.

    Часы станка правило НЕ двигает: строка берёт минуты у того же
    необъяснённого остатка, что и окна «стоп … пуск» (потолок — budget_min,
    минуты уже названных строк вычитаются). Два исключения, чтобы минуты не
    уехали дважды:

     • строка со счётчиками («2 срез-731 узлов- сч-304851») причиной не
       становится — из неё берут только время;
     • минуты строк, которые уже названы часами без интервала (уход оператора
       на другую машину: `elsewhere_ivs`), не забираем — они объяснены своими
       словами, и новая строка повторяла бы их.
    """
    if r.balance_unknown or r.engineering_all_shift or r.no_operator_all_shift:
        return
    if not r.untimed_stops:
        return
    freezes = [iv for iv in _log_counter_freezes(section_text)
               if iv[1] - iv[0] >= 5]
    if not freezes:
        return
    budget_min = int(round(max(0.0, MACHINE_SHIFT_HOURS - r.work_hours
                               - r.tech_stops_total
                               - r.lunch_in_downtime) * 60))
    if budget_min < 5:
        return
    taken = [(s.start_min, s.end_min) for s in r.tech_stops
             if s.start_min is not None and s.end_min is not None]
    taken += [tuple(iv) for iv in elsewhere_ivs or ()]
    if r.lunch_window:
        taken.append(tuple(r.lunch_window))
    taken = _merge_intervals(taken)
    left = budget_min
    for cause in list(r.untimed_stops):
        if _log_is_counter_report(cause):
            continue
        at = _log_cause_time(section_text, cause)
        if at is None:
            continue
        window = None
        for a, b in freezes:
            if a <= at <= b:
                window = (at, b)
                break
            if a > at and a - at <= _LOG_COUNTER_ANCHOR_MIN:
                window = (at, b)
                break
        if window is None:
            continue
        clean = _log_gap_reason(cause)
        is_naladka = bool((untimed_naladka or {}).get(cause,
                                                      _reason_is_naladka(clean)))
        named = False
        for x, y in _subtract_intervals([window], taken):
            if y - x < 5 or left < 5:
                continue
            y = min(y, x + left)
            left -= y - x
            taken = _merge_intervals(taken + [(x, y)])
            # Классификатор не знает всех слов мастера («убавлена подача
            # помогающего вала» → «прочее»), а приказ 29.09 требует причину по
            # его словам: безымянную категорию заменяем дословной фразой.
            label = None
            if not is_naladka and classify_stop(clean)[0] == OTHER_LABEL:
                cut = re.split(r"[,;.]", clean)[0].strip()
                if len(cut) > 60:
                    cut = cut[:57].rsplit(" ", 1)[0]
                label = cut or clean[:60]
            stop = TechStop(round((y - x) / 60.0, 2), clean,
                            operator_active=False, start_min=x, end_min=y,
                            is_naladka=is_naladka, label_override=label)
            r.tech_stops.append(stop)
            r.log_timed_stops.append(
                f"{_log_hm(x)}–{_log_hm(y)} {stop.label} — время посчитано по "
                f"счётчику: «{clean[:70]}»")
            named = True
        if named and cause in r.untimed_stops:
            # Причина больше не «без времени»: второй раз в отчёте её писать
            # нельзя, иначе один и тот же простой назван дважды.
            r.untimed_stops.remove(cause)


def _log_word_stems(text: str) -> set:
    return {w[:5] for w in re.findall(r"[а-яёa-z]{5,}", (text or "").lower())
            if w[:5] not in {"машин", "станок", "работ", "врем", "смен",
                             "общий", "счётч", "счетч", "конец", "начал"}}


def _log_window_at(windows: List[Tuple[int, int, str]], minute: int
                   ) -> Optional[Tuple[int, int, str]]:
    """Окно простоя, накрывающее минуту (границы включаем в своё окно)."""
    for s, e, t in windows:
        if s <= minute <= e and e > s:
            return (s, e, t)
    return None


def _log_match_window(windows: List[Tuple[int, int, str]],
                      reason: str) -> Optional[Tuple[int, int, str]]:
    """Окно, чей текст причины совпадает с формулировкой события.

    Нужно ДВА совпавших корня и единственный лучший вариант: «чинка» есть в
    половине окон смены, и брать по одному слову — значит угадывать.
    """
    stems = _log_word_stems(reason)
    if not stems:
        return None
    scored = sorted(((len(stems & _log_word_stems(t)), s, e, t)
                     for s, e, t in windows), key=lambda x: (-x[0], x[1]))
    if not scored or scored[0][0] < 2:
        return None
    if len(scored) > 1 and scored[0][0] == scored[1][0]:
        return None
    _, s, e, t = scored[0]
    return (s, e, t)


def _log_hm(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _log_event_is_stop(kind_early: str, reason: str) -> bool:
    """Простой ли это событие станка (по роду работы и словам причины).

    Kind «работа»/«подмена»/«навивка» — это НЕ простой, такие события окно
    «стоп → пуск» не трогает вовсе (правило 24.09.2026). Слова причины в
    проверке kinds участвовать не должны: «стоп машина на срез … подмена 5
    из 6» — это показание счётчика в тексте, а не работа (прогон 27.09.2026,
    ст.321: событие 17:20 из-за слова «подмена» осталось без конца).
    """
    return (not _LOG_WORK_KIND_RE.search(kind_early)
            and bool(_LOG_STOP_WORD_RE.search(kind_early)
                     or _LOG_STOP_STATE_RE.search(reason)))


def _log_state_times(windows: List[Tuple[int, int, str]], a_min: Optional[int],
                     b_min: Optional[int], kind_early: str, reason: str,
                     end_chained: bool, has_hours: bool = False,
                     cap_end: Optional[int] = None
                     ) -> Tuple[Optional[int], Optional[int], str]:
    """Достроить границы простоя по парам «стоп → пуск» из переписки.

    Возвращает (начало, конец, пояснение) — пояснение пустое, если ничего не
    добавилось. Три случая, где время в логе ЕСТЬ, но в одной строке не написано:

      • «11:20 стоп машина, чинка» → «11:48 пуск машина»: событие с началом без
        конца получает конец от пуска;
      • событие с концом без начала («18:33 пуск» и строка «чинка 5 пропусков»
        без времени) — начало берётся со «стопа» того же простоя;
      • `_chain_half_intervals` дотянул конец до начала соседней записи, а
        мастер пишет «пуск» позже: станок в это время стоял, поэтому конец
        берём у пуска, а часы код пересчитывает.

    Событие, которое пришлось на минуты РАБОТАЮЩЕЙ машины, остаётся без
    времени: станок в это время не стоял, и приписывать ему простой нельзя.

    cap_end — начало СЛЕДУЮЩЕЙ названной остановки (13:33 «стоп машина, обрыв
    нити»). Хвост окна принадлежит ей, а не этой строке, поэтому пуском окно
    закрываем не дальше cap_end. Прогон 25.09.2026, ст.251: станок стоял с
    11:29 («брак нити, замена катушек») и мастер писал «13:08 чинка»,
    «13:33 стоп машина, обрыв нити», «13:39 … машина в работе» — без cap_end
    «чинка» съедала 6 минут обрыва, и в отчёте пропадала названная причина.
    Ровно так же «срез» 17:20 у ст.321 остаётся при своих минутах: следующая
    остановка названа в 17:30 («в стопе замена 5 сошедших катушек»), и все 73
    мин до пуска 18:33 забирает она.

    Часам, которые модель назвала явным числом (has_hours), границы не трогаем:
    менять их по окну — значит переписать слова мастера.
    """
    if not windows:
        return a_min, b_min, ""
    if not _log_event_is_stop(kind_early, reason):
        return a_min, b_min, ""
    label = (reason or kind_early or "").strip()[:60]

    def _hit(win: Tuple[int, int, str], na: int, nb: int, verb: str) -> str:
        return (f"{_log_hm(na)}–{_log_hm(nb)} {label} — {verb} из переписки: "
                f"«{win[2][:70]}»")

    def _closed(win: Tuple[int, int, str]) -> Optional[int]:
        """Конец окна, обрезанный следующей названной остановкой."""
        end = min(win[1], cap_end) if cap_end is not None else win[1]
        return end if end > a_min else None

    if a_min is not None and b_min is None:
        win = _log_window_at(windows, a_min)
        end = _closed(win) if win else None
        if end is not None:
            return a_min, end, _hit(win, a_min, end, "конец")
        return a_min, b_min, ""
    if a_min is None and b_min is not None:
        win = _log_window_at(windows, b_min)
        if win and win[0] < b_min:
            return win[0], b_min, _hit(win, win[0], b_min, "начало")
        return a_min, b_min, ""
    if a_min is None and b_min is None:
        win = _log_match_window(windows, reason)
        if win:
            return win[0], win[1], _hit(win, win[0], win[1], "обе границы")
        return a_min, b_min, ""
    if end_chained and not has_hours:
        # Конец достроен соседним событием, а не словами мастера. Если обе
        # границы лежат внутри одного простоя, а пуск был позже — доводим его до
        # пуска (станок физически стоял), но не дальше следующей остановки.
        win = _log_window_at(windows, a_min)
        end = _closed(win) if win else None
        if (win and end is not None and end > b_min
                and _log_window_at(windows, b_min)):
            return a_min, end, _hit(win, a_min, end, "конец")
    return a_min, b_min, ""


def _horizon_stop_from_topic(machine: dict, r: ShiftMachineReport) -> None:
    """Станок, про который в теме написано только «машина (в стопе до даты)».

    Прогон 27.09.2026, ст.15тр: единственное сообщение темы — заголовок
    «15т машина(в стопе до 15.10.2026 г.) - информация за смену 27.09.2026г.».
    Модель вернула по такому станку пустой разбор (ни событий, ни счётчиков), и
    в бланке получалось две пустые клетки Q/R при том, что станок стоял всю
    смену. На ст.14тр в той же теме написано ещё и «инж. служба», событие
    model посчитала — поэтому там 11,25 ч были.

    Основание — слово мастера, а не догадка: фразу «в стопе до <дата>» читаем из
    переписки СТАНКА (section_text кладёт day_pipeline) и закрываем ею смену
    станка. Службу не приписываем: в 15тр её нет, а выдуманная «инженерная
    служба» — это уже цифра без основания.
    """
    if r.tech_stops or r.attracted or r.untimed_stops or r.lines:
        return
    if (r.operator or "").strip():
        return
    for line in (machine.get("section_text") or "").splitlines():
        m = _TOPIC_HORIZON_RE.search(line)
        if not m:
            continue
        phrase = re.sub(r"\s+", " ",
                        m.group(1).replace("(", " ").replace(")", " "))
        phrase = phrase.strip(" .,")
        r.tech_stops.append(TechStop(MACHINE_SHIFT_HOURS, phrase,
                                     operator_active=False,
                                     start_min=int(SHIFT_START_H * 60),
                                     end_min=int((SHIFT_START_H
                                                  + MACHINE_SHIFT_HOURS) * 60)))
        r.warnings.append(
            f"часы простоя взяты из заголовка темы: «{phrase}» — по станку нет "
            f"ни счётчика, ни событий, смена закрыта его же словами")
        return


MEDIA_MARK_RE = re.compile(r"\[медиа\]", re.IGNORECASE)


def _log_gap_reason(text: str) -> str:
    """Слова мастера об остановке — чистые, без разметки выгрузки.

    Окно из переписки несёт в себе и показание счётчика («Об. Сч.: 234542 Ср.
    Сч.: 2887 из 2700»), и метку вложений: в строке отчёта это читается как
    мусор, а классификатор причины по такому хвосту может выбрать не то слово.
    """
    t = MEDIA_MARK_RE.sub(" ", text or "")
    t = re.sub(r"[*_`]+", " ", t)
    t = re.sub(r"\s+", " ", t)
    return t.strip(" .,:;-")[:120]


def _name_winding_on_submen_state(r: ShiftMachineReport, section_text: str,
                                  own_machine) -> None:
    """Навивка шпуль в минуты «машина на подмене» — простой станка.

    Приказ владельца от 29.09.2026 по ст.111 за 28.09 (дословно): «нет-это не
    отсутвие заказа. по 111 машине же написны останоки по оператору и это типо
    было время навивки шпуль. Там тоже в начала смены писалось что машина на
    подмене. Если машина на подмене и оператор пишет навивку шпуль в это же
    время что и подмена то машина в стопе».

    Правило 24.09 («навивка без слова «стоп» — не простой станка») остаётся в
    силе там, где станок мотает полотно: здесь состояние машины названо её же
    строкой переписки, а 7,18 ч смены висели в отчёте «причина не указана».

    Часы оператора при этом НЕ двигаются: шпули он в эти минуты действительно
    навивал (приказ 28.09 — часы не добивать и не обрезать), и запись остаётся
    его работой. Берём только целые записи навивки, легшие в окно состояния, и
    только те минуты, которых станку не хватает до 12 ч: навивка не должна
    съедать работу, которую считает счётчик.
    """
    if (r.balance_unknown or r.engineering_all_shift
            or r.no_operator_all_shift):
        return
    windows = _submen_state_windows(section_text, own_machine)
    if not windows:
        return
    marks = [(t, seg) for t, k, seg in _log_state_marks(section_text, own_machine)
             if k == "submen"]
    budget_min = int(round(max(
        0.0, (MACHINE_SHIFT_HOURS - r.work_hours - r.tech_stops_total
              - r.lunch_in_downtime) * 60)))
    if budget_min < 5:
        return
    left = budget_min
    taken: List[Tuple[int, int]] = []
    for i, s in enumerate(r.tech_stops):
        if (not s.is_parallel or s.shiftlong_parallel or s.elsewhere
                or s.transferred or s.stop_label != WINDING_LABEL):
            continue
        ivs = s.windows_min
        if not ivs:
            continue
        if _union_hours(_subtract_intervals(ivs, windows)) * 60 >= 5:
            continue     # запись целиком не лежит в состоянии — не трогаем
        covered = [(max(a, c), min(b, d))
                   for a, b in ivs for c, d in windows if min(b, d) > max(a, c)]
        added = round((_union_hours(taken + covered)
                       - _union_hours(taken)) * 60)
        if added < 5 or added > left:
            continue
        taken.extend(covered)
        left -= added
        r.tech_stops[i] = replace(s, on_submen_state=True)
        start, stop = s.start_min, s.end_min
        # Цитируем последнее состояние ДО начала записи: утренняя сводка
        # («Состояние машины и полотна: Машина на подмене», 06:40) стоит в теме
        # раньше строки оператора, а мастеру в отчёте нужнее её слова.
        prior = [seg for t, seg in sorted(marks) if t <= start]
        r.log_timed_stops.append(
            f"{_log_hm(start)}–{_log_hm(stop)} {WINDING_LABEL} — станок назван "
            f"на подмене: «{_log_gap_reason(prior[-1] if prior else '')[:70]}»")


def _name_uncovered_log_windows(r: ShiftMachineReport,
                                log_windows: List[Tuple[int, int, str]],
                                section_text: str, own_machine) -> None:
    """Непокрытое окно «стоп … пуск» — отдельной названной строкой простоя.

    Приказ владельца от 29.09.2026 (дословно): «когда пишется какая операция
    которая подразумеват остановку машины и другое сообщение подразумевает пуск
    машины то вычитать нужно из конечного времени началное и это и есть врмя
    затраченное на работу». До этого окно работало только как ДОПОЛНЕНИЕ:
    _log_state_times достраивает границы той записи разбора, которую модель уже
    назвала. Если под окном модель не вернула ничего, окно пропадало, и его
    минуты доставались безымянному остатку смены. Прогон 28.09.2026, ст.251:
    «09:47 Останов машины. Чинка. Обрыв и бракованная нить» → «10:00 чинка
    завершена» (10 мин) и «10:58 Чинка два обрыва. Стоп машина» → «11:06»
    (8 мин) стояли в отчёте внутри «причина не указана», хотя причину мастер
    написал словами. Прогон 25.09.2026, ст.251: окно 07:14–07:25 «Машина в
    наладке» и 12:50–13:08 «12:48 Идёт наладка» (34 мин) были то же самое —
    приказ 29.09 прямо называет их наладкой.

    Часы станка правило НЕ двигает: остаток считается как 12 − работа −
    названные простои − обед (см. operator_absence_hours), поэтому новая строка
    отнимает минуты у того же необъяснённого остатка. Отсюда потолок (budget):
    называть можно только то, что ещё не объяснено, иначе станок
    «переработает» 12 ч.

    Причину строки пишет сообщение ВНУТРИ свободного куска, а не всё окно: у
    окна 16:29–19:00 на ст.111 за 26.09 первая фраза — «Стоп на подмену. Сошла
    шпуля √7», а свободен как раз хвост 16:58–19:00, где мастер написал «стоп
    навивка. Перешла в работу на 151 машину». Взять начало окна — значит
    перевести уход оператора в «подстановку шпуль».

    Минуты, которые уже объяснены словами мастера в записи БЕЗ времени (уход
    на другую машину, «замена шпулярника в теч.смены»), второй раз не называем:
    строка с часами, но без интервала не видна в покрытии минут, и окно
    залезло бы в те же часы дважды.
    """
    if r.balance_unknown:
        return
    log_windows = list(log_windows or []) + _log_open_stop_tail(section_text,
                                                                own_machine)
    if not log_windows:
        return
    if r.engineering_all_shift or r.no_operator_all_shift:
        return
    budget_min = int(round(max(0.0, MACHINE_SHIFT_HOURS - r.work_hours
                               - r.tech_stops_total
                               - r.lunch_in_downtime) * 60))
    if budget_min < 5:
        return
    taken = [(s.start_min, s.end_min) for s in r.tech_stops
             if s.start_min is not None and s.end_min is not None]
    if r.lunch_window:
        taken.append(tuple(r.lunch_window))
    taken = _merge_intervals(taken)
    # Фразы мастера о простоях, которые уже стоят в отчёте без времени.
    worded = [_log_word_stems(s.reason) for s in r.tech_stops + r.attracted
              if s.start_min is None and (s.reason or "").strip()]
    worded = [w for w in worded if w]
    marks = [m for m in _log_state_marks(section_text, own_machine)
             if m[1] == "stop"]
    left = budget_min
    for a, b, reason in sorted(log_windows):
        for x, y in _subtract_intervals([(a, b)], taken):
            if y - x < 5 or left < 5:
                continue
            y = min(y, x + left)
            inner = [t for mm, _k, t in marks if x <= mm < y]
            clean = _log_gap_reason("; ".join(inner) if inner else reason)
            if worded and len(_log_word_stems(clean) & set().union(*worded)) >= 2:
                continue        # эти минуты мастер уже назвал другой строкой
            left -= y - x
            # operator_active=False — как у остатка, из которого взяты минуты:
            # мастер писал строку у станка, но доказательств этого в переписке
            # нет, а часы оператора приписывать по догадке нельзя (приказ 28.09:
            # «не добивать и не обрезать»).
            stop = TechStop(round((y - x) / 60.0, 2), clean,
                            operator_active=False, start_min=x, end_min=y,
                            is_naladka=_reason_is_naladka(clean))
            r.tech_stops.append(stop)
            r.log_timed_stops.append(
                f"{_log_hm(x)}–{_log_hm(y)} {stop.label} — названо из переписки: "
                f"«{clean[:70]}»")


def _events_to_stops_and_subs(machine: dict, r: ShiftMachineReport) -> None:
    """Из событий с временем вывести подмены и тех.остановки.

    Событие: {start, end, kind, reason, performer, hours, other_machine}.
    kind «подмена» → в подмены; «отсутствие»/«остановка»/«наладка»/«простой»/
    «чинка» → тех.остановки; «обед»/«перерыв» пропускаем, но помечаем, что
    обед уже учтён отдельным интервалом. Часы = явные hours либо
    (end − start), чтобы арифметику делал код, а не модель.
    """
    events = machine.get("events")
    if not isinstance(events, list):
        return
    subs_h, subs_n, fios = 0.0, 0, []
    # Минуты уходов на другую машину (строка без интервала, но с часами) и
    # слова мастера о причинах без времени — нужны правилу 29.09 про счётчик
    # (см. _name_untimed_causes_by_counters).
    elsewhere_ivs: List[Tuple[int, int]] = []
    untimed_naladka: Dict[str, bool] = {}
    # ШЛА ЛИ машина. Единственное доказательство — счётчик (см. work_hours).
    # Он нужен здесь, чтобы нераспознанную причину (см. machine_stopped_for)
    # решать по правилу 25.09.2026 только там, где параллельной работе есть
    # чем объясниться: на станке, который по счётчику не выработал ни узла,
    # «операция при работающей машине» невозможна физически.
    machine_was_running = r.work_hours > 0.01
    # Влезает ли работа станка в смену. Счётчик иногда даёт больше 12 ч
    # (прогон 21.09.2026, ст.98: 20,6 ч) — это бракованные показания, и
    # строить на них ещё и 12-часовую фоновую запись нельзя: часы оператора
    # уезжают за 20 ч вместо честного «время не указано».
    machine_work_in_shift = r.work_hours <= MACHINE_SHIFT_HOURS + TOLERANCE_H
    # Окна простоя по строкам состояния станка (см. _log_stop_windows).
    log_windows = _log_stop_windows(machine.get("section_text") or "",
                                    machine.get("machine"))
    # Начала названных остановок — граница, дальше которой окно этого события
    # не доходит: хвост принадлежит следующей причине (см. _log_state_times).
    stop_starts = sorted({m for ev in events if isinstance(ev, dict)
                          for m in [_time_to_min(ev.get("start"))]
                          if m is not None and _log_event_is_stop(
                              (ev.get("kind") or "").lower(),
                              ev.get("reason") or ev.get("label")
                              or ev.get("text") or "")})
    for ev in events:
        if not isinstance(ev, dict):
            continue
        hours = _to_float(ev.get("hours"))
        # Часы назвал код, а не мастер: их обязан пересчитать и достроенный
        # интервал «стоп → пуск».
        hours_derived = hours is None
        a_min, b_min = _time_to_min(ev.get("start")), _time_to_min(ev.get("end"))
        if hours_derived:
            if a_min is not None and b_min is not None and b_min >= a_min:
                hours = (b_min - a_min) / 60.0
        kind_early = (ev.get("kind") or "").lower()
        reason = (ev.get("reason") or ev.get("label") or ev.get("text") or "")
        # Второй проход: время простоя, которое мастер написал парой сообщений
        # «стоп» … «пуск», а не интервалом в одной строке.
        a_min, b_min, log_note = _log_state_times(
            log_windows, a_min, b_min, kind_early, reason,
            bool(ev.get("_end_chained")), not hours_derived,
            next((x for x in stop_starts
                  if a_min is not None and x > a_min), None))
        if log_note:
            r.log_timed_stops.append(log_note)
            if hours_derived and a_min is not None and b_min is not None:
                hours = (b_min - a_min) / 60.0
        # Фамилия службы наладки обязана быть сказано словами мастера (задача
        # 62). Прогон 25.09.2026, ст.251: запись «машина в наладке» 07:48–08:13
        # ушла с performer «Рыбин» — при том что в теме 251 его нет, а вообще за
        # день фамилия встречается ОДИН раз: в списке участников совещания
        # 08.09 («в составе: Перов, Скрипачев, Рыбин, Каленюк, Черныш»), которое
        # мастер выложил в тему 14тр. Отчёт показал человека, который у этого
        # станка не был.
        #
        # Правило ВЗЯТО УЗКО — только записи службы (kind «наладка» или работа
        # наладки в причине), и вот почему: сухой прогон по всем восьми датам
        # (правило на ВСЕ исполнители) снимал имена там, где они настоящие, но
        # написаны в теме соседнего станка — 14.09 ст.321 терял Арташину
        # (0,27+0,33+0,08 ч, и в эталоне пользователя она названа прямо), 16.09
        # ст.251 — «Вашурина Р.» на подмене, 21.09 ст.321 — Петровского и
        # Неделькина, 24.09 ст.121 — Абдулаева. Это задача 53 (темы путаются), а
        # не выдумка модели, и лечить её надо там.
        #
        # ИМЯ при этом остаётся в поле performer: по нему работают фильтр
        # зеркальных пересказов (_is_mirrored_arrival) и разбивка «свои часы /
        # привлечённый» (operator_stops, attracted_own). Обнуление имени на
        # 25.09 убило фильтр и вернуло пересказ «Петровский ушёл на 251» назад:
        # станок получил ложное «отсутствие оператора (работа на №321)», а на 321
        # уехала выдуманная «Гудкова». В отчёт непроверенное имя выходит ролью
        # (см. attracted_all), а часы всегда остаются станку.
        who_ev = (ev.get("performer") or "").strip()
        service_ev = "наладк" in kind_early or _reason_is_naladka(reason)
        claimed = who_ev if (
                service_ev
                and who_ev
                and not _same_person_name(who_ev, r.operator)
                and not _same_person_name(who_ev, r.operator2)
                and not _name_backed_by(who_ev, reason)
                and not _name_backed_by(who_ev,
                                        machine.get("section_text"))
                ) else ""
        # Завершающая запись («заполнение журнала и чата») — запоминаем её
        # конец как реальное время ухода человека.
        if b_min is not None and _CLOSING_RE.search(reason):
            if (r.closing_activity_end is None
                    or b_min > r.closing_activity_end):
                r.closing_activity_end = b_min
        if "обед" in kind_early or "перерыв" in kind_early:
            # Обед — фиксированные 45 мин и он уже стоит в простое станка
            # отдельной строкой (lunch_in_downtime). Ветка «нет времени» ниже
            # иначе добавляла слово «Обед» в untimed_stops, и в отчёте
            # появлялась строка «время не указано у причин: …, обед» — те же
            # 0,75 ч второй раз (прогон 10.09.2026, ст.151).
            r.lunch_recorded = True
            # ПЛАВАЮЩИЙ ОБЕД: если мастер написал, что станок на время
            # перерыва приняли / не останавливали, машина не стояла — строки
            # «простой обед» быть не должно. Прогон 16.09.2026: ст.321
            # «обеденный перерыв Демидова Е. с 11:00 до 11:45, передал навивку
            # шпулей Петровскому О.», ст.151 «…Демидов Е. принимает №151».
            # В эталоне пользователя у этих станков строки обеда нет.
            if (ev.get("machine_kept_running")
                    or _LUNCH_HANDOVER_RE.search(reason or "")
                    or _LUNCH_HANDOVER_RE2.search(reason or "")
                    # Передачу писали ОТДЕЛЬНЫМ сообщением, в причине события
                    # её может не быть вовсе — смотрим весь раздел станка.
                    or _lunch_covered_in_text(
                        machine.get("section_text") or "")):
                r.lunch_handed_over = True
            # ОКНО ОБЕДА ОБЯЗАТЕЛЬНО запоминаем и здесь. Раньше этот ранний
            # continue уходил до присвоения lunch_window, и обед не вырезался
            # из часов оператора: прогон 15.09.2026, ст.321 — Демидов получил
            # 9,33 ч вместо 8,58 (45 мин обеда остались внутри его навивки),
            # а в эталоне пользователя 8,25 ч.
            #
            # ПЛАВАЮЩИЙ ОБЕД (16.09.2026): операторы обедают в РАЗНОЕ время и
            # на это время передают станки друг другу, поэтому в одном разделе
            # бывает НЕСКОЛЬКО окон обеда — чужие и своё. В окно станка берём
            # обед ЕГО ОПЕРАТОРА: из чужого окна нельзя вычитать 45 мин у
            # своего человека. Прогон 16.09, ст.151 (оператор Петровский):
            # первым шло событие «обеденный перерыв Демидова Е. 11:00–11:45»,
            # код брал его, и у Петровского обед вырезался не в то время,
            # хотя его собственный перерыв — 11:45–12:30.
            if a_min is not None and b_min is not None and b_min > a_min:
                perf = (ev.get("performer") or "").strip().lower()
                mine = bool(perf) and _same_person_name(
                    perf, (r.operator or "").strip())
                if r.lunch_window is None or (mine and not r.lunch_window_mine):
                    r.lunch_window = (a_min, b_min)
                    r.lunch_window_mine = mine
            continue
        if (not hours and a_min is None and b_min is None
                and "работа" not in kind_early
                and machine_work_in_shift
                and _WHOLE_SHIFT_RE.search(reason or "")):
            # «в течении всей смены» — это и есть названное время, весь рабочий
            # день. Терять часы нельзя: без окна запись уезжала в «причины без
            # времени», остаток смены висел необъяснённым, и файл одновременно
            # печатал «2,78 простой — время не указано у причин: замена
            # шпулярника…» и «!!! РАСХОЖДЕНИЕ: станок −2,78 ч до 12 ч» (прогон
            # 24.09.2026 со второго раза, ст.91). Дальше физикой занимается
            # _parallelize_shiftlong_swaps: фон на всю смену и работа по
            # счётчику в 12 ч не влезают, поэтому такая строка остаётся
            # параллельной работой, а не простоем.
            a_min = int(SHIFT_START_H * 60)
            b_min = int((SHIFT_START_H + MACHINE_SHIFT_HOURS) * 60)
            hours = MACHINE_SHIFT_HOURS
        if not hours:
            # Причина есть, а времени нет — сохраняем текстом, чтобы простой
            # не исчез из отчёта (иначе «недостаток времени» без объяснения).
            reason_only = (ev.get("reason") or ev.get("label") or ev.get("text")
                           or "")
            if (reason_only.strip()
                    and not _log_is_restart_only(reason_only.strip())):
                r.untimed_stops.append(reason_only.strip())
                untimed_naladka[reason_only.strip()] = (
                    "наладк" in kind_early
                    or _reason_is_naladka(reason_only))
            # Названный человек без времени — строка привлечённого с НУЛЁМ часов.
            # Так у пользователя в эталоне 01.09 (ст.111: «Петровский 0 — время
            # не уточнено»). Раньше человек просто терялся, и модель начинала
            # выдумывать ему интервал (ст.121: «наладчики Пронкин и Шишкин» без
            # времени превратились в 3,5 + 3,5 ч).
            perf_only = (ev.get("performer") or "").strip()
            if perf_only and perf_only.lower() != (r.operator or "").lower():
                r.attracted.append(TechStop(
                    0.0,
                    (reason_only.strip() or "работа") + " (время не уточнено)",
                    operator_active=False, performer=perf_only,
                    performer_claimed=claimed,
                    is_naladka=("наладк" in (ev.get("kind") or "").lower()
                                or _reason_is_naladka(reason_only))))
            elif reason_only.strip():
                # Операция самого оператора без времени: в часы не поставить, но
                # в расшифровке его работы она обязана быть названа (правило
                # пользователя 03.09.2026).
                r.untimed_own.append(reason_only.strip())
            continue
        kind = (ev.get("kind") or "").lower()
        # Слово мастера о том, чем было окно: основание колонки «подмены, ч».
        submen_kind = "подмен" in kind
        reason = (ev.get("reason") or ev.get("label") or ev.get("text")
                  or kind or "")
        if "обед" in kind or "перерыв" in kind:
            # Обед записан отдельным интервалом — значит, в часах оператора
            # его уже нет и второй раз вычитать нельзя.
            r.lunch_recorded = True
            if (r.lunch_window is None and a_min is not None
                    and b_min is not None and b_min > a_min):
                r.lunch_window = (a_min, b_min)
            continue
        other = _validated_other_machine(ev.get("other_machine"), reason,
                                         r.machine)
        # other_machine означает «НАШ ОПЕРАТОР ушёл на другой станок». Если у
        # события назван ДРУГОЙ исполнитель, оно описывает работу того человека
        # на ЭТОМ станке, а номер — ОТКУДА он пришёл, а не куда ушёл наш.
        # Прогон 16.09.2026, ст.321: модель вернула {kind «навивка», performer
        # «Петровский», other_machine «151», 11:00–11:45, reason «принял 321 на
        # время обеда Демидова Е.»} — Петровский пришёл СО 151-й, Демидов никуда
        # не уходил. Код же сделал из этого «отсутствие оператора (работа на
        # №151, часы посчитаны там)» 4,98 ч и вписал Демидову 0,75 ч чужой
        # навивки. В эталоне пользователя такого отсутствия нет.
        ev_performer = (ev.get("performer") or "").strip()
        if other and ev_performer and not _same_person_name(
                ev_performer, (r.operator or "").strip()):
            other = None
        if other:
            # Оператор ушёл работать на другой станок: для этого станка это
            # простой, а его часы принадлежат тому станку. Исполнителя (кто
            # ушёл) запоминаем — он станет привлечённым персоналом того станка.
            # Отличаем ДВА случая:
            #  • kind «отсутствие» — оператор ВСЮ смену на другом станке, где он
            #    штатный оператор. Здесь это чистое отсутствие, его часы туда
            #    НЕ прибавляем как «работу на этом станке» (full_absence=True).
            #  • иначе (навивка/подмена) — краткий уход на подмену: это его
            #    реально отработанные часы, идут в его время (full_absence=False).
            full_abs = "отсутств" in kind
            r.tech_stops.append(TechStop(round(hours, 2), reason,
                                         other_machine=str(other),
                                         performer=ev.get("performer"),
                                         performer_claimed=claimed,
                                         full_absence=full_abs))
            if a_min is not None and b_min is not None and b_min > a_min:
                # Строка без интервала, но свои минуты у неё есть: часы уже
                # объяснены, и забирать их у неё нельзя.
                elsewhere_ivs.append((a_min, b_min))
        elif (is_real_submen(reason) and not _WHOLE_SHIFT_RE.search(reason)
                and ("подмен" in kind or creel_change_now(reason))):
            # Правило (26.08.2026, отмена прежнего правила 8): подмена на
            # СВОЁМ станке — станок СТОИТ, причина простоя «подмена». Часы
            # одновременно идут в рабочее время того, кто подменял. Поэтому
            # это обычный простой (machine_stopped=True, operator_active=True),
            # а не «работа станка», как было раньше.
            #
            # Различает подмену по словам мастера, а не по метке модели: со
            # второго прогона 24.09 та же запись ст.321 «13:03 Меняю на
            # шпулярнике с малым количеством шнура для подвивки шпулей» вернулась
            # с kind «работа», и 0,35 ч пропали и из колонки «подмены, ч», и из
            # расшифровки — станок по документу в это время не стоял, хотя
            # мастер менял шпулярник. По kind «работа» поэтому требуется глагол
            # самой замены (creel_change_now), иначе уборка «после замены
            # шпулярника» с 22.09 стала бы простоем станка.
            #
            # Приказ владельца 30.09.2026: «строку мастера считай подменой,
            # заменой одной катушки это не подмена». Окно остаётся простоем
            # станка (его часы — в технических остановках), но подменой человека
            # оно бывает только когда мастер сам назвал его подменой И не писал
            # про единицу сырья. Прогон 29.09.2026, ст.321: 56 окон «Замена N
            # бобины» дали 56 подмен при том, что мастер писал «Подмена - 5 из
            # 6», а в его файле у станка пустые и «подмены, ч», и «фио на
            # подменах».
            person_submen = submen_kind and not is_material_swap(reason)
            r.tech_stops.append(TechStop(round(hours, 2),
                                         reason or "подмена",
                                         operator_active=True,
                                         performer=ev.get("performer"),
                                         performer_claimed=claimed,
                                         is_sub=person_submen,
                                         submen_recorded=submen_kind,
                                         start_min=a_min, end_min=b_min))
            if person_submen:
                subs_n += 1
                # Часы подмен обязаны копиться: без этой строки subs_hours всегда
                # оставался 0, и Excel/1С печатали «Подмены: 2» без часов
                # (прогон 09.09.2026: у ст.98 «подмены_часы: 0» при одной подмене
                # 10:00–10:50).
                subs_h += hours
                if ev.get("performer"):
                    fios.append(_unproven_role(False) if claimed
                                else ev["performer"])
        elif "работа" in kind:
            # Работа станка считается по счётчику — интервалы работы не нужны.
            # НО: если у события назван ИСПОЛНИТЕЛЬ и это не оператор станка,
            # событие описывает работу ДРУГОГО ЧЕЛОВЕКА (стажёр, наладчик,
            # подменный). Его часы обязаны попасть в привлекаемый персонал.
            # Прогон 10.09.2026, ст.251: модель честно вернула стажёра
            # («работа стажёра … 16:00 работа стажёра окончена (8,5 часов)»,
            # performer «Демидов», 07:00–16:00) — а код выбросил событие, и
            # блок «Работа привлекаемого персонала всего» остался 0 ч.
            perf = (ev.get("performer") or "").strip()
            if perf and not _same_person_name(perf, (r.operator or "").strip()):
                r.attracted.append(TechStop(
                    round(hours, 2), reason, operator_active=False,
                    performer=perf, performer_claimed=claimed,
                    start_min=a_min, end_min=b_min,
                    is_naladka=_reason_is_naladka(reason)))
            elif hours > 0.01:
                # РАБОТА СВОЕГО ОПЕРАТОРА — ЭТО ЕГО ЧАСЫ, а не «ничего».
                # Работа станка считается по счётчику, но у человека в это
                # время есть конкретное дело, и мастер его назвал: «приём
                # сырья за шпульный стол», «подготовка машины к подмене»,
                # «перестановка телег, сбор отходов», «заполнение журнала и
                # чата», «культура производства», «взвешивание нити».
                #
                # Раньше такие события выбрасывались целиком (ветка просто
                # делала continue), и часы оператора восстанавливал филлер
                # «контроль за работой машины» — итог сходился, но строки были
                # без деталей. На станке с НУЛЕВЫМ выпуском филлер не работает
                # (правило zero_output_all_shift), и операции терялись совсем.
                # Прогон 16.09.2026, ст.321: у Демидова пропали 1,53 ч явных
                # дел (0,42 приём сырья и подготовка + 0,33 перестановка телег
                # + 0,25 журнал + 0,18 работа с наладчиком + 0,40 машина на
                # подмену), бот выдал 6,76 ч вместо эталонных 8,58.
                # Проверено по всем накопленным дням: таких событий 69.
                #
                # Станок при этом РАБОТАЕТ (kind «работа»), поэтому операция
                # параллельная: machine_stopped=False, by_operator=True. Одно
                # исключение — в той же записи названа намотка на вал (правило
                # 28.09.2026): станок от этого встал, что бы модель ни вернула
                # в kind.
                r.tech_stops.append(TechStop(
                    round(hours, 2), reason, performer=perf or r.operator,
                    is_parallel=not is_shaft_wrap(reason), operator_active=True,
                    start_min=a_min, end_min=b_min,
                    is_naladka=_reason_is_naladka(reason)))
            continue
        else:
            # Часы службы наладки не должны попадать в работу оператора: если
            # в причине назван наладчик («машину остановил наладчик Пронкин»),
            # а модель не заполнила performer — берём фамилию из текста и
            # помечаем событие наладкой (прогон 01.09, ст.251).
            is_naladka = "наладк" in kind or _reason_is_naladka(reason)
            performer = ev.get("performer")
            if is_naladka and not (performer or "").strip():
                performer = _naladchik_from_reason(reason)
                if not (performer or "").strip() \
                        and not _is_service_request(reason):
                    # Фамилии в записи нет, но служба работала: «служба наладки
                    # вытащила шнур, который ушёл за вал», «зашли верёвки за вал
                    # (на двух); исправлено, передано оператору». В эталоне
                    # пользователя такая строка есть БЕЗ фамилии — прогон
                    # 14.09.2026, ст.321: «Работа привлекаемого персонала всего
                    # 1,55: 0,68 Арташина …; 0,87 наладчик — наладка».
                    # Раньше событие оставалось без performer и в привлечённый
                    # персонал не попадало вовсе: 0,87 ч службы терялись.
                    performer = "наладчик"
            # kind «отсутствие»/«простой» — ЧЕЛОВЕКА У СТАНКА НЕ БЫЛО, его часы
            # в работу оператора не идут, даже если reason звучит нейтрально.
            # Прогон 15.09.2026, ст.321: модель вернула {kind «отсутствие»,
            # performer «Демидов», 16:20–19:00, reason «конец смены оператора»},
            # а classify_stop не знает выражения «конец смены» и дал «прочее» с
            # operator_active=True → Демидову начислили 2,67 ч, которых он не
            # работал (он ушёл в 16:20). В эталоне пользователя эти часы стоят
            # в простое станка строкой «простой отсутствие оператора».
            is_absence_kind = "отсутств" in kind or "простой" in kind
            low_reason = (reason or "").lower()
            # Модель назвала род работы явно: kind «навивка» = намотка запаса
            # шпулей, чем занимаются ПОКА МАШИНА ИДЁТ.
            winding_kind = ("навивк" in kind or "намотк" in kind
                            or "развивк" in kind or "развит" in kind
                            or "навит" in kind)
            # Правило участка (25.09.2026, ст.98 за 24.09): «развито и навито
            # 110 шп» без слова про останов — НЕ простой. Без этого три таких
            # записи поставили станок в стоп на 10,33 ч, хотя счётчик дал
            # 10,28 ч работы: баланс 22,28 ч при 12-часовой смене.
            winding_free = (winding_kind
                            and not is_absence_kind and not is_naladka
                            and not _REPAIR_RE.search(low_reason)
                            and not is_shaft_wrap(low_reason)
                            and not any(m in low_reason for m in _STOP_TEXT_MARKERS))
            # Навивка на СВОЕЙ машине, а чужой станок в записи упомянут только
            # как законченное дело, — станок не стоял (см. _work_at_own_machine).
            own_work = (winding_kind
                        and not is_absence_kind
                        and not _REPAIR_RE.search(low_reason)
                        and not is_shaft_wrap(low_reason)
                        and _work_at_own_machine(reason, r.machine))
            # Ярлык «прочее» = классификатор не узнал операцию по тексту. Если
            # модель при этом назвала её навивкой, в отчёте обязана стоять
            # навивка, а не безликая «прочее».
            winding_label = (WINDING_LABEL if winding_free
                             and classify_stop(reason)[0] == OTHER_LABEL
                             else None)
            if is_absence_kind and "отсутств" in kind:
                winding_label = "отсутствие оператора"
            r.tech_stops.append(TechStop(
                round(hours, 2), reason,
                operator_active=False if is_absence_kind else None,
                performer=performer,
                performer_claimed=claimed,
                is_naladka=is_naladka,
                submen_recorded=submen_kind,
                start_min=a_min, end_min=b_min,
                is_parallel=True if (winding_free or own_work) else False,
                label_override=winding_label,
                machine_label=_service_stop_label(reason),
                unknown_is_stop=not machine_was_running,
                hours_estimated=_time_is_estimate(reason)))
    # Сколько подмен — считает код по названным окнам; цифра ИИ может только
    # дополнить счёт, когда окон нет вовсе. Со второго прогона 24.09 модель
    # вернула subs_count=1 при ТРЁХ окнах подмены и трёх фамилиях в «фио на
    # подменах» — в бланке «Кол-во подмен» стояла единица рядом со списком из
    # трёх человек, то есть файл противоречил сам себе.
    if subs_n:
        r.subs_count = max(subs_n, r.subs_count or 0)
    if subs_h and not r.subs_hours:
        r.subs_hours = round(subs_h, 2)
    if fios and not r.subs_fio:
        r.subs_fio = ", ".join(dict.fromkeys(fios))
    # Навивка шпуль в минуты «машина на подмене» — простой станка (приказ
    # 29.09.2026 по ст.111 за 28.09). Идёт ДО именованного остатка и до окон
    # переписки: эти минуты названы самой машиной, а не «причиной не указана».
    _name_winding_on_submen_state(r, machine.get("section_text") or "",
                                  machine.get("machine"))
    # Что осталось от окон «стоп … пуск» без строки разбора — названный простой.
    _name_uncovered_log_windows(r, log_windows,
                                machine.get("section_text") or "",
                                machine.get("machine"))
    # Причина без времени, у которой счётчик стоит на месте, — простой с
    # минутами (приказ 29.09: «время брать можно по счётчикам»).
    _name_untimed_causes_by_counters(r, machine.get("section_text") or "",
                                     machine.get("machine"),
                                     elsewhere_ivs, untimed_naladka)


def _parallelize_shiftlong_swaps(r: ShiftMachineReport) -> None:
    """Сменная подстановка бобин при работающем по счётчику станке.

    Правило пользователя 03.09.2026 ставит станок в стоп на время подстановки
    бобин и подмены шпулярника. Но мастера иногда пишут такую работу ОДНОЙ
    записью на всю смену («замена шпулярника на протяжении всей смены» —
    реальные ст.98 за 27.08, 31.08 и 01.09), а счётчик показывает, что машина в
    это время крутилась. Положить эти часы в простой нельзя: 12 ч простоя плюс
    10 ч работы по счётчику дают ложное превышение на 10 ч и ломают эталон
    пользователя (ст.98: 11,82 ч за 27.08 и 11,43 ч за 01.09).

    Поэтому такая запись остаётся ПАРАЛЛЕЛЬНОЙ работой (бобины подставляли на
    ходу), а бот говорит об этом словами — решение за пользователем. Условие
    узкое: запись одна не влезает в 12 ч смены вместе с работой по счётчику.
    Короткие подстановки бобин (обычный случай) идут в простой как есть.

    То же и для записи, где рядом с операцией стоит слово «чинка» (правило А:
    чинка = станок стоит). Короткая чинка с названным временем («10:36 чинка,
    10:39 завершена») в это условие не попадает и остаётся простоем. А фон на
    всю смену — «замена шпулярника и чинка в течении всей смены» (ст.91 за
    24.09: 12 ч при 7,22 ч работы по счётчику, в переписке «7:00 машина в
    работе», «13:10 пуск машины», «14:10 пуск машины») — остановом быть не
    может: станок не может стоять 12 ч и одновременно выдать узлы на 7,22 ч.
    """
    work = r.work_hours
    if work <= TOLERANCE_H:
        return
    for i, s in enumerate(list(r.tech_stops)):
        if s.elsewhere or s.hours <= 0.01:
            continue
        # Отдельный случай: запись помечена параллельной (kind «работа»), но
        # слово «чинка» в machine_stopped перекрывает этот флаг, и станок всё
        # равно стоит на 12 ч — такое окно ещё разбирается.
        if s.is_parallel and not s.machine_stopped:
            continue
        if not is_swap_stop(s.reason):
            # Подмена шпулярника/подстановка бобин — описанный выше случай. Но
            # то же противоречие даёт чинка «в течении всей смены» без слова про
            # шпулярник: со второго прогона ИИ разбил строку мастера на две
            # записи, и вторая — «чинка в течении всей смены» (ст.91 за 24.09).
            # Короткая чинка с названным временем («10:36 чинка, 10:39
            # завершена») под это условие не попадает: окно меньше смены.
            if not (_REPAIR_RE.search(s.reason or "")
                    and _WHOLE_SHIFT_RE.search(s.reason or "")):
                continue
        if s.hours + work <= MACHINE_SHIFT_HOURS + TOLERANCE_H:
            continue
        r.tech_stops[i] = replace(s, is_parallel=True, shiftlong_parallel=True,
                                  label_override=(s.reason or "").strip() or None)
        r.warnings.append(
            f"«{(s.reason or '').strip()}» записано на {_fmt_h(s.hours)} ч, а "
            f"станок по счётчику работал {_fmt_h(work)} ч — вместе это больше "
            f"12 ч смены. Поэтому эта работа оставлена ПАРАЛЛЕЛЬНОЙ (бобины "
            f"подставляли на ходу), а не простоем станка. Если машина в это "
            f"время стояла — пришлите время остановки")


# «Связан 1 срез из 3», «Довязан 2 срез из 3», «срезан 3 срез» — завершённый срез.
_CUT_DONE_RE = re.compile(r"(?:связан|довязан|извязан|срезан)[а-яё]*\s*\d*\s*срез",
                          re.IGNORECASE)


def _is_cut_report(ev: dict) -> bool:
    """Это ОТМЕТКА о связанном срезе, а не останов станка.

    Мастера пишут срез одной точкой с показанием счётчика: «Связан 1 срез из 3,
    1350 узл. Общ. сч:297413» — это отчёт о готовом срезе, а не останов: счётчик
    доказывает, что до этого момента машина вязала. Дотяжка такой записи до
    следующего события превращает время работы в простой: прогон 21.09.2026,
    ст.251 — «связан 1 срез» (12:16) дотянули до 15:17, получили 3,02 ч простоя
    «срезы», хотя между счётчиками 297413 и 298764 лежат 1351 узел = 3,06 ч
    РАБОТЫ (норма 7,35 узл/мин). Итог — станок 13,81 ч из 12 ч и «!!! РАСХОЖДЕНИЕ»
    без вины мастера.

    Признак узкий намеренно: причастие завершённого среза + число узлов или
    показание счётчика в той же записи. Запись со словом про останов
    («стоп машина, срез узлов, замена телег») остаётся простоем и дотягивается
    как раньше.
    """
    low = (ev.get("reason") or "").lower()
    if not _CUT_DONE_RE.search(low):
        return False
    if any(m in low for m in _STOP_TEXT_MARKERS):
        return False
    return "узл" in low or "сч" in low


def _chain_half_intervals(events: List[dict]) -> List[dict]:
    """Достроить полуинтервалы: событие с одним временем получает второе.

    Модель возвращает «start 07:10, end null», когда мастер написал «7:10
    продолжаю навивку шпуль» и не назвал конец — но конец есть у СЛЕДУЮЩЕЙ
    записи («Пуск в 9:00»). Без достройки такие события уходят в «время не
    указано», и у станка появляется гигантский безымянный простой, а у
    оператора — часы без причины.

    Прогон 14.09.2026, ст.151: 5 событий со start без end и 2 с end без start
    → 11,25 ч в строке «простой — время не указано у причин», а в эталоне
    пользователя на том же месте стоят названные причины: наладка 2,08 ч,
    срез 0,17 ч, чинка 0,33 ч.

    Ничего не выдумываем: берутся ТОЛЬКО времена, которые модель уже вернула в
    соседних событиях (по порядку следования в переписке). Если соседей нет —
    событие остаётся как есть и честно попадёт в «время не указано».

    Отчёт о связанном срезе не дотягиваем вообще — см. _is_cut_report.
    """
    if not events:
        return events
    fixed: List[dict] = [dict(ev) for ev in events]
    changed = False
    # Достраиваем ТОЛЬКО конец события от начала следующего. Обратное
    # («начало от конца предыдущего») НЕ делаем: предыдущая запись обычно
    # описывает РАБОТУ машины («7:10 продолжаю навивку шпуль, машина в
    # работе»), и приписать следующему останову её начало — значит заявить,
    # что станок стоял всё это время. Прогон 14.09.2026, ст.151: так «Стоп
    # машина, срез узлов, замена телег, пуск в 9:00» превратился в останов
    # 07:10–09:00 (1,83 ч) при эталонных 0,17 ч, а оператор получил 14,46 ч
    # вместо 11,25. Лучше честное «время не указано», чем выдуманная цифра.
    # Проход назад: событие без end получает start СОСЕДНЕГО события.
    # Перескакивать через события без времени нельзя: иначе «16:07 стоп машина,
    # обрыв нити» растягивался до 19:00 через два безвременных события и давал
    # оператору 2,88 ч выдуманной работы (прогон 14.09.2026, ст.151).
    for i in range(len(fixed) - 1):
        ev = fixed[i]
        nxt = fixed[i + 1]
        if ev.get("start") and not ev.get("end") and nxt.get("start") \
                and not _is_cut_report(ev):
            a = _time_to_min(ev.get("start"))
            b = _time_to_min(nxt.get("start"))
            if a is not None and b is not None and b >= a:
                ev["end"] = nxt["start"]
                # Пометка: конец ВЗЯТ НЕ из слов мастера, а у соседней записи.
                # По паре «стоп … пуск» (_log_state_times) его можно продлить до
                # фактического пуска машины.
                ev["_end_chained"] = True
                changed = True
    return fixed if changed else events


def _line_zero_output(ln) -> bool:
    """Оба показания есть, но равны: счётчик не сдвинулся ⇒ 0 узлов, 0 часов."""
    return (ln.counter_start is not None and ln.counter_end is not None
            and ln.counter_start == ln.counter_end)


def _line_produced(ln) -> bool:
    """Есть ли у строки собственные узлы (конец больше начала)."""
    return (ln.counter_start is not None and ln.counter_end is not None
            and ln.counter_end > ln.counter_start)


def _drop_uncountered_lines(r: ShiftMachineReport) -> None:
    """Убрать строку ассортимента без показаний счётчика, если есть другая строка.

    Так ИИ превращает план в факт: прогон 22.09.2026, ст.151 — вторая строка
    «187х3-51-250,5, заявка 18.09.2026» без счётчиков (станок на этот
    ассортимент ещё не переводили), и в таблицу легла строка 12 без номера
    станка. Часов и выпуска у такой строки нет в принципе, а карточка
    действующего задания остаётся в первой строке.

    Тем же рядом приходит и метка перехода с ДВУМЯ ОДИНАКОВЫМИ показаниями
    (22.09 при пересборке 24.09.2026: «187х3-51-250,5 … 790782 → 790782»).
    Так станок передают на новый ассортимент: счётчик на границе записан, но
    ещё не двигался. Нули в строке выпуска и времени человек читает как
    «станок столько не сделал», поэтому ряд убираем так же, как плановый.
    Ни там, ни там строка не должна исчезать, если весь станок стоял: когда
    движется нечего, единственная запись о станке и есть эта строка.
    """
    if len(r.lines) < 2:
        return
    if not any(ln.counter_start is not None or ln.counter_end is not None
               for ln in r.lines):
        return
    moved = [ln for ln in r.lines if _line_produced(ln)]
    if not moved:
        return
    rest = [ln for ln in r.lines
            if ln.counter_start is not None or ln.counter_end is not None]
    gone = [ln for ln in r.lines if ln not in rest]
    for ln in [ln for ln in rest if _line_zero_output(ln)]:
        rest.remove(ln)
        gone.append(ln)
    if not gone:
        return
    r.lines = rest
    for ln in gone:
        title = (f"Строка «{ln.assortment or 'без ассортимента'}»"
                 f"{(' (заявка ' + str(ln.order_no) + ')') if ln.order_no else ''} ")
        if _line_zero_output(ln):
            why = (f"убрана: счётчик на ней не сдвинулся "
                   f"({ln.counter_start} → {ln.counter_end}), выпуска и времени "
                   f"у неё нет — это граница перехода, а не работа смены")
        else:
            why = ("убрана: показаний счётчика по ней нет, выпуска за смену она "
                   "не дала — это план перехода, а не работа смены")
        r.warnings.append(title + why)


# Заявка в переписке пишется номером СРАЗУ с датой: «Склад 49-24.08.26» — это
# заявка №49 от 24.08.2026. Разбор ИИ по этому полю отдаёт то обрывок («49-24»,
# прогон 27.09.2026, ст.98), то только номер («49», прогон 26.09.2026, ст.98).
# Номер с датой склеены дефисом, а части даты разделены точками — такой
# порядок в теме станка и читаем; вершину числа проверяем по календарю.
_ORDER_WITH_DATE_RE = re.compile(r"(?<![\d.,\-])(\d{1,3})-(\d{1,2})\.(\d{1,2})\.(\d{2,4})")

# Цикл среза: «Ср сч. 1450Уз из 1450уз», «Срезовой:0 из 760», «502 узлов из 730».
# Правое число — сколько узлов machine делает на ОДИН срез; на нём и проверяем
# количество срезов смены (см. _cuts_from_counter).
_SLICE_CYCLE_RE = re.compile(
    r"(?<![\d.])(\d{3,5})\s*(?:уз(?:лов)?(?:\.|\s|-)?)?\s*из\s*(\d{3,5})",
    re.IGNORECASE)


def _split_order_with_date(order_no, text: str):
    """Разклеить заявку «49-24.08.26» на (№ 49, дата 24.08.2026, фрагмент текста).

    Возвращает None, если в переписке станка такого склеенного номера нет:
    выдумывать дату по одному лишь номеру нельзя, её мастер не называл.
    Год из двух цифр дописываем до четырёх (все смены проекта — 20xx).
    """
    number = str(order_no or "").strip().replace(" ", "")
    if not number or not text:
        return None
    for m in _ORDER_WITH_DATE_RE.finditer(text):
        num, day, month, year = m.groups()
        if not (1 <= int(day) <= 31 and 1 <= int(month) <= 12):
            continue
        frag = m.group(0)
        # Стык с тем, что отдала модель: она могла обрезать дату («49-24»),
        # отдать только номер («49») или принести фрагмент целиком. Считать
        # этой же заявкой другое число нельзя: общий начало только до
        # границы разряда («4» — не начало «49»).
        shorter, longer = ((number, frag) if len(number) <= len(frag)
                          else (frag, number))
        if not longer.startswith(shorter):
            continue
        tail = longer[len(shorter):]
        if tail and tail[0].isdigit():
            continue
        y = year if len(year) == 4 else "20" + year.zfill(2)
        return num, f"{day.zfill(2)}.{month.zfill(2)}.{y}", frag
    return None


# ——— Колонка D: полотно смены, а не нитки со шпулярника ———
#
# Прогон 27.09.2026, ст.151: станок весь день был в службе наладки и
# заправлялся новой нитью. Единственное «название» в теме — «Шпули и шпулярник
# поменены на НПА187х3». Разбор положил эту строку в assortment, и в бланк
# поехало «НПА187х3»: читается как «станок вязал НПА187х3», хотя это СЫРЬЁ,
# поставленное на шпулярник, а полотно смены мастер в тот день не называл.
#
# Снимаем строку только когда КАЖДАЯ её встреча в теме станка стоит сразу после
# фразы про замену (шпули/шпулярник/бобины/нити … поменены/заменены/установлены/
# настроены на …). Молча ничего не делаем: заметка уходит в ответ словами.
#
# Обратный случай — слово мастера «ассортимент»: прогон 14.09.2026, ст.251,
# «Шпульный стол на ассортимент НПА 187х3х2 настроен». Там НПА 187х3х2 и есть
# то, на что станок перенастроили, и строку не трогаем.

_SEP = r"[\W_]*"

# Фраза про замену ниток: объект (шпули/шпулярник/бобины/нити) → глагол замены
# → «на», после которого и идёт название нитки. Привязана к концу текста, то
# есть к месту, где стоит само название.
_SWAP_RAW_RE = re.compile(
    rf"(?:шпулярник|шпул\w*|бобин\w*|нит\w*){_SEP}(?:\w+{_SEP}){{0,6}}?"
    rf"(?:помен\w*|замен\w*|смен\w*|установл\w*|заправл\w*|настроен\w*|"
    rf"настроил\w*|перевед\w*)(?:{_SEP}на)?{_SEP}$", re.IGNORECASE)


def _compact(s) -> str:
    """Строка «как слышится»: буквы и цифры, без пробелов и разметки выгрузки.

    «187*3», «187×3» и «187 х 3» должны встречаться на одном и том же шаблоне.
    """
    out = str(s or "").lower().replace("ё", "е")
    for ch in ("×", "*", "х", "x", "✕"):
        out = out.replace(ch, "х")
    return re.sub(r"[^a-zа-я0-9]", "", out)


def _thread_swap_only(assortment, text: str) -> Optional[str]:
    """Назван ли ассортимент в теме ТОЛЬКО как нитки, поставленные на станок.

    Возвращает фразу замены (для заметки словами) либо None — если строку в
    теме нет вовсе (проверить нечем), если хоть одна её встреча стоит вне
    фразы про замену, или если мастер сам назвал её ассортиментом.
    """
    if not assortment or not text:
        return None
    chars = _compact(assortment)
    if len(chars) < 4:
        return None
    pattern = _SEP.join(re.escape(c) for c in chars)
    hits = list(re.finditer(pattern, text, re.IGNORECASE))
    if not hits:
        return None
    for m in hits:
        before = text[:m.start()]
        swap = _SWAP_RAW_RE.search(before)
        if not swap or "ассортимент" in before[swap.end():].lower():
            return None
        phrase = swap.group(0).strip()
    return phrase or None


def _drop_thread_swap(machine: dict, r: "ShiftMachineReport", raw):
    """Убрать из колонки D нитки со шпулярника; вернуть то, что писать в клетку."""
    phrase = _thread_swap_only(raw, machine.get("section_text") or "")
    if not phrase:
        return raw
    r.warnings.append(
        f"ассортимент: «{raw}» — в теме это нитки, которые поставили на станок "
        f"(«{phrase}»), а не полотно смены. Само полотно мастер не называл, "
        "поэтому колонка D осталась пустой")
    return None


def _cuts_from_counter(r: "ShiftMachineReport", text: str) -> None:
    """Проверка «Кол-во срезов» (K) по счётчику и по словам мастера.

    Разбор берёт срезы из первой попавшейся сводки, а первая сводка в теме —
    УТРЕННЯЯ, то есть состояние станка на приёмку, а не работа смены. Прогон
    27.09.2026, ст.98: «1 Ср. Из 4 срезов» из утреннего блока дало в K четвёрку,
    хотя оператор записала вечерний итог «7 ср» (в ручном отчёте владельца тоже
    7).

    Меняем ТОЛЬКО когда согласуются два независимых доказательства:
    1) выпуск смены делится на цикл среза (узлов на срез из «N из M» той же
       темы) без остатка — это арифметика счётчика;
    2) это же число мастер назвал словами («7 ср», «Всего 8 срезов»).
    Не согласуются — оставляем то, что принёс разбор: срезы выдумывать нельзя.
    """
    if not text or not r.lines:
        return
    output = sum(ln.output or 0 for ln in r.lines)
    if output <= 0:
        return
    clean = text.replace("_", "").replace("*", "")
    for cycle in sorted({int(m.group(2)) for m in _SLICE_CYCLE_RE.finditer(clean)}):
        cuts = output / cycle
        if abs(cuts - round(cuts)) > 1e-9 or not (0 < round(cuts) <= 60):
            continue
        cuts = round(cuts)
        # «7 ср» / «7 срезов», но НЕ «7 ср.сч.» — там семикратный срезовой
        # счётчик, а не семь срезов.
        stated = [m for m in re.finditer(
            rf"(?<![\d.,]){cuts}[\s.:-]*ср[а-яё]*", clean, re.IGNORECASE)
            if not re.match(r"\s*[.,]?\s*с[чх]", clean[m.end():m.end() + 6])]
        if not stated or r.cuts == cuts:
            return
        old = r.cuts
        r.cuts = cuts
        r.warnings.append(
            f"срезы: в колонку K шло {cuts}, а разбор принёс {old} — число "
            f"взято не из сводки, а из счётчика: {int(output)} узлов / {cycle} "
            f"узлов на срез = ровно {cuts}, и «{cuts} ср» мастер называет в той "
            f"же теме. Утренняя сводка описывает станок на приёмку, а не "
            f"работу смены")
        return


def build_shift_report_from_machine(machine: dict,
                                    date: Optional[str] = None) -> ShiftMachineReport:
    machine = dict(machine)
    # Полуинтервалы достраиваются ДО разбора событий (см. _chain_half_intervals).
    machine["events"] = _chain_half_intervals(machine.get("events") or [])
    r = ShiftMachineReport(
        machine=machine.get("machine"),
        operator=machine.get("operator"),
        # Марка станка: в переписке её не называют НИ РАЗУ, и разбор ИИ по этому
        # полю всегда молчит. Пустая колонка C в таблице читалась как «нет данных
        # по станку», хотя счётчики и выпуск стоят полные. Берём марку из
        # справочника парка (services/machine_rates.json), если ИИ ничего не нашёл.
        brand=machine.get("brand") or machine_rates.get_brand(machine.get("machine")),
        date=machine.get("date") or date,
        cuts=machine.get("cuts"),
        subs_count=machine.get("subs_count"),
        subs_hours=_to_float(machine.get("subs_hours")) or 0.0,
        subs_fio=machine.get("subs_fio"),
        operator_shift_end=machine.get("operator_shift_end"),
        operator_norm_hours=_to_float(machine.get("operator_norm_hours")),
        operator2=machine.get("operator2"),
        operator2_start=machine.get("operator2_start"),
        operator_start=machine.get("operator_start"),
        first_info_time=machine.get("first_info_time"),
    )
    # Передача смены: если оператор сдал станок и ушёл, а конец его смены явно
    # не задан — концом считаем момент передачи (дальше станок ведёт принявший).
    if r.has_handover and not (r.operator_shift_end or "").strip():
        r.operator_shift_end = r.operator2_start
    for ln in machine.get("lines") or []:
        split = _split_order_with_date(ln.get("order_no"),
                                       machine.get("section_text") or "")
        if split:
            number, order_date, frag = split
            r.warnings.append(
                f"заявка: в теме станка написано «{frag}» — разбили на "
                f"№{number} и дату заявки {order_date} "
                f"(колонки G и H в таблице)")
        r.lines.append(ProductLine(
            assortment=_drop_thread_swap(machine, r, ln.get("assortment")),
            client=ln.get("client"),
            order_no=split[0] if split else ln.get("order_no"),
            order_date=split[1] if split else None,
            panels=ln.get("panels"),
            counter_start=_to_float(ln.get("counter_start")),
            counter_end=_to_float(ln.get("counter_end")),
            counter_start_mid_shift=bool(ln.get("counter_start_mid_shift")),
        ))
    # Если ИИ отдал счётчики прямо на машине (одна строка) — поддержим и это.
    if not r.lines and (machine.get("counter_start") or machine.get("counter_end")):
        split = _split_order_with_date(machine.get("order_no"),
                                       machine.get("section_text") or "")
        r.lines.append(ProductLine(
            assortment=_drop_thread_swap(machine, r, machine.get("assortment")),
            client=machine.get("client"),
            order_no=split[0] if split else machine.get("order_no"),
            order_date=split[1] if split else None,
            counter_start=_to_float(machine.get("counter_start")),
            counter_end=_to_float(machine.get("counter_end")),
        ))
    _drop_uncountered_lines(r)
    _cuts_from_counter(r, machine.get("section_text") or "")
    r.tech_stops = _parse_tech_stops(machine)
    _events_to_stops_and_subs(machine, r)
    # Правило 03.09.2026 (бобины/шпулярник) — станок стоит. Исключение только
    # для записи «на протяжении всей смены» при работающем счётчике, см. функцию.
    _parallelize_shiftlong_swaps(r)
    # Станок, про который в теме осталась только фраза «в стопе до <дата>»:
    # смену закрываем ею, а не молчаливыми пустыми клетками (см. функцию).
    _horizon_stop_from_topic(machine, r)
    # Передача смены: принявший станок ведёт его до конца смены. Его часы
    # (присутствие от передачи до 19:00 минус обед) — работа привлекаемого
    # персонала. Добавляем одной строкой, чтобы не потерять человека и чтобы
    # хвост станка не считался «отсутствием оператора» (см. absence_after_shift).
    if r.has_handover and r.operator2_hours > 0.01:
        r.attracted.append(TechStop(
            r.operator2_hours,
            f"принял станок в {r.operator2_start}, работа/контроль за станком "
            f"до конца смены",
            operator_active=False,
            performer=r.operator2))
    if r.naladka_all_shift:
        # Остаток смены добирается ONE строкой «наладка (весь день)», и это
        # закрывает день СТАНКА, а не часы человека.
        #
        # Обед (45 мин) занимает место в смене только когда на станке был
        # кто-то, поэтому без фамилии наладка закрывает все 12 ч.
        #
        # Раньше при названном операторе остаток шёл как его работа
        # (operator_active=True) и ровно добивал смену до 11,25 ч — приказ
        # владельца от 28.09.2026 это запрещает: «не нужно их добивать до
        # 11,25, если не хватает или переизбыток, то оставляй как есть». Плюс
        # наладка — время службы наладки, а не оператора (правило Г от
        # 03.09.2026, эталон 01.09 ст.121 в test_shift_0309_operator): часы
        # станка в наладке уже показаны в его простое.
        no_op = not (r.operator or "").strip()
        target = MACHINE_SHIFT_HOURS if no_op else round(
            MACHINE_SHIFT_HOURS - r.lunch_in_downtime, 2)
        covered = sum(s.hours for s in r.tech_stops if not s.elsewhere)
        remainder = round(target - covered, 2)
        if remainder > 0.01:
            r.tech_stops.append(TechStop(remainder, "наладка (весь день)",
                                         operator_active=False))
    if r.no_operator_all_shift:
        # Машина весь день без оператора (инженерная служба или очередь на
        # наладку): счётчик не нужен, часы закрыты одной строкой простоя.
        # Лишние предупреждения про счётчик тут только мешают.
        return r
    if r.rate is None:
        r.warnings.append(
            f"Нет нормы выработки для станка {r.machine} — добавьте его в "
            "machine_rates.json, иначе время работы не посчитать")
    if r.counters_missing:
        r.warnings.append(
            "В переписке нет пары показаний общего счётчика (начальное и "
            "конечное) — время работы станка посчитать нельзя")
    else:
        for ln in r.lines:
            if ln.counter_start is None and ln.counter_end is not None:
                r.warnings.append(
                    f"Нет НАЧАЛЬНОГО показания счётчика для «"
                    f"{ln.assortment or 'строка без ассортимента'}» "
                    f"(есть только {_fmt_int(ln.counter_end)}) — эта работа в "
                    "часы не попала, отсюда возможен ложный недостаток")
            elif ln.counter_end is None and ln.counter_start is not None:
                r.warnings.append(
                    f"Нет КОНЕЧНОГО показания счётчика для «"
                    f"{ln.assortment or 'строка без ассортимента'}» "
                    f"(есть только {_fmt_int(ln.counter_start)}) — эта работа "
                    "в часы не попала, отсюда возможен ложный недостаток")
    for ln in r.lines:
        if ln.counter_start_mid_shift and ln.counter_start is not None:
            r.warnings.append(
                f"Первое показание счётчика ({_fmt_int(ln.counter_start)}) взято "
                f"из СЕРЕДИНЫ смены — на 07:00 в переписке его нет. Время работы "
                f"станка занижено: сверьте начальное показание по журналу")
    if r.naladka_test_run_cut > 0.01:
        r.warnings.append(
            f"Со строки «наладка/переналадка» снято {_fmt_h(r.naladka_test_run_cut)} ч: "
            f"внутри окна наладки станок крутился {_fmt_h(r.work_hours)} ч по "
            f"счётчику (пробные узлы наладчика), и туда же попадает обед. "
            f"Время работы станка оставлено как есть, смена сходится к 12 ч")
    if r.untimed_stops:
        r.warnings.append(
            f"Остановок без времени: {len(r.untimed_stops)} — мастер написал "
            "причину, но не указал начало и конец, поэтому эти часы не "
            "разложены по причинам (отсюда возможен «недостаток времени»)")
    if r.first_info_time and not r.operator_start:
        # Правило пользователя 03.09.2026: смена у всех с 07:00. Пустое начало
        # смены по станку — это простой «отсутствие оператора». Но если баланс
        # станка уже закрыт (data_gap_before_shift == 0), часы не выдумываем и
        # говорим словами, что расхождение — в записи, а не в работе.
        gap = r.data_gap_before_shift
        late = r._hhmm_to_span(r.first_info_time) or 0.0
        if gap > 0.01:
            r.warnings.append(
                f"Первая информация по станку — {r.first_info_time}, а смена "
                f"начинается в 07:00: {_fmt_h(gap)} ч "
                f"({_fmt_hm(gap)}) отнесены в простой станка как отсутствие "
                f"оператора. Если оператор был на месте с 07:00, значит за этот "
                f"час в переписке просто нет сообщений")
        elif late > TOLERANCE_H:
            r.warnings.append(
                f"Первая информация по станку — {r.first_info_time}, а смена "
                f"начинается в 07:00, но в 12 ч смены свободного времени нет: "
                f"работа по счётчику и названные простои уже закрыли смену. "
                f"Отсутствие оператора за начало смены НЕ начислено — сверьте, "
                f"кто вёл станок до {r.first_info_time}")
    if (r.machine_shortfall and r.operator_shift_span < MACHINE_SHIFT_HOURS
            and r.operator_shift_end):
        r.warnings.append(
            f"Смена оператора закончилась в {r.operator_shift_end}, а норма "
            f"станка — 12 ч (07:00–19:00). Часть недостатка может быть просто "
            f"отсутствием сообщений за конец смены — проверьте, кто вёл станок "
            f"после {r.operator_shift_end}")
    return r


def _rows_from_foreign_topic(other: "ShiftMachineReport") -> List["TechStop"]:
    """Строки чужого станка, которые может принести его «гость».

    Это ВЕСЬ список исполнителей, которых станок показал как не своих, а не
    только его простой: `attracted_own` — остановки станка, а работа, записанная
    в чужой теме как операция при стоящем (или без счётчика) станке, лежит в
    `attracted`. Приказ владельца от 30.09.2026 (вопрос №135, дословно): «брать
    строки оператора можно в чужих темах» — «вот это делай».

    `attracted_all()`, а не сырые списки: там уже сняты строки-состояния «вся
    смена» без подтверждения времени (правило 01.09 про Каленюка) и выдуманные
    фамилии (25.09, «Рыбин»). `transferred` не берём: это часы ЧУЖОГО ухода, они
    уже стоят в блоке того станка, откуда человек пришёл.
    """
    return [s for s in other.attracted_all() if not s.transferred and s.hours]


def build_shift_reports_from_structured(data: dict) -> List[ShiftMachineReport]:
    """Собрать отчёты по всем станкам из структуры, извлечённой из переписки."""
    date = data.get("date")
    reports = [build_shift_report_from_machine(m, date)
               for m in data.get("machines", [])]
    # Перенос привлечённого персонала: если оператор станка A ушёл работать
    # (подмена/наладка) на станок B, то на станке B это работа привлечённого
    # персонала. Часы там же остаются простоем/отсутствием для станка A (п.2).
    by_num: dict = {}
    for r in reports:
        key = machine_rates._norm_key(r.machine)
        if key:
            by_num[key] = r
    for r in reports:
        for s in r.tech_stops:
            if s.elsewhere and s.other_machine:
                tgt = by_num.get(machine_rates._norm_key(s.other_machine))
                if tgt is not None and tgt is not r:
                    who = (s.performer or r.operator
                           or f"оператор ст. {r.machine}")
                    # Если ушедший — сам ОПЕРАТОР целевого станка (провёл там
                    # всю смену, эталон 26.08: Камбаров с 321 весь день на 251),
                    # то его часы там УЖЕ учтены как работа оператора. Второй
                    # раз в привлечённый персонал не добавляем — иначе задвоение.
                    if _same_person(who, tgt.operator) or \
                            _same_person(who, tgt.operator2):
                        continue
                    tgt.attracted.append(TechStop(
                        s.hours, s.reason or "подмена", performer=who,
                        transferred=True))
    # Уточняем «полное отсутствие»: часы оператора НЕ засчитываются только
    # тогда, когда он ушёл на станок, где сам является штатным оператором —
    # там эти часы уже посчитаны (26.08: Камбаров с 321 весь день на 251).
    # Если на целевом станке оператор другой (или его нет вовсе — станок у
    # инженерной службы, как 111 за 27.08), то человек РАБОТАЛ, и часы идут в
    # его время: правило пользователя «помощь этого оператора на других станках
    # тоже идёт во время работы оператора» (эталон 251: «работа на машине
    # №111 1,67»).
    by_key = {}
    for r in reports:
        key = machine_rates._norm_key(r.machine)
        if key:
            by_key[key] = r
    for r in reports:
        op = (r.operator or "").strip()
        for s in r.tech_stops:
            if not s.elsewhere:
                continue
            key = machine_rates._norm_key(s.other_machine or "")
            tgt = by_key.get(key) if key else None
            same = bool(tgt is not None and op and (
                _same_person(op, tgt.operator)
                or _same_person(op, tgt.operator2)))
            who = (s.performer or "").strip()
            if same and (not who or _same_person(who, op)) and \
                    key not in r.absence_credited_machines:
                # Человек — штатный оператор целевого станка: его часы там и
                # считаются. Именно это обещает строка отсутствия.
                r.absence_credited_machines.append(key)
            if s.full_absence and not same:
                s.full_absence = False
    # Зеркальный дубль: событие «ушёл на подмену на 151 машину / пришёл с
    # подмены» описано с точки зрения ДРУГОГО станка, но ИИ приписал его самому
    # станку 151 да ещё и другим именем (прогон 27.08: «Олег — ушёл на подмену
    # шпулярника на 151 машину» рядом с «Петровский — замена шпулярника, 58
    # бабин» — один и тот же человек и одно и то же дело, 2,5 ч дважды).
    # Признак жёсткий: причина ГОВОРИТ об уходе/приходе и называет НОМЕР ЭТОГО
    # ЖЕ станка, а исполнитель — не штатный оператор станка. Это удаление
    # повтора, а не подгонка времени.
    for r in reports:
        key = machine_rates._norm_key(r.machine)
        if not key:
            continue
        keep = []
        for s in r.tech_stops:
            if _is_mirrored_arrival(s, r, key):
                continue
            keep.append(s)
        r.tech_stops = keep
        r.attracted = [s for s in r.attracted
                       if not _is_mirrored_arrival(s, r, key)]
    # Слово мастеру про имя, которое ДОШЛО до отчёта: модель назвала человека,
    # которого в переписке этого станка нет, — строка вышла ролью, часы
    # остались станку. Про имена, которые фильтр выше снял как пересказ чужой
    # темы, не предупреждаем: 25.09, ст.251 — «Петровский ушёл на 251» в
    # зеркале, а его честная строка пришла на 251 переносом с 321.
    for r in reports:
        for s in list(r.attracted) + list(r.tech_stops):
            if not s.performer_claimed:
                continue
            msg = (f"исполнитель «{s.performer_claimed}» ни в причине записи, "
                   f"ни в переписке станка №{r.machine} не назван — в отчёте "
                   f"он показан как «{_unproven_role(s.is_naladka)}», часы "
                   "остались станку; проверьте, кто делал эту работу")
            if msg not in r.warnings:
                r.warnings.append(msg)
    # Обратный перенос: работа НАШЕГО оператора, записанная по ЧУЖОМУ станку.
    # Если на станке B в событии указан performer, который является оператором
    # станка A («замена шпулярника на 151: Камбаров 58 бабин», Камбаров —
    # оператор 251), то эти часы обязаны попасть в РАБОТУ ОПЕРАТОРА станка A
    # (эталон 27.08: в блоке 251 «работа на машине №151 2,5»; в блоке 321
    # «работа на машине №151 2,5»). Иначе у человека возникает ложный
    # недостаток времени, хотя он всю смену работал.
    for r in reports:
        op = (r.operator or "").strip()
        if not op or r.engineering_all_shift:
            continue
        # На какие станки уход уже учтён своими событиями — второй раз не берём.
        seen = {machine_rates._norm_key(m) for m in r.operator_elsewhere_machines}
        for other in reports:
            if other is r:
                continue
            key = machine_rates._norm_key(other.machine)
            if key and key in seen:
                continue
            # Источник — весь список чужих исполнителей станка, а не только его
            # простой (см. `_rows_from_foreign_topic`, приказ №135 от 30.09.2026).
            for s in _rows_from_foreign_topic(other):
                if not _same_person(s.performer, op):
                    continue
                label = f"{ELSEWHERE_WORK_LABEL}{other.machine}"
                reason = (f"{label} ({s.reason})" if s.reason else label)
                # Минуты окна едут вместе с часами: без них одно и то же время,
                # описанное в двух темах, сложилось бы в сумму (чинка на 111
                # 13:22–15:59 и подвязка на 121 14:20–16:40 дали бы 4,95 ч там,
                # где человек физически был 3,6 ч). С окном работает
                # `_squeeze_time_overlaps`: общие минуты остаются у более ранней
                # строки, и слагаемые блока по-прежнему складываются в итог.
                r.elsewhere_extra.append(TechStop(
                    s.hours, reason, performer=op,
                    start_min=s.start_min, end_min=s.end_min,
                    label_override=label))
    # Один человек — ОДИН отчёт, куда идёт его работа на ЧУЖОМ станке. Если он
    # оператор нескольких станков (31.08: Вашурина записана и на 151, и на 121),
    # ОДНА И ТА ЖЕ поездка на №111 попадала в блок работы оператора ОБОИХ
    # станков: ст.121 показал «оператор Вашурина до 16:25 работала на 111м
    # 9,42 ч» и превышение +7,59 ч, хотя те же часы уже стоят в блоке 151 и в
    # простое машины 121 как отсутствие. Работа остаётся у станка, с которого
    # человек начал смену (нет operator_start → стоял с 07:00, иначе самый
    # ранний приход); на остальных его станках эта же поездка становится
    # ОТСУТСТВИЕМ — часы не теряются, они вычитаются из нормы (full_absence) и
    # видны в простое машины. Признак дубля жёсткий: у более раннего отчёта есть
    # уход на ТОТ ЖЕ станок. Иначе поломалась бы передача смены (25.08:
    # Арташина 321 → 151), где короткий уход с одного станка к другому
    # отношения не имеет.
    def _shift_start_rank(rep) -> tuple:
        return (rep.operator_start_span, str(rep.machine or ""))

    for r in reports:
        op = (r.operator or "").strip()
        if not op:
            continue
        earlier = [x for x in reports
                   if x is not r and _same_person(x.operator, op)
                   and _shift_start_rank(x) < _shift_start_rank(r)]
        if not earlier:
            continue
        for s in r.tech_stops:
            if not s.elsewhere or s.full_absence:
                continue
            tgt = machine_rates._norm_key(s.other_machine or "")
            if not tgt:
                continue
            if any(machine_rates._norm_key(o.other_machine or "") == tgt
                   for x in earlier for o in x.tech_stops if o.elsewhere):
                s.full_absence = True
        # Перенос «работа на машине №X» тоже должен остаться в одном отчёте.
        taken = {s.label for x in earlier for s in x.elsewhere_extra}
        r.elsewhere_extra = [s for s in r.elsewhere_extra
                             if s.label not in taken]
    # Станки, которые ИИ не разобрал (ai_extract кладёт их в data["not_parsed"]),
    # обязаны остаться в отчёте нулевой строкой с пометкой: молча пропавший
    # станок выглядит как простаивавший, а это потерянные цифры (прогон (8):
    # так исчез ст.98 с 10 ч работы).
    have = {machine_rates._norm_key(x.machine) for x in reports}
    for num in data.get("not_parsed") or []:
        if machine_rates._norm_key(num) in have:
            continue
        stub = build_shift_report_from_machine({"machine": num}, date)
        stub.not_parsed = True
        stub.warnings.append(
            f"станок №{num} есть в переписке, но ИИ не вернул по нему "
            f"разбор — цифры в отчёт не попали")
        reports.append(stub)
    return reports


def fill_park_machines(reports: List[ShiftMachineReport],
                       date: Optional[str] = None,
                       not_parsed: Optional[List[str]] = None
                       ) -> List[ShiftMachineReport]:
    """Дополнить список станками парка, о которых в переписке не было НИ СЛОВА.

    В эталонном файле пользователя такие станки (601, 14тр, 15тр) стоят в дне
    нулевыми строками с пометкой «нет данных», а не пропадают из отчёта —
    правило пользователя 28.08 «пиши с нулевыми строками их». Список парка —
    справочник норм T (`machine_rates.known_machines()`), туда ничего не
    придумывается.

    `not_parsed` — станки, которые В ПЕРЕПИСКЕ ЕСТЬ, но ИИ по ним ничего не
    вернул. Их нулевые строки помечаются отдельно: «нет данных» и «цифры
    потеряны» — это разные вещи, и вторую надо видеть сразу.

    Порядок: сначала станки, по которым данные есть (как пришли), потом
    недостающие по номеру. Ничего не считается и не добивается: у пустого
    станка нет счётчика, поэтому баланс времени не проверяется вообще.
    """
    have = {machine_rates._norm_key(r.machine) for r in reports}
    have.discard("")
    date = date or next((r.date for r in reports if r.date), None)
    lost = {machine_rates._norm_key(m) for m in (not_parsed or [])}
    lost.discard("")
    missing = [m for m in machine_rates.known_machines()
               if machine_rates._norm_key(m) not in have]
    # Станок из переписки может вообще не быть в справочнике норм — его тоже
    # нельзя молча терять.
    missing += [m for m in (not_parsed or [])
                if machine_rates._norm_key(m) not in have
                and machine_rates._norm_key(m)
                not in {machine_rates._norm_key(x) for x in missing}]

    def _num(m: str):
        digits = re.sub(r"\D", "", m)
        return (int(digits) if digits else 0, m)

    extra = []
    for m in sorted(missing, key=_num):
        rep = build_shift_report_from_machine({"machine": m}, date)
        if machine_rates._norm_key(m) in lost:
            rep.not_parsed = True
            rep.warnings.append(
                f"станок №{m} есть в переписке, но ИИ не вернул по нему "
                f"разбор — цифры в отчёт не попали")
        extra.append(rep)
    return list(reports) + extra

